ANSI_ESCAPE_RE = re.compile(r"\x1B\[[0-?]*[ -/]*[@-~]")
AUTO_LOCAL_PROPERTIES_HEADER = "\n".join(
    [
        "# This file is automatically generated by DevEco Studio.",
        "# Do not modify this file -- YOUR CHANGES WILL BE ERASED!",
        "#",
        "# This file should *NOT* be checked into Version Control Systems,",
        "# as it contains information specific to your local configuration.",
        "#",
        "# For customization when using a Version Control System, please read the header note.",
    ]
)


def parse_json5_text(text: str) -> Any:
    """
    Parse a subset of JSON5 suitable for Harmony ``build-profile.json5``:
    block comments ``/* */``, line comments ``//``, trailing commas.
    """
    out: list[str] = []
    i = 0
    in_string = False
    quote = ""
    escape = False
    while i < len(text):
        char = text[i]
        next_char = text[i + 1] if i + 1 < len(text) else ""
        if in_string:
            if escape:
                if quote == "'" and char == "'":
                    out.append("'")
                elif quote == "'" and char == '"':
                    out.append('\\"')
                else:
                    out.append("\\" + char)
                escape = False
            elif char == "\\":
                escape = True
            elif char == quote:
                in_string = False
                out.append('"')
            else:
                if quote == "'" and char == '"':
                    out.append('\\"')
                else:
                    out.append(char)
            i += 1
            continue
        if char in ("'", '"'):
            in_string = True
            quote = char
            out.append('"')
            i += 1
            continue
        if char == "/" and next_char == "/":
            i += 2
            while i < len(text) and text[i] not in "\r\n":
                i += 1
            continue
        if char == "/" and next_char == "*":
            i += 2
            while i + 1 < len(text) and not (text[i] == "*" and text[i + 1] == "/"):
                i += 1
            i += 2 if i + 1 < len(text) else 0
            continue
        out.append(char)
        i += 1
    stripped = "".join(out)
    for _ in range(32):
        next_text = re.sub(r",(\s*[\]}])", r"\1", stripped)
        if next_text == stripped:
            break
        stripped = next_text
    stripped = re.sub(r'([{\[,]\s*)([A-Za-z_$][\w$]*)(\s*:)', r'\1"\2"\3', stripped)
    return json.loads(stripped)


def _build_profile_declares_arkts_version(text: str, version: str) -> bool:
    try:
        data = parse_json5_text(text)
    except Exception:
        return bool(
            re.search(
                rf'(?:"arkTSVersion"|arkTSVersion)\s*:\s*["\']{re.escape(version)}["\']',
                text,
            )
        )
    return isinstance(data, dict) and data.get("arkTSVersion") == version


def _has_module_arkts_version(repo_dir: Path, version: str) -> bool:
    for profile in sorted(repo_dir.glob("*/build-profile.json5"), key=lambda p: str(p)):
        if not profile.is_file():
            continue
        try:
            text = profile.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        if _build_profile_declares_arkts_version(text, version):
            return True
    return False


def _coerce_sdk_version(value: Any) -> int | None:
    if value is None:
        return None
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        stripped = value.strip()
        if stripped.isdigit():
            return int(stripped)
        paren_match = re.search(r"\((\d+)\)", stripped)
        if paren_match:
            return int(paren_match.group(1))
    return None


def _read_build_profile_product_info(
    repo_dir: str | os.PathLike[str],
    *,
    product_name: str = "default",
) -> tuple[int | None, int | None, str, str | None]:
    root = Path(repo_dir).expanduser().resolve()
    profile = root / "build-profile.json5"
    if not profile.is_file():
        return None, None, product_name, None

    raw = profile.read_text(encoding="utf-8", errors="replace")
    data = parse_json5_text(raw)
    app = data.get("app") if isinstance(data, dict) else None
    if not isinstance(app, dict):
        return None, None, product_name, None

    products = app.get("products")
    if not isinstance(products, list) or not products:
        return None, None, product_name, None

    selected: dict[str, Any] | None = None
    for entry in products:
        if not isinstance(entry, dict):
            continue
        if entry.get("name") == product_name:
            selected = entry
            break

    if selected is None:
        first = products[0]
        selected = first if isinstance(first, dict) else None
        if selected and isinstance(selected.get("name"), str):
            product_name = selected["name"]

    if selected is None:
        return None, None, product_name, None

    compile_v = _coerce_sdk_version(selected.get("compileSdkVersion", app.get("compileSdkVersion")))
    compatible_v = _coerce_sdk_version(selected.get("compatibleSdkVersion", app.get("compatibleSdkVersion")))
    runtime_os = selected.get("runtimeOS", app.get("runtimeOS"))
    return compile_v, compatible_v, product_name, runtime_os if isinstance(runtime_os, str) else None


def read_build_profile_sdk_versions(
    repo_dir: str | os.PathLike[str],
    *,
    product_name: str = "default",
) -> tuple[int | None, int | None, str]:
    """
    Read ``build-profile.json5`` under ``repo_dir`` and return
    ``(compileSdkVersion, compatibleSdkVersion, matched_product_name)``.
    If the product is not found, uses the first product entry when present.
    """
    compile_v, compatible_v, used_product, _runtime_os = _read_build_profile_product_info(
        repo_dir,
        product_name=product_name,
    )
    return compile_v, compatible_v, used_product


def _candidate_openharmony_api_dirs(sdk_root: Path, api_level: int) -> list[Path]:
    level = str(api_level)
    return [
        path
        for path in (
            sdk_root / "default" / "openharmony" / level,
            sdk_root / "openharmony" / level,
            sdk_root / level,
        )
        if path.is_dir()
    ]


def _is_complete_sdk_component_root(path: Path) -> bool:
    return (
        path.is_dir()
        and (path / "toolchains").is_dir()
        and (path / "ets" / "oh-uni-package.json").is_file()
        and (path / "js" / "oh-uni-package.json").is_file()
    )


def resolve_sdk_api_slice_for_api(
    sdk_root: str | os.PathLike[str],
    api_level: int | None,
) -> Path:
    """
    Resolve the API-specific SDK slice for diagnostics.

    Example:
    - root ``C:\\...\\OpenHarmony\\Sdk`` + API ``12`` -> ``C:\\...\\OpenHarmony\\Sdk\\12``
    - already-sliced root ``C:\\...\\OpenHarmony\\Sdk\\12`` stays unchanged
    """
    resolved = Path(sdk_root).expanduser().resolve()
    if api_level is None:
        return resolved
    if _is_sdk_component_root(resolved):
        return resolved
    candidates = _candidate_openharmony_api_dirs(resolved, api_level)
    for candidate in candidates:
        if _is_sdk_component_root(candidate):
            return candidate.resolve()
    if candidates:
        return candidates[0].resolve()
    return resolved


def sdk_root_contains_openharmony_api(sdk_root: Path, api_level: int) -> bool:
    """Best-effort check that an API-level OpenHarmony SDK slice is installed under ``sdk_root``."""
    for path in _candidate_openharmony_api_dirs(sdk_root, api_level):
        if _is_complete_sdk_component_root(path):
            return True
    return False


def _first_installed_openharmony_api_at_least(sdk_root: Path | None, minimum_api: int) -> int | None:
    if sdk_root is None:
        return None
    roots: list[Path] = []
    try:
        roots.append(Path(sdk_root).expanduser().resolve())
    except OSError:
        return None
    for extra in ("default/openharmony", "openharmony"):
        roots.append(roots[0] / extra)

    found: set[int] = set()
    for root in roots:
        if not root.is_dir():
            continue
        for child in root.iterdir():
            if not child.is_dir() or not child.name.isdigit():
                continue
            api = int(child.name)
            if api >= minimum_api and _is_complete_sdk_component_root(child):
                found.add(api)
    return min(found) if found else None


def _legacy_complete_openharmony_roots(sdk_roots: list[Path], api_level: int | None) -> list[Path]:
    if api_level is None or api_level > 12:
        return []
    roots: list[Path] = []
    seen: set[str] = set()
    for root in sdk_roots:
        candidates = [root, root / "default" / "openharmony", root / "openharmony"]
        for candidate in candidates:
            try:
                resolved = candidate.expanduser().resolve()
            except OSError:
                continue
            key = str(resolved).lower()
            if key in seen:
                continue
            seen.add(key)
            if _is_complete_sdk_component_root(resolved):
                roots.append(resolved)
    return roots


def rank_sdk_roots_for_build_profile(
    sdk_roots: list[Path],
    *,
    compile_sdk_version: int | None,
    compatible_sdk_version: int | None,
    runtime_os: str | None = None,
) -> tuple[list[Path], int | None]:
    """
    Prefer SDK roots that contain the OpenHarmony API tree for ``compileSdkVersion``,
    then ``compatibleSdkVersion``. Falls back to the original order if nothing matches.
    Returns ``(ordered_roots, api_level_used)``.
    """
    for api in (compile_sdk_version, compatible_sdk_version):
        if api is None:
            continue
        matching = [root for root in sdk_roots if sdk_root_contains_openharmony_api(root, api)]
        if matching:
            tail = [root for root in sdk_roots if root not in matching]
            return matching + tail, api
        upgrade_matches: list[tuple[int, Path]] = []
        for root in sdk_roots:
            installed_api = _first_installed_openharmony_api_at_least(root, api)
            if installed_api is not None:
                upgrade_matches.append((installed_api, root))
        if upgrade_matches:
            best_api = min(installed_api for installed_api, _root in upgrade_matches)
            matching = [root for installed_api, root in upgrade_matches if installed_api == best_api]
            tail = [root for root in sdk_roots if root not in matching]
            return matching + tail, api
        legacy_matching = _legacy_complete_openharmony_roots(sdk_roots, api)
        if legacy_matching:
            tail = [root for root in sdk_roots if root not in legacy_matching]
            return legacy_matching + tail, api
    return list(sdk_roots), None


def get_ordered_sdk_roots_for_repo(
    repo_dir: str | os.PathLike[str],
    deveco_path: str | os.PathLike[str],
    *,
    product_name: str = "default",
) -> tuple[list[Path], dict[str, Any]]:
    """
    1. Enumerate DevEco / env SDK roots (``find_deveco_sdk_roots``).
    2. Read ``build-profile.json5`` compile / compatible SDK versions.
    3. Re-order roots so roots that contain the matching API level are tried first.

    Returns ``(ordered_roots, meta)`` where ``meta`` includes parsed versions and selection notes.
    """
    repo_path = Path(repo_dir).expanduser().resolve()
    compile_v, compatible_v, used_product, runtime_os = _read_build_profile_product_info(
        repo_path,
        product_name=product_name,
    )
    roots = find_deveco_sdk_roots(deveco_path)
    ranked, api_used = rank_sdk_roots_for_build_profile(
        roots,
        compile_sdk_version=compile_v,
        compatible_sdk_version=compatible_v,
        runtime_os=runtime_os,
    )
    meta: dict[str, Any] = {
        "build_profile_path": str(repo_path / "build-profile.json5"),
        "product": used_product,
        "compileSdkVersion": compile_v,
        "compatibleSdkVersion": compatible_v,
        "runtimeOS": runtime_os,
        "sdk_selection_api_level": api_used,
        "sdk_roots_unfiltered_count": len(roots),
        "sdk_roots_ordered_count": len(ranked),
    }
    if not roots:
        meta["sdk_selection_note"] = (
            "No OpenHarmony SDK root was discovered (check DEVECO_SDK_HOME, DevEco install, or --deveco-path)."
        )
    elif compile_v is not None and api_used is None:
        meta["sdk_selection_note"] = (
            "No SDK root reported an installed OpenHarmony API tree for compile/compatible "
            f"versions ({compile_v}/{compatible_v}); install API {compile_v} in DevEco SDK Manager or fix SDK paths."
        )
    return ranked, meta


def require_sdk_roots_for_repo(
    repo_dir: str | os.PathLike[str],
    deveco_path: str | os.PathLike[str],
    *,
    product_name: str = "default",
) -> tuple[list[Path], dict[str, Any]]:
    """
    Resolve SDK roots for a repo and fail early when no usable OpenHarmony SDK can be matched.
    """
    roots, meta = get_ordered_sdk_roots_for_repo(
        repo_dir,
        deveco_path,
        product_name=product_name,
    )
    note = str(meta.get("sdk_selection_note") or "").strip()
    if not roots:
        raise StructuredToolError(
            code="sdk_not_found",
            message=note or "No OpenHarmony SDK root was discovered.",
            details={"sdk_meta": meta},
        )
    if meta.get("compileSdkVersion") is not None and meta.get("sdk_selection_api_level") is None:
        raise StructuredToolError(
            code="sdk_precheck_failed",
            message=note or "No SDK root matches the compileSdkVersion required by build-profile.json5.",
            details={
                "sdk_meta": meta,
                "sdk_roots": [str(root) for root in roots],
            },
        )
    return roots, meta


def print_build_profile_sdk_resolution(meta: Mapping[str, Any]) -> None:
    """Print machine-readable ``KEY=value`` lines (stdout) for scripts that resolve SDK from build-profile."""
    print(f"BUILD_PROFILE_PATH={meta.get('build_profile_path', '')}")
    print(f"BUILD_PROFILE_PRODUCT={meta.get('product', '')}")
    c = meta.get("compileSdkVersion")
    v = meta.get("compatibleSdkVersion")
    print(f"BUILD_PROFILE_COMPILE_SDK_VERSION={c if c is not None else ''}")
    print(f"BUILD_PROFILE_COMPATIBLE_SDK_VERSION={v if v is not None else ''}")
    sel = meta.get("sdk_selection_api_level")
    print(f"SDK_SELECTION_API_LEVEL={sel if sel is not None else ''}")
    note = meta.get("sdk_selection_note")
    if note:
        print(f"SDK_SELECTION_NOTE={note}")


def _windows_space_free_alias(path: Path, label: str) -> Path:
    """Return a stable no-space junction alias for old Windows tools that split paths."""
    resolved = path.expanduser().resolve()
    # Keep validation on the existing machine paths. Do not create temp junction
    # aliases such as %TEMP%\arkeval_tool_links.
    return resolved


def build_harmony_command_env(
    *,
    sdk_root: Path | None,
    sdk_api_level: int | None = None,
    deveco_path: str | os.PathLike[str],
    base_env: Mapping[str, str] | None = None,
    openssl_legacy_provider: bool = True,
) -> dict[str, str]:
    env = dict(base_env or os.environ)
    for key in ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE"):
        env.pop(key, None)
    shared_tool_home = workspace_root().resolve()
    env["HOME"] = str(shared_tool_home)
    env["USERPROFILE"] = str(shared_tool_home)
    env["HVIGOR_USER_HOME"] = str((shared_tool_home / ".hvigor").resolve())
    if sdk_root:
        # Pass the parent SDK root to hvigor and let compileSdkVersion drive API selection.
        # Some hvigor versions mis-detect components when pointed directly at ``.../Sdk/<api>``.
        sdk_s = str(Path(sdk_root).expanduser().resolve())
        env["DEVECO_SDK_HOME"] = sdk_s
        env["OHOS_BASE_SDK_HOME"] = sdk_s
        env["OHOS_SDK_HOME"] = sdk_s
        openharmony_root = _resolve_openharmony_component_root(Path(sdk_root))
        if openharmony_root:
            env.setdefault("OHOS_NDK_HOME", str(openharmony_root))

    node_home = find_node_home(deveco_path)
    java_home = find_java_home(deveco_path)
    path_prefixes: list[str] = []
    if java_home:
        java_home = _windows_space_free_alias(java_home, "java_home")
        env["JAVA_HOME"] = str(java_home)
        path_prefixes.append(str(java_home / "bin"))
    elif env.get("JAVA_HOME"):
        java_home = _windows_space_free_alias(Path(env["JAVA_HOME"]), "java_home")
        env["JAVA_HOME"] = str(java_home)
        path_prefixes.append(str(java_home / "bin"))
    if node_home:
        node_home = _windows_space_free_alias(node_home, "node_home")
        env["NODE_HOME"] = str(node_home)
        path_prefixes.append(str(node_home))
    elif env.get("NODE_HOME"):
        node_home = _windows_space_free_alias(Path(env["NODE_HOME"]), "node_home")
        env["NODE_HOME"] = str(node_home)
        path_prefixes.append(str(node_home))
    node_options = env.get("NODE_OPTIONS", "")
    if openssl_legacy_provider:
        if "--openssl-legacy-provider" not in node_options:
            env["NODE_OPTIONS"] = (node_options + " --openssl-legacy-provider").strip()
    elif node_options:
        filtered_node_options = " ".join(
            option for option in node_options.split() if option != "--openssl-legacy-provider"
        ).strip()
        if filtered_node_options:
            env["NODE_OPTIONS"] = filtered_node_options
        else:
            env.pop("NODE_OPTIONS", None)
    if path_prefixes:
        env["PATH"] = os.pathsep.join([*path_prefixes, env.get("PATH", "")]).strip(os.pathsep)
    return env


def _resolve_openharmony_component_root(sdk_root: Path | None) -> Path | None:
    if sdk_root is None:
        return None
    root = sdk_root.expanduser().resolve()
    candidates = [
        root,
        root / "openharmony",
        root / "default" / "openharmony",
    ]
    candidates.extend(parent for parent in root.parents)
    candidates.extend(parent / "openharmony" for parent in root.parents)
    candidates.extend(parent / "default" / "openharmony" for parent in root.parents)
    for candidate in candidates:
        if (candidate / "native" / "llvm" / "bin").is_dir() and (candidate / "native" / "sysroot").is_dir():
            return candidate
    return None


@dataclass(slots=True)
class StructuredToolError(Exception):
    code: str
    message: str
    details: dict[str, Any] = field(default_factory=dict)

    def __str__(self) -> str:
        return self.message

    def to_dict(self) -> dict[str, Any]:
        return {
            "code": self.code,
            "message": self.message,
            "details": self.details,
        }


def _normalize_error_details(value: Any) -> Any:
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, Mapping):
        return {str(key): _normalize_error_details(item) for key, item in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_normalize_error_details(item) for item in value]
    return value


def error_to_dict(exc: BaseException) -> dict[str, Any]:
    if isinstance(exc, StructuredToolError):
        return {
            "code": exc.code,
            "message": exc.message,
            "details": _normalize_error_details(exc.details),
        }
    return {
        "code": exc.__class__.__name__,
        "message": str(exc),
        "details": {},
    }


def error_to_json(exc: BaseException) -> str:
    return json.dumps(error_to_dict(exc), ensure_ascii=False, sort_keys=True)


def resolve_directory(path_value: str | os.PathLike[str], label: str) -> Path:
    path = Path(path_value).expanduser().resolve()
    if not path.is_dir():
        raise FileNotFoundError(f"{label} does not exist or is not a directory: {path}")
    return path


def resolve_existing_path(path_value: str | os.PathLike[str], label: str) -> Path:
    path = Path(path_value).expanduser().resolve()
    if not path.exists():
        raise FileNotFoundError(f"{label} does not exist: {path}")
    return path


def read_text_file(
    path_value: str | os.PathLike[str],
    label: str,
    *,
    encoding: str = "utf-8",
) -> str:
    path = resolve_existing_path(path_value, label)
    return path.read_text(encoding=encoding, errors="replace")


def write_text_file(
    path_value: str | os.PathLike[str],
    content: str,
    *,
    encoding: str = "utf-8",
) -> Path:
    path = Path(path_value).expanduser().resolve()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding=encoding, errors="replace")
    return path


def _candidate_sdk_dirs_from_env(base_env: Mapping[str, str] | None) -> list[Path]:
    env = base_env or os.environ
    ordered: list[Path] = []
    seen: set[str] = set()
    for key in ("DEVECO_SDK_HOME", "OHOS_BASE_SDK_HOME", "OHOS_SDK_HOME"):
        raw = str(env.get(key, "")).strip()
        if not raw:
            continue
        if raw.lower() in seen:
            continue
        seen.add(raw.lower())
        ordered.append(Path(raw))
    return ordered


def _configured_openharmony_sdk_root() -> Path | None:
    for candidate in _candidate_sdk_dirs_from_env(os.environ):
        try:
            resolved = candidate.expanduser().resolve()
        except OSError:
            continue
        if resolved.is_dir():
            return resolved
    return None


def _configured_sdk_api_file(file_name: str, *, component: str, api_level: int) -> Path | None:
    sdk_root = _configured_openharmony_sdk_root()
    if sdk_root is None:
        return None
    candidate = sdk_root / str(api_level) / component / "api" / file_name
    return candidate if candidate.is_file() else None


def _normalize_sdk_dir_for_local_properties(path_value: str | os.PathLike[str]) -> str:
    return Path(path_value).expanduser().resolve().as_posix()


def ensure_local_properties(
    repo_dir: str | os.PathLike[str],
    *,
    sdk_root: str | os.PathLike[str] | None = None,
    sdk_api_level: int | None = None,
    base_env: Mapping[str, str] | None = None,
) -> Path:
    """
    Ensure ``<repo>/local.properties`` exists and contains ``sdk.dir=...``.

    Preference order:
    1. Explicit ``sdk_root`` from the current repo/sdk-selection flow
    2. ``DEVECO_SDK_HOME`` / ``OHOS_BASE_SDK_HOME`` / ``OHOS_SDK_HOME`` from env
    """
    resolved_repo = resolve_directory(repo_dir, "repo_dir")
    candidates: list[Path] = []
    if sdk_root is not None:
        candidates.append(Path(sdk_root))
    candidates.extend(_candidate_sdk_dirs_from_env(base_env))

    selected_sdk: Path | None = None
    seen: set[str] = set()
    for candidate in candidates:
        try:
            # Keep local.properties aligned with the hvigor-facing parent SDK root.
            resolved = Path(candidate).expanduser().resolve()
        except OSError:
            continue
        key = str(resolved).lower()
        if key in seen:
            continue
        seen.add(key)
        if resolved.exists():
            selected_sdk = resolved
            break

    if selected_sdk is None:
        raise StructuredToolError(
            code="local_properties_sdk_missing",
            message=(
                "Unable to create local.properties because no SDK root was available from "
                "DEVECO_SDK_HOME / OHOS_BASE_SDK_HOME / OHOS_SDK_HOME."
            ),
            details={
                "repo_dir": str(resolved_repo),
                "sdk_root_fallback": str(Path(sdk_root).expanduser()) if sdk_root is not None else "",
                "sdk_api_level": sdk_api_level,
                "env_candidates": [str(path) for path in _candidate_sdk_dirs_from_env(base_env)],
            },
        )

    content = AUTO_LOCAL_PROPERTIES_HEADER + "\n" + f"sdk.dir={_normalize_sdk_dir_for_local_properties(selected_sdk)}\n"
    target = resolved_repo / "local.properties"
    existing = ""
    if target.is_file():
        existing = target.read_text(encoding="utf-8", errors="replace")
    if existing != content:
        write_text_file(target, content)
    return target


def workspace_root() -> Path:
    """Return the command_line_tools_test workspace root (folder containing dev_sessions/)."""
    return Path(__file__).resolve().parents[1]


def tool_logs_dir() -> Path:
    """Shared logs directory for CLI tools."""
    return (workspace_root() / "dev_sessions" / "05_test" / "logs").resolve()


def timestamp_slug() -> str:
    """Filesystem-friendly timestamp for log filenames."""
    return datetime.now().strftime("%Y%m%d-%H%M%S-%f")


def write_tool_log(tool_name: str, content: str) -> Path:
    """Write a log file under dev_sessions/05_test/logs and return its path."""
    tool_logs_dir().mkdir(parents=True, exist_ok=True)
    filename = f"{tool_name}-{timestamp_slug()}.log"
    return write_text_file(tool_logs_dir() / filename, content.rstrip() + "\n")


def append_text_file(
    path_value: str | os.PathLike[str],
    content: str,
    *,
    encoding: str = "utf-8",
) -> Path:
    path = Path(path_value).expanduser().resolve()
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding=encoding, errors="replace", newline="\n") as file_obj:
        file_obj.write(content)
    return path


def strip_ansi(text: str) -> str:
    return ANSI_ESCAPE_RE.sub("", text)


def tail_text(text: str, limit: int = 60) -> str:
    lines = [line.rstrip() for line in strip_ansi(text).splitlines()]
    if len(lines) <= limit:
        return "\n".join(lines).strip()
    return "\n".join(lines[-limit:]).strip()


def format_command(command: Sequence[str]) -> str:
    return subprocess.list2cmdline([str(part) for part in command])


def format_path_for_display(
    path_value: str | os.PathLike[str],
    *,
    start: str | os.PathLike[str] | None = None,
) -> str:
    path = Path(path_value).expanduser().resolve()
    start_path = Path(start).expanduser().resolve() if start is not None else Path.cwd().resolve()

    try:
        return path.relative_to(start_path).as_posix() or "."
    except ValueError:
        try:
            return Path(os.path.relpath(path, start_path)).as_posix()
        except ValueError:
            return str(path)


def command_output(result: subprocess.CompletedProcess[str]) -> str:
    stdout = result.stdout or ""
    stderr = result.stderr or ""
    return "\n".join(part for part in (stdout, stderr) if part).strip()


def run_command(
    command: Sequence[str],
    cwd: Path,
    env: dict[str, str] | None = None,
    timeout_sec: float | None = None,
) -> subprocess.CompletedProcess[str]:
    popen_kwargs: dict[str, Any] = {
        "args": [str(part) for part in command],
        "cwd": str(cwd),
        "env": env,
        "stdout": subprocess.PIPE,
        "stderr": subprocess.PIPE,
        "text": True,
        "encoding": "utf-8",
        "errors": "replace",
    }
    if os.name == "nt":
        popen_kwargs["creationflags"] = getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
    else:
        popen_kwargs["start_new_session"] = True

    proc = subprocess.Popen(**popen_kwargs)
    try:
        stdout, stderr = proc.communicate(timeout=timeout_sec)
    except subprocess.TimeoutExpired as exc:
        _kill_process_tree(proc.pid)
        try:
            stdout, stderr = proc.communicate(timeout=5)
        except subprocess.TimeoutExpired:
            stdout = exc.output if isinstance(exc.output, str) else ""
            stderr = exc.stderr if isinstance(exc.stderr, str) else ""
        raise subprocess.TimeoutExpired(
            cmd=[str(part) for part in command],
            timeout=timeout_sec,
            output=stdout,
            stderr=stderr,
        ) from exc
    return subprocess.CompletedProcess(
        [str(part) for part in command],
        proc.returncode,
        stdout,
        stderr,
    )


def _kill_process_tree(pid: int) -> None:
    if os.name == "nt":
        subprocess.run(
            ["taskkill", "/F", "/T", "/PID", str(pid)],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
        )
        return
    try:
        os.killpg(pid, 9)
    except ProcessLookupError:
        return
    except OSError:
        try:
            os.kill(pid, 9)
        except OSError:
            return


def find_command_path(command_name: str) -> Path | None:
    if command_name.lower() in {"hdc", "hdc.exe"}:
        configured_hdc = os.environ.get("HDC_PATH", "").strip()
        if configured_hdc:
            candidate = Path(configured_hdc).resolve()
            if candidate.is_file():
                return candidate
    found = shutil.which(command_name)
    return Path(found).resolve() if found else None


def start_detached_process(
    command: Sequence[str],
    cwd: Path | None = None,
    env: dict[str, str] | None = None,
) -> subprocess.Popen[str]:
    popen_kwargs: dict[str, object] = {
        "args": [str(part) for part in command],
        "cwd": str(cwd) if cwd else None,
        "env": env,
        "stdin": subprocess.DEVNULL,
        "stdout": subprocess.DEVNULL,
        "stderr": subprocess.DEVNULL,
        "text": True,
    }
    if os.name == "nt":
        creationflags = getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0) | getattr(subprocess, "DETACHED_PROCESS", 0)
        popen_kwargs["creationflags"] = creationflags
    else:
        popen_kwargs["start_new_session"] = True
    return subprocess.Popen(**popen_kwargs)


def _existing_paths(paths: Iterable[Path]) -> list[Path]:
    return [path.resolve() for path in paths if path.exists()]


def _is_sdk_component_root(path: Path) -> bool:
    return path.is_dir() and (path / "toolchains").is_dir() and (path / "ets").is_dir()


def _version_key(path: Path) -> tuple[int, str]:
    digits = "".join(char for char in path.name if char.isdigit())
    return (int(digits) if digits else -1, path.name)


def _looks_like_sdk_root(path: Path) -> bool:
    if not path.is_dir():
        return False
    if (path / "default").is_dir():
        return True
    if (path / "openharmony").is_dir() or (path / "hms").is_dir():
        return True
    if _is_sdk_component_root(path):
        return True
    return any(child.is_dir() and child.name.isdigit() and _is_sdk_component_root(child) for child in path.iterdir())


def _sdk_related_candidates(path: Path) -> list[Path]:
    path = path.expanduser().resolve()
    candidates = [
        path,
        path / "sdk",
        path / "sdk" / "default",
        path / "sdk" / "default" / "openharmony",
        path / "sdk" / "openharmony",
        path / "default",
        path / "default" / "openharmony",
        path / "openharmony",
    ]
    if path.name.lower() in {"openharmony", "hms"}:
        candidates.extend([path.parent, path.parent.parent])
    if path.name.lower() == "default":
        candidates.append(path.parent)
    return [candidate.resolve() for candidate in candidates if candidate.exists()]


def find_deveco_sdk_roots(deveco_path: str | os.PathLike[str]) -> list[Path]:
    base_path = resolve_directory(deveco_path, "deveco_path")

    raw_candidates: list[Path] = []

    env_sdk = os.environ.get("DEVECO_SDK_HOME")
    if env_sdk:
        raw_candidates.extend(_sdk_related_candidates(Path(env_sdk)))

    raw_candidates.extend(_sdk_related_candidates(base_path))

    sdk_roots: list[Path] = []
    seen: set[Path] = set()
    for candidate in raw_candidates:
        resolved = candidate.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        if _looks_like_sdk_root(resolved):
            sdk_roots.append(resolved)
    return sdk_roots


def find_deveco_sdk_root(deveco_path: str | os.PathLike[str]) -> Path | None:
    sdk_roots = find_deveco_sdk_roots(deveco_path)
    return sdk_roots[0] if sdk_roots else None


def find_ohpm(
    deveco_path: str | os.PathLike[str],
) -> Path:
    base_path = resolve_directory(deveco_path, "deveco_path")
    candidates = [
        base_path / "tools" / "ohpm" / "bin" / "ohpm.bat",
        base_path / "tools" / "ohpm" / "bin" / "ohpm",
        base_path / "ohpm" / "bin" / "ohpm.bat",
        base_path / "ohpm" / "bin" / "ohpm",
    ]
    for candidate in candidates:
        if candidate.is_file():
            return candidate.resolve()
    raise FileNotFoundError("Unable to find bundled ohpm under the local arkeval DevEco runtime.")


def _repo_oh_package_paths(repo_dir: Path) -> list[Path]:
    """Return root/module ``oh-package.json5`` files declared by the Harmony project."""
    paths: list[Path] = []
    seen: set[str] = set()

    def add(path: Path) -> None:
        resolved = path.resolve()
        key = str(resolved).lower()
        if key not in seen and resolved.is_file():
            seen.add(key)
            paths.append(resolved)

    add(repo_dir / "oh-package.json5")
    build_profile = repo_dir / "build-profile.json5"
    if not build_profile.is_file():
        return paths
    try:
        data = parse_json5_text(build_profile.read_text(encoding="utf-8", errors="replace"))
    except Exception:
        return paths
    modules = data.get("modules") if isinstance(data, dict) else None
    if not isinstance(modules, list):
        return paths
    for module in modules:
        if not isinstance(module, dict):
            continue
        src_path = module.get("srcPath")
        if isinstance(src_path, str) and src_path.strip():
            add(repo_dir / src_path / "oh-package.json5")
    return paths


def _is_registry_dependency_spec(spec: Any) -> bool:
    if not isinstance(spec, str):
        return False
    normalized = spec.strip().lower()
    if not normalized:
        return False
    return not (
        normalized.startswith("file:")
        or normalized.startswith("../")
        or normalized.startswith("./")
        or normalized.startswith("/")
        or re.match(r"^[a-z]:[\\/]", normalized)
    )


OHPM_SEMVER_RANGE_MIN_RE = re.compile(
    r"^\s*(?:\^|~|>=|=)\s*"
    r"(?P<version>\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?)"
)


def _minimum_version_from_ohpm_range(spec: Any) -> str | None:
    if not isinstance(spec, str):
        return None
    stripped = spec.strip()
    if not stripped or "||" in stripped:
        return None
    match = OHPM_SEMVER_RANGE_MIN_RE.match(stripped)
    if not match:
        return None
    version = match.group("version")
    return None if stripped == version else version


def _apply_api_compatible_ohpm_adapters(
    repo_dir: Path,
    *,
    product_name: str = "default",
) -> tuple[dict[Path, str], list[str]]:
    """
    Apply temporary ohpm dependency pins needed by older SDK projects.

    Some upstream packages publish newer compatibleSdkVersion requirements under
    a broad semver range. For example, ``@ohos/zxing@^2.0.0`` can now resolve
    to a newer HAR whose SDK floor no longer matches the base project. During
    install we pin registry semver ranges to their declared minimum version,
    then restore source manifests so environment adaptation does not enter
    patches.
    """
    _ = product_name

    backups: dict[Path, str] = {}
    notes: list[str] = []

    for pkg_path in _repo_oh_package_paths(repo_dir):
        try:
            original = pkg_path.read_text(encoding="utf-8", errors="replace")
            data = parse_json5_text(original)
        except Exception:
            continue
        if not isinstance(data, dict):
            continue

        changed = False
        for section_name in ("dependencies", "dynamicDependencies", "devDependencies"):
            section = data.get(section_name)
            if not isinstance(section, dict):
                continue
            for package_name, spec in list(section.items()):
                minimum_version = _minimum_version_from_ohpm_range(spec)
                if _is_registry_dependency_spec(spec) and minimum_version is not None:
                    section[package_name] = minimum_version
                    changed = True
                    notes.append(
                        "OHPM_ADAPTER=pin_minimum "
                        f"{package_name} {spec!r}->{minimum_version!r} "
                        f"in {format_path_for_display(pkg_path, start=repo_dir)}"
                    )

        if changed:
            backups[pkg_path] = original
            pkg_path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    return backups, notes


def _snapshot_files(paths: Iterable[Path]) -> dict[Path, str | None]:
    snapshots: dict[Path, str | None] = {}
    for path in paths:
        resolved = path.resolve()
        if resolved.is_file():
            snapshots[resolved] = resolved.read_text(encoding="utf-8", errors="replace")
        else:
            snapshots[resolved] = None
    return snapshots


def _restore_file_snapshots(snapshots: Mapping[Path, str | None]) -> list[str]:
    notes: list[str] = []
    for path, content in snapshots.items():
        try:
            if content is None:
                if path.exists():
                    path.unlink()
            else:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content, encoding="utf-8")
        except Exception as exc:
            notes.append(f"OHPM_ADAPTER_RESTORE_ERROR={path}: {exc}")
    return notes


def _snapshot_binary_files(paths: Iterable[Path]) -> dict[Path, bytes | None]:
    snapshots: dict[Path, bytes | None] = {}
    for path in paths:
        resolved = path.resolve()
        snapshots[resolved] = resolved.read_bytes() if resolved.is_file() else None
    return snapshots


def _restore_binary_file_snapshots(snapshots: Mapping[Path, bytes | None]) -> list[str]:
    notes: list[str] = []
    for path, content in snapshots.items():
        try:
            if content is None:
                if path.exists():
                    path.unlink()
            else:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes(content)
        except Exception as exc:
            notes.append(f"OHPM_ADAPTER_RESTORE_ERROR={path}: {exc}")
    return notes


def run_ohpm_install(
    repo_dir: str | os.PathLike[str],
    deveco_path: str | os.PathLike[str],
    *,
    timeout_sec: float | None,
    product_name: str = "default",
) -> tuple[int, str]:
    """
    Run ``ohpm install`` as a deterministic repo initialization step before build/test.
    """
    resolved_repo = resolve_directory(repo_dir, "repo_dir")
    resolved_deveco = resolve_directory(deveco_path, "deveco_path")
    installed_modules = resolved_repo / "oh_modules"
    if installed_modules.is_dir() and any(installed_modules.iterdir()):
        return 0, "OHPM_STATUS=SUCCESS\nENV_PREPARE_OHPM=preinstalled oh_modules\n"
    ohpm = find_ohpm(resolved_deveco)
    offline_env = workspace_root() / "offline_env"
    cache_dir = offline_env / "ohpm_cache"
    command = [
        str(ohpm),
        "install",
        "--cache",
        str(cache_dir),
        "--registry",
        "http://127.0.0.1:9/",
        "--fetch_timeout",
        "10000",
        "--retry_times",
        "0",
    ]
    lock_paths = [path.parent / "oh-package-lock.json5" for path in _repo_oh_package_paths(resolved_repo)]
    lock_snapshots = _snapshot_files(lock_paths)
    manifest_backups: dict[Path, str] = {}
    archive_snapshots: dict[Path, bytes | None] = {}
    adapter_notes: list[str] = []
    restore_notes: list[str] = []
    env = build_harmony_command_env(
        sdk_root=None,
        deveco_path=resolved_deveco,
        base_env=os.environ.copy(),
    )
    env["HOME"] = str(offline_env)
    env["USERPROFILE"] = str(offline_env)
    env["OHPM_CACHE"] = str(cache_dir)
    env["OHPM_STORE_DIR"] = str(offline_env / "ohpm_store")
    env["HTTP_PROXY"] = "http://127.0.0.1:9"
    env["HTTPS_PROXY"] = "http://127.0.0.1:9"
    env["ALL_PROXY"] = "http://127.0.0.1:9"
    env["NO_PROXY"] = "127.0.0.1,localhost"
    try:
        adapter_notes.extend(_prepare_orange_shopping_lfs_archives(resolved_repo))
        adapter_notes.extend(_prepare_orange_shopping_clean_generated_state_for_ohpm(resolved_repo))
        local_archives = _repo_local_ohpm_archive_paths(resolved_repo)
        archive_snapshots = _snapshot_binary_files(local_archives)
        adapter_notes.extend(_prepare_local_archive_dependency_lock_pins(resolved_repo, local_archives))
        manifest_backups, ohpm_adapter_notes = _apply_api_compatible_ohpm_adapters(
            resolved_repo,
            product_name=product_name,
        )
        adapter_notes.extend(ohpm_adapter_notes)
        install_lock = offline_env / "arkeval-ohpm-install.lock"
        with FileLock(str(install_lock), timeout=max(900.0, float(timeout_sec or 0))):
            result = run_command(command, cwd=resolved_repo, env=env, timeout_sec=timeout_sec)
    finally:
        restore_notes.extend(_restore_file_snapshots({path: text for path, text in manifest_backups.items()}))
        restore_notes.extend(_restore_file_snapshots(lock_snapshots))
        restore_notes.extend(_restore_binary_file_snapshots(archive_snapshots))
    output_text = command_output(result)
    status = "SUCCESS" if result.returncode == 0 else "FAILED"
    combined = "\n".join(
        [
            f"OHPM_STATUS={status}",
            f"OHPM_EXIT_CODE={result.returncode}",
            f"OHPM_COMMAND={format_command(command)}",
            *adapter_notes,
            output_text.strip(),
            *restore_notes,
        ]
    ).strip()
    return result.returncode, combined + "\n"


def _abi_filter_text_with_x86_64(text: str, *, only_x86_64: bool = False) -> str:
    pattern = re.compile(r'("abiFilters"\s*:\s*\[)(?P<body>.*?)(\])', re.S)
    match = pattern.search(text)
    if not match:
        return text
    body = match.group("body")
    if only_x86_64:
        new_body = '\n        "x86_64"\n      '
        return text[: match.start("body")] + new_body + text[match.end("body") :]
    if re.search(r'["\']x86_64["\']', body):
        return text
    stripped = body.rstrip()
    if stripped:
        suffix = "" if stripped.endswith(",") else ","
        new_body = f'{stripped}{suffix}\n        "x86_64"\n      '
    else:
        new_body = '\n        "x86_64"\n      '
    return text[: match.start("body")] + new_body + text[match.end("body") :]


def _imageknife_root_profile_with_gpu_transform(root_profile: Path) -> str | None:
    if not root_profile.is_file():
        return None

    original = root_profile.read_text(encoding="utf-8", errors="replace")
    try:
        data = parse_json5_text(original)
    except Exception:
        return None

    modules = data.get("modules") if isinstance(data, dict) else None
    if not isinstance(modules, list):
        return None
    for module in modules:
        if isinstance(module, dict) and module.get("name") == "gpu_transform":
            return None

    modules.append({
        "name": "gpu_transform",
        "srcPath": "./gpu_transform",
    })
    root_profile.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return original


def _run_hvigor_preprocess_task(
    repo_dir: Path,
    deveco_dir: Path,
    *,
    module: str,
    product: str,
    task: str,
    sdk_root: Path | None,
    sdk_api_level: int | None,
    timeout_sec: float | None,
) -> str:
    hvigor = find_hvigor_wrapper(repo_dir, deveco_dir)
    command = [
        str(hvigor),
        "--debug",
        "--no-daemon",
        "--mode",
        "module",
        "-p",
        f"module={module}",
        "-p",
        f"product={product}",
        task,
    ]
    env = build_harmony_command_env(
        sdk_root=sdk_root,
        sdk_api_level=sdk_api_level,
        deveco_path=deveco_dir,
        base_env=os.environ.copy(),
    )
    try:
        result = run_command(command, cwd=repo_dir, env=env, timeout_sec=timeout_sec)
    except subprocess.TimeoutExpired as exc:
        output = "\n".join(
            part for part in (exc.output or "", exc.stderr or "") if isinstance(part, str) and part
        )
        raise StructuredToolError(
            code="native_preprocess_build_timeout",
            message=f"Native preprocess build timed out after {timeout_sec}s: {format_command(command)}",
            details={"output_tail": tail_text(output, limit=120)},
        ) from exc
    output = command_output(result)
    if result.returncode == 0 or "BUILD SUCCESSFUL" in output:
        return output
    raise StructuredToolError(
        code="native_preprocess_build_failed",
        message=f"Native preprocess build failed: {format_command(command)}",
        details={"output_tail": tail_text(output, limit=120)},
        )


def _harmonyos_openharmony_sdk_root_from_deveco(deveco_dir: Path) -> Path | None:
    sdk_root = deveco_dir / "sdk"
    if (sdk_root / "default" / "sdk-pkg.json").is_file():
        return sdk_root
    sdk_default = deveco_dir / "sdk" / "default"
    if (sdk_default / "openharmony").is_dir():
        return sdk_default / "openharmony"
    if (sdk_default / "hms").is_dir():
        return sdk_default / "hms"
    if (sdk_root / "default" / "openharmony").is_dir() or (sdk_root / "default" / "hms").is_dir():
        return sdk_root
    return None


def _prepare_imageknife_native_submodules(repo_dir: Path) -> list[str]:
    gitmodules = repo_dir / ".gitmodules"
    submodule_path = Path("gpu_transform/src/main/cpp/boundscheck/third_party_bounds_checking_function")
    expected_source = repo_dir / submodule_path / "src" / "memcpy_s.c"
    if not gitmodules.is_file() or not (repo_dir / "gpu_transform").is_dir() or expected_source.is_file():
        return []

    git = find_command_path("git")
    if not git:
        raise StructuredToolError(
            code="git_not_found",
            message="Unable to initialize native submodules because git was not found.",
            details={"submodule_path": str(submodule_path)},
        )

    command = [
        str(git),
        "-C",
        str(repo_dir),
        "submodule",
        "update",
        "--no-fetch",
        "--init",
        "--recursive",
        "--",
        submodule_path.as_posix(),
    ]
    result = run_command(command, cwd=repo_dir, timeout_sec=300.0)
    output_text = command_output(result)
    if result.returncode != 0 or not expected_source.is_file():
        raise StructuredToolError(
            code="native_submodule_init_failed",
            message="Failed to initialize the ImageKnife native boundscheck submodule.",
            details={
                "command": format_command(command),
                "exit_code": result.returncode,
                "output_tail": tail_text(output_text),
                "expected_source": str(expected_source),
            },
        )
    return [
        "ENV_PREPARE_IMAGEKNIFE_NATIVE_SUBMODULE="
        + format_path_for_display(repo_dir / submodule_path, start=repo_dir)
    ]


def _prepare_imageknife_entry_install_permissions(repo_dir: Path) -> list[str]:
    module_json = repo_dir / "entry" / "src" / "main" / "module.json5"
    if not module_json.is_file() or not (repo_dir / "gpu_transform").is_dir():
        return []

    original = module_json.read_text(encoding="utf-8", errors="replace")
    try:
        data = parse_json5_text(original)
    except Exception:
        return []
    module = data.get("module") if isinstance(data, dict) else None
    if not isinstance(module, dict):
        return []
    permissions = module.get("requestPermissions")
    if not isinstance(permissions, list):
        return []

    blocked = {"ohos.permission.READ_IMAGEVIDEO", "ohos.permission.WRITE_IMAGEVIDEO"}
    filtered = [
        item for item in permissions
        if not (isinstance(item, dict) and item.get("name") in blocked)
    ]
    if len(filtered) == len(permissions):
        return []

    module["requestPermissions"] = filtered
    module_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return [
        "ENV_PREPARE_IMAGEKNIFE_ENTRY_PERMISSIONS=removed_install_blocking_media_permissions"
    ]


def _find_populated_homogram_native_source(repo_dir: Path, native_rel: Path) -> Path | None:
    """Find an already-populated Homogram native submodule in sibling worktrees."""
    current = (repo_dir / native_rel).resolve()
    arkeval_root = Path(os.environ.get("ARKEVAL_ROOT", Path(__file__).resolve().parents[3]))
    repair_repo = arkeval_root / "depend" / "repair_repo"
    search_roots = [
        repo_dir.parent,
        repo_dir.parent.parent,
        repair_repo / "run01",
        repair_repo / "run02",
        repair_repo / "run03",
    ]
    seen: set[Path] = set()
    for root in search_roots:
        try:
            resolved_root = root.resolve()
        except Exception:
            continue
        if resolved_root in seen or not resolved_root.is_dir():
            continue
        seen.add(resolved_root)
        candidates = [
            resolved_root / "Homogram" / native_rel,
            resolved_root / native_rel,
        ]
        for candidate in candidates:
            try:
                resolved_candidate = candidate.resolve()
            except Exception:
                continue
            if resolved_candidate == current:
                continue
            if (resolved_candidate / "Cargo.toml").is_file() and (resolved_candidate / "dist" / "oh-package.json5").is_file():
                return resolved_candidate
    return None


def _copy_homogram_native_source(src: Path, dest: Path) -> None:
    ignore = shutil.ignore_patterns("target", ".git", ".git/*")
    if dest.exists():
        shutil.rmtree(dest)
    shutil.copytree(src, dest, ignore=ignore)


def _prepare_homogram_native_submodule(repo_dir: Path) -> list[str]:
    native_rel = Path("features/home/src/main/native/homogrape")
    native_dir = repo_dir / native_rel
    if not (repo_dir / ".gitmodules").is_file() or not native_dir.exists():
        return []
    if (native_dir / "Cargo.toml").is_file():
        return ["ENV_PREPARE_HOMOGRAM_NATIVE_SUBMODULE=present"]

    source = _find_populated_homogram_native_source(repo_dir, native_rel)
    if source is not None:
        _copy_homogram_native_source(source, native_dir)
        return [
            "ENV_PREPARE_HOMOGRAM_NATIVE_SUBMODULE=copied "
            + format_path_for_display(native_dir, start=repo_dir)
        ]

    git = find_command_path("git")
    if not git:
        raise StructuredToolError(
            code="git_not_found",
            message="Unable to initialize Homogram native submodule because git was not found.",
            details={"submodule_path": native_rel.as_posix()},
        )

    command = [
        str(git),
        "-C",
        str(repo_dir),
        "submodule",
        "update",
        "--no-fetch",
        "--init",
        "--recursive",
        "--",
        native_rel.as_posix(),
    ]
    result = run_command(command, cwd=repo_dir, timeout_sec=300.0)
    output_text = command_output(result)
    if result.returncode != 0 or not (native_dir / "Cargo.toml").is_file():
        raise StructuredToolError(
            code="homogram_native_submodule_init_failed",
            message="Failed to initialize the Homogram native homogrape submodule.",
            details={
                "command": format_command(command),
                "exit_code": result.returncode,
                "output_tail": tail_text(output_text),
                "expected_source": str(native_dir / "Cargo.toml"),
            },
        )
    return [
        "ENV_PREPARE_HOMOGRAM_NATIVE_SUBMODULE="
        + format_path_for_display(native_dir, start=repo_dir)
    ]


def _prepare_legacy_qrcode_src_entry_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/ETSUI/QRCode"):
        return []

    notes: list[str] = []
    for module_json in (
        repo_dir / "entry" / "src" / "main" / "module.json5",
        repo_dir / "entry" / "src" / "ohosTest" / "module.json5",
    ):
        if not module_json.is_file():
            continue
        original = module_json.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            continue
        module = data.get("module") if isinstance(data, dict) else None
        if not isinstance(module, dict):
            continue

        changed = False
        if "srcEntry" not in module and isinstance(module.get("srcEntrance"), str):
            module["srcEntry"] = module["srcEntrance"]
            changed = True
        abilities = module.get("abilities")
        if isinstance(abilities, list):
            for ability in abilities:
                if (
                    isinstance(ability, dict)
                    and "srcEntry" not in ability
                    and isinstance(ability.get("srcEntrance"), str)
                ):
                    ability["srcEntry"] = ability["srcEntrance"]
                    changed = True
                if isinstance(ability, dict) and "srcEntry" in ability and "srcEntrance" in ability:
                    ability.pop("srcEntrance", None)
                    changed = True

        if changed:
            module_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append(
                "ENV_PREPARE_QRCODE_SRC_ENTRY_SHIM="
                + format_path_for_display(module_json, start=repo_dir)
            )
    return notes


