def _prepare_upload_and_download_src_entry_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/BasicFeature/Connectivity/UploadAndDownLoad"):
        return []

    notes: list[str] = []
    hvigor_config = repo_dir / "hvigor" / "hvigor-config.json5"
    if hvigor_config.is_file():
        original = hvigor_config.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            data = None
        if not isinstance(data, dict):
            data = {}
        changed = data.get("modelVersion") != "5.0.0" or not isinstance(data.get("dependencies"), dict)
        if changed:
            data["modelVersion"] = "5.0.0"
            data["dependencies"] = data.get("dependencies") if isinstance(data.get("dependencies"), dict) else {}
            hvigor_config.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append(
                "ENV_PREPARE_UPLOAD_AND_DOWNLOAD_HVIGOR_CONFIG="
                + format_path_for_display(hvigor_config, start=repo_dir)
            )
    else:
        hvigor_config.parent.mkdir(parents=True, exist_ok=True)
        hvigor_config.write_text(
            json.dumps({"modelVersion": "5.0.0", "dependencies": {}}, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        notes.append(
            "ENV_PREPARE_UPLOAD_AND_DOWNLOAD_HVIGOR_CONFIG="
            + format_path_for_display(hvigor_config, start=repo_dir)
        )

    oh_package = repo_dir / "oh-package.json5"
    if oh_package.is_file():
        original = oh_package.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            data = None
        if isinstance(data, dict) and data.get("modelVersion") != "5.0.0":
            data["modelVersion"] = "5.0.0"
            oh_package.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append(
                "ENV_PREPARE_UPLOAD_AND_DOWNLOAD_OH_PACKAGE_MODEL_VERSION="
                + format_path_for_display(oh_package, start=repo_dir)
            )

    build_profile = repo_dir / "build-profile.json5"
    if build_profile.is_file():
        original = build_profile.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            data = None
        app = data.get("app") if isinstance(data, dict) else None
        if isinstance(app, dict):
            compile_sdk = app.pop("compileSdkVersion", None)
            compatible_sdk = app.pop("compatibleSdkVersion", None)
            products = app.get("products")
            changed = compile_sdk is not None or compatible_sdk is not None
            if isinstance(products, list):
                for product in products:
                    if not isinstance(product, dict):
                        continue
                    product_compile_sdk = product.pop("compileSdkVersion", None)
                    product_compatible_sdk = product.pop("compatibleSdkVersion", None)
                    product_runtime_os = product.pop("runtimeOS", None)
                    if product_compile_sdk is not None:
                        compile_sdk = compile_sdk if compile_sdk is not None else product_compile_sdk
                        changed = True
                    if product_compatible_sdk is not None:
                        compatible_sdk = compatible_sdk if compatible_sdk is not None else product_compatible_sdk
                        changed = True
                    if product_runtime_os is not None:
                        changed = True
            if compatible_sdk == 10:
                compatible_sdk = 9
                changed = True
            if isinstance(products, list):
                for product in products:
                    if not isinstance(product, dict):
                        continue
                    if product.get("runtimeOS") != "OpenHarmony":
                        product["runtimeOS"] = "OpenHarmony"
                        changed = True
                    if compile_sdk is not None and product.get("compileSdkVersion") != compile_sdk:
                        product["compileSdkVersion"] = compile_sdk
                        changed = True
                    if compatible_sdk is not None and product.get("compatibleSdkVersion") != compatible_sdk:
                        product["compatibleSdkVersion"] = compatible_sdk
                        changed = True
            if app.pop("runtimeOS", None) is not None:
                changed = True
            if changed:
                build_profile.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
                notes.append(
                    "ENV_PREPARE_UPLOAD_AND_DOWNLOAD_BUILD_PROFILE_SCHEMA="
                    + format_path_for_display(build_profile, start=repo_dir)
                )

    for module_json in (
        repo_dir / "entry" / "src" / "main" / "module.json5",
        repo_dir / "entry" / "src" / "ohosTest" / "module.json5",
    ):
        if not module_json.is_file():
            continue
        original = module_json.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            continue
        module = data.get("module") if isinstance(data, dict) else None
        if not isinstance(module, dict):
            continue

        changed = False
        for key in ("abilities", "extensionAbilities"):
            values = module.get(key)
            if not isinstance(values, list):
                continue
            for ability in values:
                if not isinstance(ability, dict):
                    continue
                if "srcEntry" not in ability and isinstance(ability.get("srcEntrance"), str):
                    ability["srcEntry"] = ability["srcEntrance"]
                    changed = True
                if "srcEntry" in ability and "srcEntrance" in ability:
                    ability.pop("srcEntrance", None)
                    changed = True

        if changed:
            module_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append(
                "ENV_PREPARE_UPLOAD_AND_DOWNLOAD_SRC_ENTRY_SHIM="
                + format_path_for_display(module_json, start=repo_dir)
            )

    ts_ability = repo_dir / "entry" / "src" / "main" / "ets" / "entryability" / "EntryAbility.ts"
    ets_ability = ts_ability.with_suffix(".ets")
    if ts_ability.is_file() and not ets_ability.exists():
        ts_ability.rename(ets_ability)
        notes.append(
            "ENV_PREPARE_UPLOAD_AND_DOWNLOAD_ENTRY_ABILITY_ETS="
            + format_path_for_display(ets_ability, start=repo_dir)
        )
        module_json = repo_dir / "entry" / "src" / "main" / "module.json5"
        if module_json.is_file():
            original = module_json.read_text(encoding="utf-8", errors="replace")
            patched = original.replace("./ets/entryability/EntryAbility.ts", "./ets/entryability/EntryAbility.ets")
            if patched != original:
                module_json.write_text(patched, encoding="utf-8")
                notes.append(
                    "ENV_PREPARE_UPLOAD_AND_DOWNLOAD_ENTRY_ABILITY_SRC_ENTRY="
                    + format_path_for_display(module_json, start=repo_dir)
                )
    return notes


