def _prepare_component_collection_hvigor412_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/UI/ArkTsComponentCollection/ComponentCollection"):
        return []

    config = repo_dir / "hvigor" / "hvigor-config.json5"
    if not config.is_file():
        return []

    original = config.read_text(encoding="utf-8", errors="replace")
    patched = re.sub(r'("hvigorVersion"\s*:\s*)"3\.0\.[29]"', r'\g<1>"4.1.2"', original)
    patched = re.sub(
        r'("@ohos/hvigor-ohos-plugin"\s*:\s*)"3\.0\.[29]"',
        r'\g<1>"4.1.2"',
        patched,
    )
    if patched == original:
        return []
    config.write_text(patched, encoding="utf-8")
    return ["ENV_PREPARE_COMPONENT_COLLECTION_HVIGOR=3.0.x->4.1.2"]


def _prepare_component_collection_hvigor412_profile_schema(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/UI/ArkTsComponentCollection/ComponentCollection"):
        return []

    notes: list[str] = []
    hvigor_major = 0
    hvigor_config = repo_dir / "hvigor" / "hvigor-config.json5"
    if hvigor_config.is_file():
        try:
            hvigor_data = parse_json5_text(hvigor_config.read_text(encoding="utf-8", errors="replace"))
            hvigor_version = str(hvigor_data.get("hvigorVersion") or "")
            hvigor_major = int(hvigor_version.split(".", 1)[0])
        except Exception:
            hvigor_major = 0
    project_profile = repo_dir / "build-profile.json5"
    if project_profile.is_file():
        original = project_profile.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            data = None
        app = data.get("app") if isinstance(data, dict) else None
        products = app.get("products") if isinstance(app, dict) else None
        if isinstance(app, dict) and isinstance(products, list) and products:
            changed = False
            if hvigor_major >= 4:
                compile_sdk = app.pop("compileSdkVersion", None)
                compatible_sdk = app.pop("compatibleSdkVersion", None)
                changed = compile_sdk is not None or compatible_sdk is not None
                for product in products:
                    if not isinstance(product, dict):
                        continue
                    product_compile_sdk = product.pop("compileSdkVersion", None)
                    product_compatible_sdk = product.pop("compatibleSdkVersion", None)
                    product_runtime_os = product.pop("runtimeOS", None)
                    if product_compile_sdk is not None:
                        compile_sdk = compile_sdk if compile_sdk is not None else product_compile_sdk
                        changed = True
                    if product_compatible_sdk is not None:
                        compatible_sdk = compatible_sdk if compatible_sdk is not None else product_compatible_sdk
                        changed = True
                    if product_runtime_os is not None:
                        changed = True
                    if compile_sdk is not None and product.get("compileSdkVersion") != compile_sdk:
                        product["compileSdkVersion"] = compile_sdk
                        changed = True
                    if compatible_sdk is not None and product.get("compatibleSdkVersion") != compatible_sdk:
                        product["compatibleSdkVersion"] = compatible_sdk
                        changed = True
            else:
                compile_sdk = app.get("compileSdkVersion")
                compatible_sdk = app.get("compatibleSdkVersion")
                for product in products:
                    if not isinstance(product, dict):
                        continue
                    product_compile_sdk = product.pop("compileSdkVersion", None)
                    product_compatible_sdk = product.pop("compatibleSdkVersion", None)
                    product_runtime_os = product.pop("runtimeOS", None)
                    if compile_sdk is None and product_compile_sdk is not None:
                        app["compileSdkVersion"] = product_compile_sdk
                        compile_sdk = product_compile_sdk
                        changed = True
                    if compatible_sdk is None and product_compatible_sdk is not None:
                        app["compatibleSdkVersion"] = product_compatible_sdk
                        compatible_sdk = product_compatible_sdk
                        changed = True
                    if product_compile_sdk is not None or product_compatible_sdk is not None or product_runtime_os is not None:
                        changed = True
            if changed:
                project_profile.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
                notes.append(
                    "ENV_PREPARE_COMPONENT_COLLECTION_PROJECT_PROFILE_SCHEMA="
                    + format_path_for_display(project_profile, start=repo_dir)
                )

    entry_profile = repo_dir / "entry" / "build-profile.json5"
    if entry_profile.is_file():
        original = entry_profile.read_text(encoding="utf-8", errors="replace")
        patched = re.sub(
            r'"buildOption"\s*:\s*\{\s*"compileMode"\s*:\s*["\']esmodule["\']\s*\}',
            '"buildOption": {}',
            original,
            flags=re.S,
        )
        if patched != original:
            entry_profile.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_COMPONENT_COLLECTION_ENTRY_PROFILE_SCHEMA="
                + format_path_for_display(entry_profile, start=repo_dir)
            )
    return notes


def _prepare_component_collection_form_component_type_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/UI/ArkTsComponentCollection/ComponentCollection"):
        return []

    target = (
        repo_dir
        / "entry"
        / "src"
        / "main"
        / "ets"
        / "pages"
        / "universal"
        / "events"
        / "dragEventSample"
        / "component"
        / "FormComponentDrag.ets"
    )
    if not target.is_file():
        return []

    original = target.read_text(encoding="utf-8", errors="replace")
    if "declare function FormComponent(options: FormComponentOptions)" in original:
        return []
    marker = " */\n\n@Component"
    if marker not in original:
        return []
    patched = original.replace(marker, " */\n\n" + FORM_COMPONENT_DRAG_TYPE_SHIM + "@Component", 1)
    target.write_text(patched, encoding="utf-8")
    return [
        "ENV_PREPARE_COMPONENT_COLLECTION_FORM_COMPONENT_TYPES="
        + format_path_for_display(target, start=repo_dir)
    ]


def _prepare_component_collection_resource_json_strict_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/UI/ArkTsComponentCollection/ComponentCollection"):
        return []

    resource_root = repo_dir / "entry" / "src" / "main" / "resources"
    if not resource_root.is_dir():
        return []

    notes: list[str] = []
    for json_file in sorted(resource_root.rglob("*.json")):
        original = json_file.read_text(encoding="utf-8", errors="replace")
        stripped_chars: list[str] = []
        i = 0
        in_string = False
        escape = False
        while i < len(original):
            char = original[i]
            next_char = original[i + 1] if i + 1 < len(original) else ""
            if in_string:
                stripped_chars.append(char)
                if escape:
                    escape = False
                elif char == "\\":
                    escape = True
                elif char == '"':
                    in_string = False
                i += 1
                continue
            if char == '"':
                in_string = True
                stripped_chars.append(char)
                i += 1
                continue
            if char == "/" and next_char == "/":
                i += 2
                while i < len(original) and original[i] not in "\r\n":
                    i += 1
                continue
            if char == "/" and next_char == "*":
                i += 2
                while i + 1 < len(original) and not (original[i] == "*" and original[i + 1] == "/"):
                    i += 1
                i += 2 if i + 1 < len(original) else 0
                continue
            stripped_chars.append(char)
            i += 1
        stripped = "".join(stripped_chars)
        for _ in range(32):
            next_text = re.sub(r",(\s*[\]}])", r"\1", stripped)
            if next_text == stripped:
                break
            stripped = next_text
        try:
            data = json.loads(stripped)
        except Exception:
            continue
        patched = json.dumps(data, ensure_ascii=False, indent=2) + "\n"
        if patched == original:
            continue
        json_file.write_text(patched, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_COMPONENT_COLLECTION_STRICT_RESOURCE_JSON="
            + format_path_for_display(json_file, start=repo_dir)
        )
    return notes


def _prepare_component_collection_button_style_strict_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/UI/ArkTsComponentCollection/ComponentCollection"):
        return []

    ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    if not ets_root.is_dir():
        return []

    notes: list[str] = []
    for source_path in sorted(ets_root.rglob("*.ets")):
        original = source_path.read_text(encoding="utf-8", errors="replace")
        if "buttonStyle()" not in original:
            continue
        patched = original.replace("function buttonStyle()", "function legacyButtonStyle()")
        patched = patched.replace("@Styles buttonStyle()", "@Styles legacyButtonStyle()")
        patched = patched.replace(".buttonStyle()", ".legacyButtonStyle()")
        if patched == original:
            continue
        source_path.write_text(patched, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_COMPONENT_COLLECTION_BUTTON_STYLE_STRICT="
            + format_path_for_display(source_path, start=repo_dir)
        )
    return notes


def _prepare_component_collection_arkts_linter_compat(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/UI/ArkTsComponentCollection/ComponentCollection"):
        return []

