def _prepare_component_collection_event_stop_propagation_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/UI/ArkTsComponentCollection/ComponentCollection"):
        return []

    target = (
        repo_dir
        / "entry"
        / "src"
        / "main"
        / "ets"
        / "pages"
        / "universal"
        / "properties"
        / "componentIDSample"
        / "ComponentIDSample.ets"
    )
    if not target.is_file():
        return []

    original = target.read_text(encoding="utf-8", errors="replace")
    patched = original
    mouse_marker = "                  sourceTool: SourceTool.Unknown\n                };"
    if mouse_marker in patched:
        patched = patched.replace(
            mouse_marker,
            "                  sourceTool: SourceTool.Unknown,\n"
            "                  stopPropagation: () => {}\n"
            "                };",
            1,
        )
    key_with_intention_marker = "                  timestamp: 0,\n                  intentionCode: 2\n                };"
    if key_with_intention_marker in patched:
        patched = patched.replace(
            key_with_intention_marker,
            "                  timestamp: 0,\n"
            "                  stopPropagation: () => {},\n"
            "                  intentionCode: 2\n"
            "                };",
            1,
        )
    else:
        key_marker = "                  timestamp: 0\n                };"
        if key_marker in patched:
            patched = patched.replace(
                key_marker,
                "                  timestamp: 0,\n"
                "                  stopPropagation: () => {}\n"
                "                };",
                1,
            )
    if patched == original:
        return []
    target.write_text(patched, encoding="utf-8")
    return [
        "ENV_PREPARE_COMPONENT_COLLECTION_EVENT_STOP_PROPAGATION="
        + format_path_for_display(target, start=repo_dir)
    ]


def _prepare_etsui_component_invalid_color_resource_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/ETSUI/Component"):
        return []

    resource_root = repo_dir / "entry" / "src" / "main" / "resources"
    if not resource_root.is_dir():
        return []

    notes: list[str] = []
    for color_json in sorted(resource_root.rglob("element/color.json")):
        original = color_json.read_text(encoding="utf-8", errors="replace")
        try:
            data = json.loads(original)
        except Exception:
            continue
        colors = data.get("color") if isinstance(data, dict) else None
        if not isinstance(colors, list):
            continue

        changed = False
        for item in colors:
            if not isinstance(item, dict):
                continue
            value = item.get("value")
            if isinstance(value, str) and re.fullmatch(r"#[0-9a-fA-F]{7}", value):
                item["value"] = "#" + value[1] + value[1:]
                changed = True

        if changed:
            color_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append(
                "ENV_PREPARE_ETSUI_COMPONENT_COLOR_JSON="
                + format_path_for_display(color_json, start=repo_dir)
            )
    return notes


def _prepare_etsui_component_float_resource_schema_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/ETSUI/Component"):
        return []

    resource_root = repo_dir / "entry" / "src" / "main" / "resources"
    if not resource_root.is_dir():
        return []

    notes: list[str] = []
    for float_json in sorted(resource_root.rglob("element/float.json")):
        original = float_json.read_text(encoding="utf-8", errors="replace")
        try:
            data = json.loads(original)
        except Exception:
            continue
        if not isinstance(data, dict) or "float" in data or not isinstance(data.get("color"), list):
            continue
        data["float"] = data.pop("color")
        float_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        notes.append(
            "ENV_PREPARE_ETSUI_COMPONENT_FLOAT_JSON="
            + format_path_for_display(float_json, start=repo_dir)
        )
    return notes


def _prepare_etsui_component_arkts_builder_check_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/ETSUI/Component"):
        return []

    local_properties = repo_dir / "local.properties"
    if not local_properties.is_file():
        return []

    original = local_properties.read_text(encoding="utf-8", errors="replace")
    line = "ArkTSConfig.ArkTSBuilderCheck=false"
    if line in original:
        return []
    separator = "" if original.endswith(("\n", "\r")) or not original else "\n"
    local_properties.write_text(original + separator + line + "\n", encoding="utf-8")
    return [
        "ENV_PREPARE_ETSUI_COMPONENT_ARKTS_BUILDER_CHECK="
        + format_path_for_display(local_properties, start=repo_dir)
    ]


def _prepare_etsui_component_compile_compat_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/ETSUI/Component"):
        return []

    replacements: dict[str, list[tuple[str, str]]] = {
        "entry/src/main/ets/MainAbility/pages/component_basis/button/buttonPage.ets": [
            (
                "Button('Button', {  type: this.typeBtn, stateEffect: this.effect }) {",
                "Button({ type: this.typeBtn, stateEffect: this.effect }) {",
            ),
        ],
        "entry/src/main/ets/MainAbility/pages/component_basis/textArea/textAreaPage.ets": [
            ("@State size: number = 15", "@State fontSizeValue: number = 15"),
            ("this.size", "this.fontSizeValue"),
        ],
        "entry/src/main/ets/MainAbility/pages/component_basis/textInput/textInputPage.ets": [
            ("@State size: number = 15", "@State fontSizeValue: number = 15"),
            ("this.size", "this.fontSizeValue"),
        ],
        "entry/src/main/ets/MainAbility/pages/component_container/Column/ColumnPage.ets": [
            ("@State offset: number = 0", "@State edgeOffset: number = 0"),
            ("this.offset", "this.edgeOffset"),
        ],
        "entry/src/main/ets/MainAbility/pages/component_container/row/rowPage.ets": [
            ("@State offset: number = 0", "@State edgeOffset: number = 0"),
            ("this.offset", "this.edgeOffset"),
        ],
        "entry/src/main/ets/MainAbility/pages/component_container/flex/flexPage.ets": [
            ("@State direction: FlexDirection[]", "@State flexDirectionOptions: FlexDirection[]"),
            ("this.direction[", "this.flexDirectionOptions["),
        ],
    }

    notes: list[str] = []
    for relative, pairs in replacements.items():
        path = repo_dir / relative
        if not path.is_file():
            continue
        original = path.read_text(encoding="utf-8", errors="replace")
        patched = original
        for old, new in pairs:
            patched = patched.replace(old, new)
        if patched == original:
            continue
        path.write_text(patched, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_ETSUI_COMPONENT_COMPILE_COMPAT="
            + format_path_for_display(path, start=repo_dir)
        )
    return notes


def _prepare_resource_manager_arkts_strict_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/BasicFeature/Resource/ResourceManager"):
        return []

    path = repo_dir / "entry" / "src" / "main" / "ets" / "pages" / "BasicResources.ets"
    if not path.is_file():
        return []

    original = path.read_text(encoding="utf-8", errors="replace")
    patched = original
    patched = patched.replace(
        "async function getDeviceCapability(): Promise<resourceManager.DeviceCapability>",
        "async function getDeviceCapability(): Promise<resourceManager.DeviceCapability | undefined>",
    )
    patched = patched.replace(
        "async function getConfiguration(): Promise<resourceManager.Configuration>",
        "async function getConfiguration(): Promise<resourceManager.Configuration | undefined>",
    )
    patched = re.sub(r"\n\s*throw error;\n", "\n", patched)

    defaults = {
        "getStringValue failed": "return '';",
        "getStringArrayValue failed": "return [];",
        "getPluralStringValue failed": "return '';",
        "getDeviceCapability failed": "return undefined;",
        "getConfiguration failed": "return undefined;",
        "getMediaContent failed": "return new Uint8Array();",
        "getMediaContentBase64 failed": "return '';",
        "getStringSync failed": "return '';",
        "getDensityMediaBase64 failed": "return '';",
    }
    for marker, default_return in defaults.items():
        pattern = re.compile(
            rf"(^\s*(?:Logger|hilog)\.error\([^\n]*{re.escape(marker)}[^\n]*\);\s*$)(?!\n\s*return )",
            re.MULTILINE,
        )
        patched = pattern.sub(rf"\1\n    {default_return}", patched)

    if patched == original:
        return []

    path.write_text(patched, encoding="utf-8")
    return [
        "ENV_PREPARE_RESOURCE_MANAGER_ARKTS_STRICT="
        + format_path_for_display(path, start=repo_dir)
    ]


def _prepare_custom_input_text_arkts_strict_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/Solutions/InputMethod/CustomInputText"):
        return []

    notes: list[str] = []
    component = repo_dir / "entry" / "src" / "main" / "ets" / "components" / "CustomInputText.ets"
    if component.is_file():
        original = component.read_text(encoding="utf-8", errors="replace")
        patched = re.sub(r"<number>\s*([^;\n]+)", r"(\1 as number)", original)
        if patched != original:
            component.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_CUSTOM_INPUT_TEXT_ARKTS_STRICT="
                + format_path_for_display(component, start=repo_dir)
            )

    page = repo_dir / "entry" / "src" / "main" / "ets" / "pages" / "Index.ets"
    if page.is_file():
        original = page.read_text(encoding="utf-8", errors="replace")
        style_names = {"buttonStyle", "selectStyle", "textStyle", "inputStyle", "cardStyle"}
        patched_lines: list[str] = []
        skip_style = False
        for line in original.splitlines(keepends=True):
            if any(
                re.match(rf"\s*@(?:Extend\([^)]+\)|Styles)\s+function\s+{name}\s*\(", line)
                for name in style_names
            ):
                skip_style = True
                continue
            if skip_style:
                if re.match(r"\s*}\s*$", line):
                    skip_style = False
                continue
            indent = re.match(r"(\s*)", line).group(1)
            if ".buttonStyle()" in line:
                patched_lines.extend([
                    f"{indent}.type(ButtonType.Capsule)\n",
                    f"{indent}.backgroundColor($r('app.color.button_color'))\n",
                    f"{indent}.fontColor(Color.White)\n",
                    f"{indent}.fontSize(16)\n",
                    f"{indent}.height(40)\n",
                    f"{indent}.fontWeight(500)\n",
                    f"{indent}.width('100%')\n",
                ])
                continue
            if ".inputStyle()" in line:
                patched_lines.extend([
                    f"{indent}.type(InputType.Number)\n",
                    f"{indent}.height(40)\n",
                    f"{indent}.placeholderFont({{ size: 14 }})\n",
                    f"{indent}.margin({{ top: 8, bottom: 8 }})\n",
                    f"{indent}.maxLength(4)\n",
                    f"{indent}.layoutWeight(1)\n",
                ])
                continue
            if ".selectStyle()" in line:
                patched_lines.extend([
                    f"{indent}.fontColor($r('app.color.text_color'))\n",
                    f"{indent}.font({{ size: 16, weight: 500 }})\n",
                ])
                continue
            if ".textStyle()" in line:
                patched_lines.extend([
                    f"{indent}.fontColor($r('app.color.text_color'))\n",
                    f"{indent}.fontSize(16)\n",
                    f"{indent}.fontWeight(500)\n",
                ])
                continue
            if ".cardStyle()" in line:
                patched_lines.extend([
                    f"{indent}.padding(12)\n",
                    f"{indent}.width('100%')\n",
                    f"{indent}.backgroundColor(Color.White)\n",
                    f"{indent}.borderRadius(23)\n",
                ])
                continue
            patched_lines.append(line)
        patched = "".join(patched_lines)
        if patched != original:
            page.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_CUSTOM_INPUT_TEXT_ARKTS_STRICT="
                + format_path_for_display(page, start=repo_dir)
            )
    return notes


def _prepare_custom_input_text_ohos_test_strict_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/Solutions/InputMethod/CustomInputText"):
        return []

    notes: list[str] = []
    ability_test = repo_dir / "entry" / "src" / "ohosTest" / "ets" / "test" / "Ability.test.ets"
    if ability_test.is_file():
        original = ability_test.read_text(encoding="utf-8", errors="replace")
        patched = original
        if "import UIAbility from '@ohos.app.ability.UIAbility';" not in patched:
            patched = patched.replace(
                "import AbilityDelegatorRegistry from '@ohos.app.ability.abilityDelegatorRegistry';",
                "import AbilityDelegatorRegistry from '@ohos.app.ability.abilityDelegatorRegistry';\n"
                "import UIAbility from '@ohos.app.ability.UIAbility';",
            )
        patched = re.sub(r"describe\(([^,\n]+,\s*)function\s*\(\)\s*\{", r"describe(\1() => {", patched)
        patched = re.sub(
            r"it\(([^,\n]+,\s*0,\s*)async function\s*\(\s*done\s*\)\s*\{",
            r"it(\1async (done: Function) => {",
            patched,
        )
        patched = patched.replace(".then(result => {", ".then((result: Object) => {")
        patched = patched.replace(".catch(err => {", ".catch((err: Error) => {")
        patched = patched.replace("then((Ability) => {", "then((ability: UIAbility) => {")
        patched = patched.replace("expect(Ability.context.abilityInfo.name)", "expect(ability.context.abilityInfo.name)")
        if patched != original:
            ability_test.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_CUSTOM_INPUT_TEXT_OHOSTEST_STRICT="
                + format_path_for_display(ability_test, start=repo_dir)
            )

    test_ability_ts = repo_dir / "entry" / "src" / "ohosTest" / "ets" / "TestAbility" / "TestAbility.ts"
    test_ability_ets = test_ability_ts.with_suffix(".ets")
    if test_ability_ts.is_file():
        test_ability_ets.write_text(test_ability_ts.read_text(encoding="utf-8", errors="replace"), encoding="utf-8")
        test_ability_ts.unlink()
        notes.append(
            "ENV_PREPARE_CUSTOM_INPUT_TEXT_OHOSTEST_STRICT="
            + format_path_for_display(test_ability_ets, start=repo_dir)
        )
    if test_ability_ets.is_file():
        original = test_ability_ets.read_text(encoding="utf-8", errors="replace")
        patched = original.replace("onCreate(want, launchParam): void", "onCreate(want: Object, launchParam: Object): void")
        if patched != original:
            test_ability_ets.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_CUSTOM_INPUT_TEXT_OHOSTEST_STRICT="
                + format_path_for_display(test_ability_ets, start=repo_dir)
            )

    module_json = repo_dir / "entry" / "src" / "ohosTest" / "module.json5"
    if module_json.is_file():
        original = module_json.read_text(encoding="utf-8", errors="replace")
        patched = original.replace("./ets/TestAbility/TestAbility.ts", "./ets/TestAbility/TestAbility.ets")
        if patched != original:
            module_json.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_CUSTOM_INPUT_TEXT_OHOSTEST_STRICT="
                + format_path_for_display(module_json, start=repo_dir)
            )
    return notes


def _prepare_homogram_libhomogrape_types(repo_dir: Path) -> list[str]:
    dist_dir = repo_dir / "features" / "home" / "src" / "main" / "native" / "homogrape" / "dist"
    package_json = dist_dir / "oh-package.json5"
    type_file = dist_dir / "index.d.ts"
    if not package_json.is_file():
        return []
    generated_marker = "// Generated by arkeval validation preprocessing for Homogram base builds."
    type_text = f"""{generated_marker}
export const enum LoginState {{
  WrongPhoneNumber = 0,
  CodeRequired = 1,
  WrongCode = 2,
  PasswordRequired = 3,
  WrongPassword = 4,
  LoggedIn = 5,
  LoginFailure = 6,
}}

export const enum MediaType {{
  None = 0,
  Photo = 1,
  Document = 2,
  Sticker = 3,
  Contact = 4,
  Poll = 5,
  Geo = 6,
  Dice = 7,
  Venue = 8,
  GeoLive = 9,
  WebPage = 10,
}}

export const enum ChatType {{
  User = 0,
  Group = 1,
  Channel = 2,
}}

export interface NativePackedChat {{
  chatId: number;
  packedChat: string;
}}

export interface NativeRawMessage {{
  chatId: number;
  messageId: number;
  rawMessage: ArrayBuffer;
}}

export interface NativeMessage {{
  messageId: number;
  chatId: number;
  outgoing: boolean;
  pinned: boolean;
  senderId: number;
  senderName: string;
  timestamp: number;
  text: string;
  mediaType: MediaType;
  editTimestamp?: number;
  groupedId?: number;
  replyToMessageId?: number;
  viewCount?: number;
  forwardCount?: number;
  replyCount?: number;
  fmtEntities?: NativeMessageEntity[];
  stickerInfo?: StickerInfo;
  mediaInfo?: MediaInfo;
}}

export const enum MessageEntityType {{
  Unknown = 0,
  Mention = 1,
  Hashtag = 2,
  BotCommand = 3,
  Url = 4,
  Email = 5,
  Bold = 6,
  Italic = 7,
  Code = 8,
  Pre = 9,
  TextUrl = 10,
  MentionName = 11,
  Phone = 12,
  Cashtag = 13,
  Underline = 14,
  Strike = 15,
  Blockquote = 16,
  Spoiler = 17,
  CustomEmoji = 18,
}}

export interface NativeMessageEntity {{
  entityType: MessageEntityType;
  offset: number;
  length: number;
  url?: string;
  userId?: number;
  language?: string;
  customEmojiId?: number;
}}

export interface StickerInfo {{
  emoji?: string;
  isAnimated: boolean;
  isVideo: boolean;
  mimeType?: string;
  fileSize?: number;
  width?: number;
  height?: number;
}}

export interface MediaInfo {{
  mimeType?: string;
  fileName?: string;
  fileSize?: number;
  width?: number;
  height?: number;
  duration?: number;
}}

export const enum NativeParticipantRole {{
  Creator = 0,
  Admin = 1,
  Member = 2,
  Left = 3,
  Banned = 4,
}}

export interface NativeParticipant {{
  userId: number;
  fullName: string;
  firstName: string;
  lastName?: string;
  username?: string;
  phone?: string;
  role: NativeParticipantRole;
  photoThumb?: number[];
  isBot?: boolean;
  isScam?: boolean;
  isFake?: boolean;
}}

export interface NativeChat {{
  chatId: number;
  chatType: ChatType;
  name: string;
  pinned: boolean;
  lastMessageId: number;
  lastMessageSenderName: string;
  lastMessageText: string;
  lastMessageTimestamp: number;
  megagroup: boolean;
  forum: boolean;
}}

export interface NativeSeenChat {{
  chatId: number;
  chatType: ChatType;
  packedChat: string;
  isContact: boolean;
  isMutualContact: boolean;
  phone?: string;
  username?: string;
  photoThumb?: number[];
  fullName: string;
  firstName: string;
  lastName?: string;
  bio?: string;
  dateOfBirth?: number;
  forum: boolean;
}}

export interface ProfilePhotoPath {{
  dir: string;
  current?: string;
  next: string;
  count: number;
}}

export type LoadChatsCallback = (err: Error | null) => Promise<void> | void;
export type CacheSeenChatCallback = (err: Error | null, seenChat: NativeSeenChat) => Promise<void> | void;
export type UpdateChatCallback = (
  err: Error | null,
  seenChat: NativeSeenChat,
  chat: NativeChat,
  messages: NativeMessage[]
) => Promise<void>;
export type IncomingMessageCallback = (err: Error | null, chat: NativeChat, message: NativeMessage) => void;
export type UpdateUploadProgressCallback = (mediaIndex: number, currentProgress: number) => Promise<void>;

export function isLoggedIn(): Promise<boolean>;
export function registerDevice(token: string): Promise<boolean>;
export function login(phoneNumber: string): Promise<LoginState>;
export function verifyCode(code: string): Promise<LoginState>;
export function password(password: string): Promise<LoginState>;
export function signOut(): Promise<boolean>;
export function run(): Promise<void>;
export function stop(): Promise<void>;
export function registerUpdateChatCallback(cb: UpdateChatCallback): Promise<void>;
export function registerCacheSeenChatCallback(cb: CacheSeenChatCallback): Promise<void>;
export function registerLoadChatsCallback(cb: LoadChatsCallback): Promise<void>;
export function registerIncomingMessageCallback(cb: IncomingMessageCallback): Promise<void>;
export function loadChats(): Promise<void>;
export function getMe(): Promise<NativeSeenChat>;
export function loadChatsWithOffset(lastMessageIds: Record<string, number>): Promise<void>;
export function syncCachesFromLocalDb(packedChats: NativePackedChat[], chats: NativeChat[]): Promise<void>;
export function sendMessage(
  chatId: number,
  text: string,
  replyTo: number | undefined,
  medias: string[] | undefined,
  updateUploadProgressCallback: UpdateUploadProgressCallback
): Promise<NativeMessage[]>;
export function sendMessage(
  chatId: number,
  text: string,
  medias: string[] | undefined,
  updateUploadProgressCallback: UpdateUploadProgressCallback
): Promise<NativeMessage[]>;
export function loadHistoryMessages(
  chatId: number,
  lastMessageId: number | undefined,
  limit: number | undefined
): Promise<NativeMessage[]>;
export function forwardMessages(fromChatId: number, toChatId: number, messageIds: number[]): Promise<NativeMessage[]>;
export function getParticipants(chatId: number): Promise<NativeParticipant[]>;
export function registerPush(tokenType: number, token: string): Promise<string>;
export function unregisterPush(tokenType: number, token: string): Promise<string>;
export function downloadMediaFromMessage(chatId: number, messageId: number): Promise<string>;
export function downloadProfilePhoto(chatId: number): Promise<string>;
export function getChatPhotoThumb(chatId: number): Promise<ArrayBuffer | undefined>;
export function reconnect(): Promise<boolean>;
export function getProfilePhotoPathAndCount(chatId: number): ProfilePhotoPath;
"""
    if type_file.is_file():
        existing = type_file.read_text(encoding="utf-8", errors="replace")
        if existing == type_text:
            return ["ENV_PREPARE_HOMOGRAM_LIBHOMOGRAPE_TYPES=present"]
        is_previous_generated_shim = (
            generated_marker in existing
            or (
                "auto-generated by OHOS-RS" in existing
                and "export " not in existing
                and len(existing.strip()) < 256
            )
            or (
                "export enum LoginState" in existing
                and "export interface NativeSeenChat" in existing
                and "export function getProfilePhotoPathAndCount" in existing
                and "photoThumb?: ArrayBuffer" in existing
            )
        )
        if not is_previous_generated_shim:
            return ["ENV_PREPARE_HOMOGRAM_LIBHOMOGRAPE_TYPES=present_external"]
        action = "updated"
    else:
        action = "created"

    type_file.write_text(type_text, encoding="utf-8")
    return [
        f"ENV_PREPARE_HOMOGRAM_LIBHOMOGRAPE_TYPES={action} "
        + format_path_for_display(type_file, start=repo_dir)
    ]


def _prepare_homogram_native_dist(repo_dir: Path) -> list[str]:
    native_dir = repo_dir / "features" / "home" / "src" / "main" / "native" / "homogrape"
    if not (native_dir / "Cargo.toml").is_file():
        return []

    notes: list[str] = []
    config_file = native_dir / "src" / "tg" / "config.rs"
    config_template = native_dir / "src" / "tg" / "config.rs.template"
    if not config_file.is_file() and config_template.is_file():
        shutil.copyfile(config_template, config_file)
        notes.append(
            "ENV_PREPARE_HOMOGRAM_NATIVE_CONFIG=created "
            + format_path_for_display(config_file, start=repo_dir)
        )

    dist_dir = native_dir / "dist"
    dist_lib = dist_dir / "arm64-v8a" / "libhomogrape.so"
    type_file = dist_dir / "index.d.ts"
    if dist_lib.is_file() and type_file.is_file():
        notes.append("ENV_PREPARE_HOMOGRAM_NATIVE_DIST=present")
        return notes

    native_rel = Path("features/home/src/main/native/homogrape")
    source = _find_populated_homogram_native_source(repo_dir, native_rel)
    source_lib = source / "dist" / "arm64-v8a" / "libhomogrape.so" if source else None
    source_types = source / "dist" / "index.d.ts" if source else None
    if source_lib is None or source_types is None or not source_lib.is_file() or not source_types.is_file():
        raise StructuredToolError(
            code="local_homogram_native_dist_missing",
            message="Homogram native artifacts are missing from the local arkeval repository pool.",
            details={"expected_lib": str(dist_lib), "expected_types": str(type_file)},
        )
    dist_lib.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source_lib, dist_lib)
    shutil.copy2(source_types, type_file)
    notes.append(
        "ENV_PREPARE_HOMOGRAM_NATIVE_DIST=copied "
        + format_path_for_display(source / "dist", start=repo_dir)
    )
    return notes


def _prepare_homogram_missing_debug_signing(repo_dir: Path) -> list[str]:
    dist_dir = repo_dir / "features" / "home" / "src" / "main" / "native" / "homogrape" / "dist"
    build_profile = repo_dir / "build-profile.json5"
    if not (dist_dir / "oh-package.json5").is_file() or not build_profile.is_file():
        return []

    original = build_profile.read_text(encoding="utf-8", errors="replace")
    if '"storeFile": "./signing/keystore.p12"' not in original:
        return []

    missing_signing_materials = [
        repo_dir / "signing" / "keystore.p12",
        repo_dir / "signing" / "Homogram_Debug.cer",
        repo_dir / "signing" / "homogram_debug.p7b",
    ]
    if all(path.is_file() for path in missing_signing_materials):
        return ["ENV_PREPARE_HOMOGRAM_DEBUG_SIGNING=present"]

    data = parse_json5_text(original)
    app = data.get("app") if isinstance(data, dict) else None
    if not isinstance(app, dict) or not isinstance(app.get("signingConfigs"), list):
        return []

    signing_configs = app.get("signingConfigs")
    if not signing_configs:
        return ["ENV_PREPARE_HOMOGRAM_DEBUG_SIGNING=already_empty"]

    if not any(
        isinstance(item, dict)
        and isinstance(item.get("material"), dict)
        and item.get("material", {}).get("storeFile") == "./signing/keystore.p12"
        for item in signing_configs
    ):
        return []

    app["signingConfigs"] = []
    build_profile.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return [
        "ENV_PREPARE_HOMOGRAM_DEBUG_SIGNING=cleared_missing_materials "
        + format_path_for_display(build_profile, start=repo_dir)
    ]


def _prepare_upgrade_popup_legacy_shims(repo_dir: Path) -> list[str]:
    if not repo_dir.as_posix().replace("\\", "/").endswith("/ETSUI/UpgradePopup"):
        return []

    replacements = {
        repo_dir / "build-profile.json5": [
            ("compileSdkVersion\": 9", "compileSdkVersion\": 10"),
            ("compileSdkVersion\":9", "compileSdkVersion\":10"),
            ("compatibleSdkVersion\": 9", "compatibleSdkVersion\": 10"),
            ("compatibleSdkVersion\":9", "compatibleSdkVersion\":10"),
        ],
        repo_dir / "entry/src/main/ets/Application/MyAbilityStage.ts": [
            ("@ohos.application.AbilityStage", "@ohos.app.ability.AbilityStage"),
        ],
        repo_dir / "entry/src/main/ets/MainAbility/MainAbility.ts": [
            ("import Ability from '@ohos.application.Ability'", "import UIAbility from '@ohos.app.ability.UIAbility'"),
            ("extends Ability", "extends UIAbility"),
            (
                "    await this.context.requestPermissionsFromUser(['ohos.permission.INTERNET'])\n",
                "",
            ),
        ],
    }
    notes: list[str] = []
    for path, pairs in replacements.items():
        if not path.is_file():
            continue
        original = path.read_text(encoding="utf-8", errors="replace")
        patched = original
        for old, new in pairs:
            patched = patched.replace(old, new)
        if patched == original:
            continue
        path.write_text(patched, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_UPGRADE_POPUP_LEGACY_SHIM="
            + format_path_for_display(path, start=repo_dir)
        )
    source_package = repo_dir / "updatedialog"
    linked_package = repo_dir / "node_modules/@ohos/updatedialog"
    if source_package.is_dir() and not linked_package.exists():
        _link_legacy_sdk_component(source_package, linked_package)
        notes.append("ENV_PREPARE_UPGRADE_POPUP_LOCAL_PACKAGE=@ohos/updatedialog")
    return notes


