def _prepare_ijkplayer_prebuilt_har_dependency(repo_dir: Path) -> list[str]:
    if repo_dir.name != "ohos_ijkplayer":
        return []
    native_dependency = (
        repo_dir
        / "ijkplayer/src/main/cpp/third_party/freetype2/arm64-v8a"
    )
    if native_dependency.is_dir():
        return []

    notes: list[str] = []
    entry_package = repo_dir / "entry/oh-package.json5"
    if entry_package.is_file():
        original = entry_package.read_text(encoding="utf-8", errors="replace")
        patched = original.replace('"file:../ijkplayer"', '"2.0.7-rc.3"')
        if patched != original:
            entry_package.write_text(patched, encoding="utf-8")
            notes.append("ENV_PREPARE_IJKPLAYER_PREBUILT_HAR=entry/oh-package.json5")

    build_profile = repo_dir / "build-profile.json5"
