def _prepare_legacy_qrcode_install_permissions(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/ETSUI/QRCode"):
        return []

    notes: list[str] = []
    host_scenario = repo_dir / "entry" / "src" / "ohosTest" / "host_ui_scenarios.json"
    needs_saved_image_write = (
        host_scenario.is_file()
        and "assertLatestSavedQrCrop" in host_scenario.read_text(encoding="utf-8", errors="replace")
    )
    module_json = repo_dir / "entry" / "src" / "main" / "module.json5"
    if module_json.is_file():
        original = module_json.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            data = None
        module = data.get("module") if isinstance(data, dict) else None
        permissions = module.get("requestPermissions") if isinstance(module, dict) else None
        if needs_saved_image_write and isinstance(module, dict):
            permissions = permissions if isinstance(permissions, list) else []
            existing = {
                item.get("name")
                for item in permissions
                if isinstance(item, dict) and isinstance(item.get("name"), str)
            }
            changed = False
            for name in ("ohos.permission.WRITE_MEDIA", "ohos.permission.READ_MEDIA"):
                if name not in existing:
                    permissions.append({"name": name})
                    changed = True
            blocked = {"ohos.permission.CAPTURE_SCREEN"}
            filtered = [
                item for item in permissions
                if not (isinstance(item, dict) and item.get("name") in blocked)
            ]
            if len(filtered) != len(permissions):
                changed = True
            if changed:
                module["requestPermissions"] = filtered
                module_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
                notes.append("ENV_PREPARE_QRCODE_PERMISSIONS=media_write_for_saved_qr_crop")
        elif isinstance(permissions, list):
            blocked = {
                "ohos.permission.CAPTURE_SCREEN",
                "ohos.permission.READ_MEDIA",
                "ohos.permission.WRITE_MEDIA",
            }
            filtered = [
                item for item in permissions
                if not (isinstance(item, dict) and item.get("name") in blocked)
            ]
            if len(filtered) != len(permissions):
                if filtered:
                    module["requestPermissions"] = filtered
                else:
                    module.pop("requestPermissions", None)
                module_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
                notes.append("ENV_PREPARE_QRCODE_PERMISSIONS=removed_install_blocking_permissions")

    main_ability = repo_dir / "entry" / "src" / "main" / "ets" / "MainAbility" / "MainAbility.ts"
    if main_ability.is_file():
        original = main_ability.read_text(encoding="utf-8", errors="replace")
        patched = original.replace("  'ohos.permission.CAPTURE_SCREEN',\n", "")
        patched = patched.replace("'ohos.permission.CAPTURE_SCREEN'", "")
        if needs_saved_image_write:
            if "'ohos.permission.WRITE_MEDIA'" not in patched:
                patched = patched.replace(
                    "const PERMISSIONS: Array<string> = [",
                    "const PERMISSIONS: Array<string> = [\n  'ohos.permission.WRITE_MEDIA',",
                )
            if "'ohos.permission.READ_MEDIA'" not in patched:
                patched = patched.replace(
                    "const PERMISSIONS: Array<string> = [",
                    "const PERMISSIONS: Array<string> = [\n  'ohos.permission.READ_MEDIA',",
                )
        else:
            patched = patched.replace("  'ohos.permission.READ_MEDIA',\n", "")
            patched = patched.replace("  'ohos.permission.WRITE_MEDIA',\n", "")
        if patched != original:
            main_ability.write_text(patched, encoding="utf-8")
            if needs_saved_image_write:
                notes.append("ENV_PREPARE_QRCODE_PERMISSIONS=runtime_media_request_for_saved_qr_crop")
            else:
                notes.append("ENV_PREPARE_QRCODE_PERMISSIONS=removed_runtime_media_permission_request")
    return notes


QRCODE_SCREENSHOT_API_SHIM = """declare namespace screenshot {
  export interface ScreenshotRect {
    left: number;
    top: number;
    width: number;
    height: number;
  }

  export interface ScreenshotSize {
    width: number;
    height: number;
  }

  export interface ScreenshotOptions {
    screenRect: ScreenshotRect;
    imageSize: ScreenshotSize;
    rotation?: number;
    displayId?: number;
  }

  export function save(options: ScreenshotOptions, callback: (err: Error | undefined, data: import('@ohos.multimedia.image').PixelMap) => void): void;
}

export default screenshot;
"""


def _prepare_legacy_qrcode_screenshot_local_api(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/ETSUI/QRCode"):
        return []

    ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    if not ets_root.is_dir():
        return []

    target = ets_root / "@ohos.screenshot.d.ts"
    if not target.is_file() or target.read_text(encoding="utf-8", errors="replace") != QRCODE_SCREENSHOT_API_SHIM:
        target.write_text(QRCODE_SCREENSHOT_API_SHIM, encoding="utf-8")
    return [
        "ENV_PREPARE_QRCODE_SCREENSHOT_LOCAL_API="
        + format_path_for_display(target, start=repo_dir)
    ]


def _prepare_screenshot_sdk9_api_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/SystemFeature/Media/Screenshot"):
        return []

    ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    feature_root = repo_dir / "Feature" / "src" / "main" / "ets"
    if not ets_root.is_dir() or not feature_root.is_dir():
        return []

    notes: list[str] = []
    for root in (ets_root, feature_root):
        screenshot_target = root / "@ohos.screenshot.d.ts"
        if _copy_installed_sdk_api_file("@ohos.screenshot.d.ts", screenshot_target, component="ets"):
            notes.append(
                "ENV_PREPARE_SCREENSHOT_LOCAL_API="
                + format_path_for_display(screenshot_target, start=repo_dir)
            )
        screenshot_text = screenshot_target.read_text(encoding="utf-8", errors="replace") if screenshot_target.is_file() else ""
        if "function save(" not in screenshot_text:
            if not screenshot_text.strip():
                screenshot_text = QRCODE_SCREENSHOT_API_SHIM
            else:
                screenshot_text = screenshot_text.replace(
                    "function capture(options?: CaptureOption): Promise<image.PixelMap>;",
                    (
                        "function capture(options?: CaptureOption): Promise<image.PixelMap>;\n"
                        "    function save(options?: ScreenshotOptions): Promise<image.PixelMap>;"
                    ),
                )
                if "interface ScreenshotOptions" not in screenshot_text:
                    screenshot_text = screenshot_text.replace(
                        "interface CaptureOption {",
                        (
                            "interface ScreenshotOptions {\n"
                            "        screenRect?: Rect;\n"
                            "        imageSize?: { width: number; height: number };\n"
                            "        rotation?: number;\n"
                            "        displayId?: number;\n"
                            "    }\n"
                            "    interface CaptureOption {"
                        ),
                    )
            screenshot_target.write_text(screenshot_text, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_SCREENSHOT_SAVE_API="
                + format_path_for_display(screenshot_target, start=repo_dir)
            )

        display_target = root / "@ohos.display.d.ts"
        copied_display = _copy_installed_sdk_api_file("@ohos.display.d.ts", display_target, component="ets")
        display_text = display_target.read_text(encoding="utf-8", errors="replace") if display_target.is_file() else ""
        if "hasPrivateWindow" not in display_text:
            if not display_text.strip():
                display_text = "declare namespace display {\n}\n\nexport default display;\n"
            display_text = display_text.rstrip() + "\n\ndeclare namespace display {\n  export function hasPrivateWindow(displayId?: number): boolean;\n}\n"
            display_target.write_text(display_text, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_SCREENSHOT_DISPLAY_API="
                + format_path_for_display(display_target, start=repo_dir)
            )
        elif copied_display:
            notes.append(
                "ENV_PREPARE_SCREENSHOT_DISPLAY_API="
                + format_path_for_display(display_target, start=repo_dir)
            )
    return notes


def _prepare_qrcode_scan_install_permissions(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/BasicFeature/Media/QRCodeScan"):
        return []

    module_json = repo_dir / "entry" / "src" / "main" / "module.json5"
    if not module_json.is_file():
        return []

    original = module_json.read_text(encoding="utf-8", errors="replace")
    try:
        data = parse_json5_text(original)
    except Exception:
        return []

    module = data.get("module") if isinstance(data, dict) else None
    permissions = module.get("requestPermissions") if isinstance(module, dict) else None
    if not isinstance(permissions, list):
        return []

    blocked = {
        "ohos.permission.CAMERA",
        "ohos.permission.MEDIA_LOCATION",
        "ohos.permission.READ_IMAGEVIDEO",
        "ohos.permission.WRITE_IMAGEVIDEO",
    }
    filtered = [
        item for item in permissions
        if not (isinstance(item, dict) and item.get("name") in blocked)
    ]
    if len(filtered) == len(permissions):
        return []

    if filtered:
        module["requestPermissions"] = filtered
    else:
        module.pop("requestPermissions", None)
    module_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return ["ENV_PREPARE_QRCODESCAN_PERMISSIONS=removed_install_blocking_permissions"]


def _prepare_legacy_qrcode_component_chain_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/ETSUI/QRCode"):
        return []

    candidate_dirs = [
        repo_dir / "entry" / "src" / "main" / "ets" / "pages",
        repo_dir / "entry" / "src" / "ohosTest" / "ets" / "testability" / "pages",
    ]
    notes: list[str] = []
    pattern = re.compile(r"(?m)^([ \t]+})\r?\n[ \t]+(\.)")
    for candidate_dir in candidate_dirs:
        if not candidate_dir.is_dir():
            continue
        for path in sorted(candidate_dir.glob("*.ets")):
            original = path.read_text(encoding="utf-8", errors="replace")
            patched = pattern.sub(r"\1\2", original)
            if patched == original:
                continue
            path.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_QRCODE_COMPONENT_CHAIN_SHIM="
                + format_path_for_display(path, start=repo_dir)
            )
    return notes


