def _prepare_international_install_permissions(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/SystemFeature/Internationalnation/International"):
        return []

    module_json = repo_dir / "entry" / "src" / "main" / "module.json5"
    if not module_json.is_file():
        return []

    original = module_json.read_text(encoding="utf-8", errors="replace")
    try:
        data = parse_json5_text(original)
    except Exception:
        return []

    module = data.get("module") if isinstance(data, dict) else None
    if not isinstance(module, dict):
        return []

    permissions = module.get("requestPermissions")
    if not isinstance(permissions, list):
        return []

    blocked = {
        "ohos.permission.UPDATE_CONFIGURATION",
        "ohos.permission.SET_TIME_ZONE",
        "ohos.permission.SET_TIME",
    }
    filtered = [
        item for item in permissions
        if not (isinstance(item, dict) and item.get("name") in blocked)
    ]
    if len(filtered) == len(permissions):
        return []

    if filtered:
        module["requestPermissions"] = filtered
    else:
        module.pop("requestPermissions", None)
    module_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return ["ENV_PREPARE_INTERNATIONAL_PERMISSIONS=removed_install_blocking_time_permissions"]


def _prepare_international_legacy_build_shims(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/SystemFeature/Internationalnation/International"):
        return []

    notes: list[str] = []
    build_profile = repo_dir / "build-profile.json5"
    if build_profile.is_file():
        original = build_profile.read_text(encoding="utf-8", errors="replace")
        patched = re.sub(
            r'((?:"compatibleSdkVersion"|compatibleSdkVersion)\s*:\s*)10',
            r"\g<1>9",
            original,
            count=1,
        )
        if patched != original:
            build_profile.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_INTERNATIONAL_COMPATIBLE_SDK="
                + format_path_for_display(build_profile, start=repo_dir)
                + " compatibleSdkVersion=10->9"
            )

    ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    if not ets_root.is_dir():
        return notes

    i18n_target = ets_root / "@ohos.i18n.d.ts"
    if _copy_installed_sdk_api_file("@ohos.i18n.d.ts", i18n_target, component="ets"):
        _append_to_export_class(i18n_target, "System", INTERNATIONAL_I18N_SYSTEM_COMPAT)
        notes.append(
            "ENV_PREPARE_INTERNATIONAL_LOCAL_API="
            + format_path_for_display(i18n_target, start=repo_dir)
        )

    system_date_time_target = ets_root / "@ohos.systemDateTime.d.ts"
    if _copy_installed_sdk_api_file("@ohos.systemDateTime.d.ts", system_date_time_target, component="ets"):
        _append_to_declare_namespace(
            system_date_time_target,
            "systemDateTime",
            INTERNATIONAL_SYSTEM_DATE_TIME_COMPAT,
        )
        notes.append(
            "ENV_PREPARE_INTERNATIONAL_LOCAL_API="
            + format_path_for_display(system_date_time_target, start=repo_dir)
        )

    return notes


def _prepare_docs_internationalization_legacy_build_shims(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/DocsSample/International/Internationalization"):
        return []

    notes: list[str] = []
    ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    if ets_root.is_dir():
        i18n_target = ets_root / "@ohos.i18n.d.ts"
        if _copy_installed_sdk_api_file("@ohos.i18n.d.ts", i18n_target, component="ets"):
            _append_to_export_class(i18n_target, "System", DOCS_INTERNATIONALIZATION_I18N_SYSTEM_COMPAT)
            notes.append(
                "ENV_PREPARE_DOCS_INTERNATIONALIZATION_LOCAL_API="
                + format_path_for_display(i18n_target, start=repo_dir)
            )
        intl_target = ets_root / "@ohos.intl.d.ts"
        if _copy_installed_sdk_api_file("@ohos.intl.d.ts", intl_target, component="ets"):
            notes.append(
                "ENV_PREPARE_DOCS_INTERNATIONALIZATION_LOCAL_API="
                + format_path_for_display(intl_target, start=repo_dir)
            )
        kit_target = ets_root / "@kit.LocalizationKit.d.ts"
        if i18n_target.is_file() and intl_target.is_file():
            kit_target.write_text(
                "import i18n from './@ohos.i18n';\n"
                "import intl from './@ohos.intl';\n"
                "export { i18n, intl };\n",
                encoding="utf-8",
            )
            notes.append(
                "ENV_PREPARE_DOCS_INTERNATIONALIZATION_LOCAL_API="
                + format_path_for_display(kit_target, start=repo_dir)
            )

    resource_values = {
        "CountryWordChina": "中国",
        "CountryWordGermany": "德国",
        "CountryWordUSA": "美国",
        "CountryWordFrance": "法国",
    }
    resource_root = repo_dir / "entry" / "src" / "main" / "resources"
    patched_files = 0
    for string_json in sorted(resource_root.glob("base/element/strValue.json")):
        try:
            data = json.loads(string_json.read_text(encoding="utf-8"))
        except Exception:
            continue
        items = data.get("string") if isinstance(data, dict) else None
        if not isinstance(items, list):
            continue
        existing = {
            item.get("name")
            for item in items
            if isinstance(item, dict) and isinstance(item.get("name"), str)
        }
        changed = False
        for name, value in resource_values.items():
            if name not in existing:
                items.append({"name": name, "value": value})
                changed = True
        if changed:
            string_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            patched_files += 1
    if patched_files:
        notes.append(f"ENV_PREPARE_DOCS_INTERNATIONALIZATION_RESOURCES=patched_country_words count={patched_files}")

    return notes


def _prepare_scrollable_component_legacy_build_shims(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/DocsSample/ArkUISample/ScrollableComponent"):
        return []

    ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    if not ets_root.is_dir():
        return []

    notes: list[str] = []

    ability_kit = ets_root / "@kit.AbilityKit.d.ts"
    source_ability_kit = _find_installed_sdk_kit_file("@kit.AbilityKit.d.ts", component="ets")
    if source_ability_kit is not None:
        ability_kit.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source_ability_kit, ability_kit)
        original = ability_kit.read_text(encoding="utf-8", errors="replace")
        if "updateConfiguration(config: Configuration" not in original:
            patched = original.replace(
                "export {",
                "import { BusinessError } from '@ohos.base';\n"
                "declare namespace xbScrollableAbilityManagerCompat {\n"
                "  function updateConfiguration(config: Configuration, callback: (err: BusinessError) => void): void;\n"
                "}\n"
                "declare const abilityManager: typeof xbScrollableAbilityManagerCompat;\n"
                "export {",
                1,
            )
            patched = patched.replace(" abilityManager,", " abilityManager,")
            ability_kit.write_text(patched, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_SCROLLABLE_COMPONENT_LOCAL_API="
            + format_path_for_display(ability_kit, start=repo_dir)
        )

    arkui_kit = ets_root / "@kit.ArkUI.d.ts"
    source_arkui_kit = _find_installed_sdk_kit_file("@kit.ArkUI.d.ts", component="ets")
    if source_arkui_kit is not None:
        arkui_kit.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source_arkui_kit, arkui_kit)
        original = arkui_kit.read_text(encoding="utf-8", errors="replace")
        if "xbScrollableUiAppearanceCompat" not in original:
            patched = original.replace(
                "export {",
                "declare namespace xbScrollableUiAppearanceCompat {\n"
                "  enum DarkMode { ALWAYS_LIGHT = 0, ALWAYS_DARK = 1 }\n"
                "  function getDarkMode(): DarkMode;\n"
                "  function setDarkMode(mode: DarkMode): Promise<void>;\n"
                "}\n"
                "declare const uiAppearance: typeof xbScrollableUiAppearanceCompat;\n"
                "export {",
                1,
            )
            export_pattern = re.compile(r"export \{(?P<body>.*)\};", re.DOTALL)
            match = export_pattern.search(patched)
            if match is not None and "uiAppearance" not in match.group("body"):
                insert_at = match.end() - 3
                patched = patched[:insert_at] + ", uiAppearance" + patched[insert_at:]
            arkui_kit.write_text(patched, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_SCROLLABLE_COMPONENT_LOCAL_API="
            + format_path_for_display(arkui_kit, start=repo_dir)
        )

    age_friendly_tabs = ets_root / "pages" / "tabs" / "AgeFriendlyTabs.ets"
    if age_friendly_tabs.is_file():
        original = age_friendly_tabs.read_text(encoding="utf-8", errors="replace")
        patched = original.replace(
            "import { promptAction, uiAppearance } from '@kit.ArkUI';",
            "import { promptAction } from '@kit.ArkUI';",
            1,
        )
        compat = (
            "namespace xbScrollableUiAppearanceCompat {\n"
            "  export enum DarkMode { ALWAYS_LIGHT = 0, ALWAYS_DARK = 1 }\n"
            "  export function getDarkMode(): DarkMode {\n"
            "    return DarkMode.ALWAYS_LIGHT;\n"
            "  }\n"
            "  export function setDarkMode(_mode: DarkMode): Promise<void> {\n"
            "    return Promise.resolve();\n"
            "  }\n"
            "}\n\n"
        )
        if "namespace xbScrollableUiAppearanceCompat" not in patched:
            patched = patched.replace(
                "import { promptAction } from '@kit.ArkUI';\n\n",
                "import { promptAction } from '@kit.ArkUI';\n\n" + compat,
                1,
            )
        patched = patched.replace("uiAppearance.", "xbScrollableUiAppearanceCompat.")
        if patched != original:
            age_friendly_tabs.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_SCROLLABLE_COMPONENT_AGE_FRIENDLY_TABS_SHIM="
                + format_path_for_display(age_friendly_tabs, start=repo_dir)
            )

    return notes


def _prepare_parallel_sample_hvigor_dependency_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not _is_parallel_sample_project(repo_dir):
        return []

    notes: list[str] = []

    build_profile = repo_dir / "build-profile.json5"
    if build_profile.is_file():
        original = build_profile.read_text(encoding="utf-8", errors="replace")
        patched = re.sub(
            r'^\s*(?:"arkTSVersion"|arkTSVersion)\s*:\s*["\']1\.2["\']\s*,?\s*\r?\n',
            "",
            original,
            flags=re.MULTILINE,
        )
        if patched != original:
            build_profile.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_PARALLEL_SAMPLE_ARKTS_VERSION="
                + format_path_for_display(build_profile, start=repo_dir)
                + " removed_unsupported_1.2"
            )

    hvigor_config = repo_dir / "hvigor" / "hvigor-config.json5"
    if hvigor_config.is_file():
        original = hvigor_config.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            data = None
        dependencies = data.get("dependencies") if isinstance(data, dict) else None
        if isinstance(dependencies, dict) and "@ohos/hvigor-ohos-online-sign-plugin" in dependencies:
            dependencies.pop("@ohos/hvigor-ohos-online-sign-plugin", None)
            hvigor_config.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append(
                "ENV_PREPARE_PARALLEL_SAMPLE_HVIGOR_DEPENDENCY="
                + format_path_for_display(hvigor_config, start=repo_dir)
                + " removed_online_sign_plugin"
            )
        if isinstance(data, dict) and data.get("modelVersion") == "5.0.2":
            data["modelVersion"] = "5.0.0"
            hvigor_config.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append(
                "ENV_PREPARE_PARALLEL_SAMPLE_HVIGOR_MODEL_VERSION="
                + format_path_for_display(hvigor_config, start=repo_dir)
                + " 5.0.2->5.0.0"
            )

    oh_package = repo_dir / "oh-package.json5"
    if oh_package.is_file():
        original = oh_package.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            data = None
        if isinstance(data, dict) and data.get("modelVersion") == "5.0.2":
            data["modelVersion"] = "5.0.0"
            oh_package.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append(
                "ENV_PREPARE_PARALLEL_SAMPLE_PACKAGE_MODEL_VERSION="
                + format_path_for_display(oh_package, start=repo_dir)
                + " 5.0.2->5.0.0"
            )

    module_json = repo_dir / "entry" / "src" / "main" / "module.json5"
    if module_json.is_file():
        original = module_json.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            data = None
        module = data.get("module") if isinstance(data, dict) else None
        device_types = module.get("deviceTypes") if isinstance(module, dict) else None
        if isinstance(device_types, list) and device_types != ["default"]:
            module["deviceTypes"] = ["default"]
            module_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append(
                "ENV_PREPARE_PARALLEL_SAMPLE_DEVICE_TYPES="
                + format_path_for_display(module_json, start=repo_dir)
                + " deviceTypes=default"
            )
    return notes


def _is_parallel_sample_project(repo_dir: Path) -> bool:
    return repo_dir.as_posix().replace("\\", "/").endswith("/code/ArkTS1.2/ParallelSample")


def _prepare_distributed_calc_install_permissions(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not (
        normalized.endswith("/code/SuperFeature/DistributedAppDev/ArkTSDistributedCalc")
        or normalized.endswith("/Preset/DistributeCalc")
    ):
        return []

    module_json = repo_dir / "entry" / "src" / "main" / "module.json5"
    if not module_json.is_file():
        return []

    original = module_json.read_text(encoding="utf-8", errors="replace")
    try:
        data = parse_json5_text(original)
    except Exception:
        return []

    module = data.get("module") if isinstance(data, dict) else None
    if not isinstance(module, dict):
        return []

    permissions = module.get("requestPermissions")
    if not isinstance(permissions, list):
        return []

    blocked = {
        "ohos.permission.ACCESS_SERVICE_DM",
    }
    filtered = [
        item for item in permissions
        if not (isinstance(item, dict) and item.get("name") in blocked)
    ]
    if len(filtered) == len(permissions):
        return []

    if filtered:
        module["requestPermissions"] = filtered
    else:
        module.pop("requestPermissions", None)
    module_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return ["ENV_PREPARE_DISTRIBUTED_CALC_PERMISSIONS=removed_system_only_permissions"]


def _prepare_distributed_calc_legacy_build_shims(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/Preset/DistributeCalc"):
        return []

    notes: list[str] = []
    package_json = repo_dir / "package.json"
    if package_json.is_file():
        try:
            package_data = json.loads(package_json.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            package_data = None
        if isinstance(package_data, dict):
            dependencies = package_data.setdefault("dependencies", {})
            if isinstance(dependencies, dict) and "mathjs" not in dependencies:
                dependencies["mathjs"] = "^10.6.4"
                package_json.write_text(json.dumps(package_data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
                notes.append(
                    "ENV_PREPARE_DISTRIBUTED_CALC_MATHJS_DEPENDENCY="
                    + format_path_for_display(package_json, start=repo_dir)
                )
    if package_json.is_file() and not (repo_dir / "node_modules" / "mathjs").is_dir():
        for lock_file in (repo_dir / "package-lock.json", repo_dir / "npm-shrinkwrap.json"):
            if lock_file.is_file():
                lock_file.unlink()
                notes.append(
                    "ENV_PREPARE_DISTRIBUTED_CALC_MATHJS_LOCK_REFRESH="
                    + format_path_for_display(lock_file, start=repo_dir)
                )

    ets_root = repo_dir / "entry" / "src" / "main" / "ets" / "MainAbility"
    if ets_root.is_dir():
        target = ets_root / "@ohos.distributedHardware.deviceManager.d.ts"
        if not target.is_file() or target.read_text(encoding="utf-8", errors="replace") != GOBANG_DEVICE_MANAGER_SHIM:
            target.write_text(GOBANG_DEVICE_MANAGER_SHIM, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_DISTRIBUTED_CALC_DEVICE_MANAGER_LOCAL_API="
            + format_path_for_display(target, start=repo_dir)
        )

    ohos_test_root = repo_dir / "entry" / "src" / "ohosTest" / "ets"
    if ohos_test_root.is_dir():
        for device_manager_target in (
            ohos_test_root / "@ohos.distributedHardware.deviceManager.d.ts",
            ohos_test_root / "test" / "@ohos.distributedHardware.deviceManager.d.ts",
            ohos_test_root / "TestAbility" / "@ohos.distributedHardware.deviceManager.d.ts",
        ):
            if not device_manager_target.parent.is_dir():
                continue
            if (
                not device_manager_target.is_file()
                or device_manager_target.read_text(encoding="utf-8", errors="replace") != GOBANG_DEVICE_MANAGER_SHIM
            ):
                device_manager_target.write_text(GOBANG_DEVICE_MANAGER_SHIM, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_DISTRIBUTED_CALC_DEVICE_MANAGER_OHOSTEST_LOCAL_API="
                + format_path_for_display(device_manager_target, start=repo_dir)
            )
        for uitest_target in (
            ohos_test_root / "@ohos.uitest.d.ts",
            ohos_test_root / "test" / "@ohos.uitest.d.ts",
            ohos_test_root / "TestAbility" / "@ohos.uitest.d.ts",
        ):
            if not uitest_target.parent.is_dir():
                continue
            if (
                not uitest_target.is_file()
                or uitest_target.read_text(encoding="utf-8", errors="replace") != DISTRIBUTED_CALC_UITEST_SHIM
            ):
                uitest_target.write_text(DISTRIBUTED_CALC_UITEST_SHIM, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_DISTRIBUTED_CALC_OHOSTEST_LOCAL_API="
                + format_path_for_display(uitest_target, start=repo_dir)
            )

    return notes


def _prepare_component_collection_sdk11_ime_event(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/UI/ArkTsComponentCollection/ComponentCollection"):
        return []

    target = (
        repo_dir
        / "entry"
        / "src"
        / "main"
        / "ets"
        / "pages"
        / "animations"
        / "TransitionAnimations"
        / "floatingSample"
        / "FloatingWindowSample.ets"
    )
    if not target.is_file():
        return []

    original = target.read_text(encoding="utf-8", errors="replace")
    patched = original.replace("'imeShow'", "'imeChange'").replace('"imeShow"', '"imeChange"')
    patched = re.sub(
        r"\s*this\.inputMethodSetting\.on\('imeChange',\s*\(info: Array<inputMethod\.InputWindowInfo>\) => \{.*?\n\s*\}\);",
        "\n      // Disabled by arkagent preprocess: legacy input-method window callback is incompatible with SDK 11.",
        patched,
        flags=re.S,
    )
    patched = re.sub(
        r"\s*this\.inputMethodSetting\.off\('imeChange',\s*\(\) => \{.*?\n\s*\}\);",
        "\n    // Disabled by arkagent preprocess: matching legacy listener is not registered under SDK 11.",
        patched,
        flags=re.S,
    )
    if patched == original:
        return []
    target.write_text(patched, encoding="utf-8")
    return ["ENV_PREPARE_COMPONENT_COLLECTION_IME_EVENT=disabled_legacy_ime_listener"]


def _prepare_component_collection_install_permissions(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/UI/ArkTsComponentCollection/ComponentCollection"):
        return []

    module_json = repo_dir / "entry" / "src" / "main" / "module.json5"
    if not module_json.is_file():
        return []

    original = module_json.read_text(encoding="utf-8", errors="replace")
    blocked = [
        "ohos.permission.GET_BUNDLE_INFO",
        "ohos.permission.GET_BUNDLE_INFO_PRIVILEGED",
        "ohos.permission.REQUIRE_FORM",
    ]
    patched = original
    for name in blocked:
        patched = re.sub(
            r"\s*\{\s*[\r\n]+\s*\"name\"\s*:\s*['\"]" + re.escape(name) + r"['\"]\s*[\r\n]+\s*\},?",
            "",
            patched,
            flags=re.S,
        )
    patched = re.sub(r",\s*(\])", r"\1", patched)
    if patched == original:
        return []
    module_json.write_text(patched, encoding="utf-8")
    return ["ENV_PREPARE_COMPONENT_COLLECTION_PERMISSIONS=removed_install_blocking_permissions"]


def _prepare_work_scheduler_sdk9_api_shim(repo_dir: Path, sdk_root: Path | None) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/BasicFeature/TaskManagement/WorkScheduler"):
        return []
    if sdk_root is None:
        return []

    root = Path(sdk_root)
    if _is_sdk_component_root(root):
        sdk_parent = root.parent
    else:
        sdk_parent = root
    api9 = sdk_parent / "9" / "ets" / "api"
    api10 = sdk_parent / "10" / "ets" / "api"
    if not api9.is_dir() or not api10.is_dir():
        return []

    notes: list[str] = []
    for name in ("@ohos.bundle.installer.d.ts", "@ohos.notification.d.ts", "@ohos.wifiManager.d.ts"):
        source = api10 / name
        target = api9 / name
        if not source.is_file():
            continue
        source_text = source.read_text(encoding="utf-8", errors="replace")
        target_text = target.read_text(encoding="utf-8", errors="replace") if target.is_file() else ""
        if name == "@ohos.notification.d.ts" and "function subscribe(" in target_text:
            continue
        if name == "@ohos.wifiManager.d.ts" and "function enableWifi(" in target_text:
            continue
        if target_text == source_text:
            continue
        target.write_text(source_text, encoding="utf-8")
        notes.append(f"ENV_PREPARE_WORKSCHEDULER_SDK9_SHIM={name}")
    if notes:
        _remove_preprocess_cache_path(repo_dir, repo_dir / "build", notes)
        _remove_preprocess_cache_path(repo_dir, repo_dir / "entry" / "build", notes)
        _remove_preprocess_cache_path(repo_dir, repo_dir / ".hvigor", notes)
    return notes


def _prepare_work_scheduler_ohos_test_runner(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/BasicFeature/TaskManagement/WorkScheduler"):
        return []

    runner = repo_dir / "entry" / "src" / "ohosTest" / "ets" / "testrunner" / "OpenHarmonyTestRunner.ts"
    if not runner.is_file():
        return []

    test_ability = repo_dir / "entry" / "src" / "ohosTest" / "ets" / "testability" / "TestAbility.ets"
    patched_test_ability = """import AbilityDelegatorRegistry from '@ohos.app.ability.abilityDelegatorRegistry';
import UIAbility from '@ohos.app.ability.UIAbility';
import window from '@ohos.window';
import { Hypium } from '@ohos/hypium';
import testsuite from '../test/List.test';
import { Logger } from '../utils/Logger';

let abilityDelegator: AbilityDelegatorRegistry.AbilityDelegator;
let abilityDelegatorArguments: AbilityDelegatorRegistry.AbilityDelegatorArgs;
let isTestStarted: boolean = false;

function startHypiumTest(): void {
  if (isTestStarted) {
    return;
  }
  isTestStarted = true;
  Logger.info('start run testcase!!!');
  Hypium.hypiumTest(abilityDelegator, abilityDelegatorArguments, testsuite);
}

export default class TestAbility extends UIAbility {
  onCreate(want, launchParam) {
    Logger.info('TestAbility onCreate');
    Logger.info('want param:' + JSON.stringify(want));
    Logger.info('launchParam:' + JSON.stringify(launchParam));
    abilityDelegator = AbilityDelegatorRegistry.getAbilityDelegator();
    abilityDelegatorArguments = AbilityDelegatorRegistry.getArguments();
  }

  onDestroy() {
    Logger.info('TestAbility onDestroy');
  }

  onWindowStageCreate(windowStage: window.WindowStage) {
    Logger.info('TestAbility onWindowStageCreate');
    windowStage.loadContent('testability/pages/Index', (err, data) => {
      if (err.code) {
        Logger.error('Failed to load the content. Cause: ' + JSON.stringify(err));
        return;
      }
      Logger.info('Succeeded in loading the content. Data: ' + JSON.stringify(data));
      startHypiumTest();
    });
  }

  onWindowStageDestroy() {
    Logger.info('TestAbility onWindowStageDestroy');
  }

  onForeground() {
    Logger.info('TestAbility onForeground');
  }

  onBackground() {
    Logger.info('TestAbility onBackground');
  }
}
"""
    notes: list[str] = []
    if test_ability.is_file() and test_ability.read_text(encoding="utf-8", errors="replace") != patched_test_ability:
        test_ability.write_text(patched_test_ability, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_WORKSCHEDULER_OHOSTEST_TEST_ABILITY="
            + format_path_for_display(test_ability, start=repo_dir)
            + " delayed_hypium_until_window_loaded"
        )

    patched = """import TestRunner from '@ohos.application.testRunner';
import AbilityDelegatorRegistry from '@ohos.app.ability.abilityDelegatorRegistry';
import { Logger } from '../utils/Logger';

function translateParamsToString(parameters) {
  const keySet = new Set([
    '-s class', '-s notClass', '-s suite', '-s itName',
    '-s level', '-s testType', '-s size', '-s timeout',
    '-s package'
  ]);
  let targetParams = '';
  for (const key in parameters) {
    if (keySet.has(key)) {
      targetParams += ' ' + key + ' ' + parameters[key];
    }
  }
  return targetParams.trim();
}

export default class OpenHarmonyTestRunner implements TestRunner {
  onPrepare() {
    Logger.info('OpenHarmonyTestRunner OnPrepare');
  }

  onRun() {
    Logger.info('OpenHarmonyTestRunner onRun start TestAbility');
    let abilityDelegator = AbilityDelegatorRegistry.getAbilityDelegator();
    let abilityDelegatorArguments = AbilityDelegatorRegistry.getArguments();
    let cmd = 'aa start -d 0 -a TestAbility -b ' + abilityDelegatorArguments.bundleName + ' -m entry_test';
    cmd += ' ' + translateParamsToString(abilityDelegatorArguments.parameters);
    let debug = abilityDelegatorArguments.parameters['-D'];
    if (debug == 'true') {
      cmd += ' -D';
    }
    Logger.info('cmd : %{public}s', cmd);
    abilityDelegator.executeShellCommand(cmd, (err, data) => {
      Logger.info('executeShellCommand err: ' + JSON.stringify(err));
      Logger.info('executeShellCommand data: ' + JSON.stringify(data));
    });
    Logger.info('OpenHarmonyTestRunner onRun end');
  }
}
"""
    original = runner.read_text(encoding="utf-8", errors="replace")
    if original == patched:
        if notes:
            _remove_preprocess_cache_path(repo_dir, repo_dir / "entry" / "build", notes)
            _remove_preprocess_cache_path(repo_dir, repo_dir / ".hvigor", notes)
        return notes
    runner.write_text(patched, encoding="utf-8")
    notes.append(
        "ENV_PREPARE_WORKSCHEDULER_OHOSTEST_RUNNER="
        + format_path_for_display(runner, start=repo_dir)
        + " entry_test_module_start"
    )
    _remove_preprocess_cache_path(repo_dir, repo_dir / "entry" / "build", notes)
    _remove_preprocess_cache_path(repo_dir, repo_dir / ".hvigor", notes)
    return notes


def _prepare_dlpmanager_sdk11_fileaccess_shim(repo_dir: Path, sdk_root: Path | None) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/BasicFeature/Security/DLPManager"):
        return []
    if sdk_root is None:
        return []

    root = Path(sdk_root)
    sdk_parent = root.parent if _is_sdk_component_root(root) else root
    api10 = sdk_parent / "10" / "ets" / "api"
    api11 = sdk_parent / "11" / "ets" / "api"
    source = api10 / "@ohos.file.fileAccess.d.ts"
    target = api11 / "@ohos.file.fileAccess.d.ts"
    if not source.is_file() or not target.parent.is_dir():
        return []

    source_text = source.read_text(encoding="utf-8", errors="replace")
    target_text = target.read_text(encoding="utf-8", errors="replace") if target.is_file() else ""
    if "interface FileAccessHelper" in target_text and "function createFileAccessHelper" in target_text:
        return []
    if target_text == source_text:
        return []

    target.write_text(source_text, encoding="utf-8")
    notes = ["ENV_PREPARE_DLPMANAGER_SDK11_SHIM=@ohos.file.fileAccess.d.ts"]
    _remove_preprocess_cache_path(repo_dir, repo_dir / "build", notes)
    _remove_preprocess_cache_path(repo_dir, repo_dir / "entry" / "build", notes)
    _remove_preprocess_cache_path(repo_dir, repo_dir / ".hvigor", notes)
    return notes


def _prepare_media_collections_api10_drm_shim(repo_dir: Path, sdk_root: Path | None) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/BasicFeature/FileManagement/MediaCollections"):
        return []
    if sdk_root is None:
        return []

    root = Path(sdk_root)
    sdk_parent = root.parent if _is_sdk_component_root(root) else root
    api10 = sdk_parent / "10" / "ets" / "api"
    api11 = sdk_parent / "11" / "ets" / "api"
    notes: list[str] = []

    drm_source = api11 / "@ohos.multimedia.drm.d.ts"
    drm_target = api10 / "@ohos.multimedia.drm.d.ts"
    if drm_source.is_file() and api10.is_dir():
        source_text = drm_source.read_text(encoding="utf-8", errors="replace")
        target_text = drm_target.read_text(encoding="utf-8", errors="replace") if drm_target.is_file() else ""
        if target_text != source_text:
            drm_target.write_text(source_text, encoding="utf-8")
            notes.append("ENV_PREPARE_MEDIACOLLECTIONS_DRM_API10=@ohos.multimedia.drm.d.ts")

    media_target = api10 / "@ohos.multimedia.media.d.ts"
    if media_target.is_file():
        original = media_target.read_text(encoding="utf-8", errors="replace")
        patched = original
        if "import type drm from './@ohos.multimedia.drm';" not in patched:
            if "import type image from './@ohos.multimedia.image';" in patched:
                patched = patched.replace(
                    "import type image from './@ohos.multimedia.image';",
                    "import type image from './@ohos.multimedia.image';\nimport type drm from './@ohos.multimedia.drm';",
                    1,
                )
            elif 'import audio from "./@ohos.multimedia.audio";' in patched:
                patched = patched.replace(
                    'import audio from "./@ohos.multimedia.audio";',
                    'import audio from "./@ohos.multimedia.audio";\nimport type drm from \'./@ohos.multimedia.drm\';',
                    1,
                )
        patched = patched.replace(
            "setDecryptConfig(mediaKeySession: drm.MediaKeySession, secureVideoPath: boolean): void;",
            "setDecryptionConfig(mediaKeySession: drm.MediaKeySession, secureVideoPath: boolean): void;",
        )
        if "setDecryptConfig(mediaKeySession: drm.MediaKeySession, secureVideoPath: boolean): void;" not in patched:
            avplayer_marker = "interface AVPlayer {"
            if avplayer_marker in patched:
                patched = patched.replace(
                    avplayer_marker,
                    (
                        avplayer_marker
                        + "\n    setDecryptConfig(mediaKeySession: drm.MediaKeySession, secureVideoPath: boolean): void;"
                    ),
                    1,
                )
            elif "setDecryptionConfig(mediaKeySession: drm.MediaKeySession, secureVideoPath: boolean): void;" in patched:
                patched = patched.replace(
                    "setDecryptionConfig(mediaKeySession: drm.MediaKeySession, secureVideoPath: boolean): void;",
                    (
                        "setDecryptionConfig(mediaKeySession: drm.MediaKeySession, secureVideoPath: boolean): void;\n"
                        "        setDecryptConfig(mediaKeySession: drm.MediaKeySession, secureVideoPath: boolean): void;"
                    ),
                    1,
                )
        if "on(type: 'mediaKeySystemInfoUpdate'" in patched and "on(type: 'drmInfoUpdate'" not in patched:
            patched = re.sub(
                r"(on\(type: 'mediaKeySystemInfoUpdate',[^\n]+?\): void;)",
                r"\1\n        on(type: 'drmInfoUpdate', callback: (mediaKeySystemInfo: Array<drm.MediaKeySystemInfo>) => void): void;",
                patched,
                count=1,
            )
        if "on(type: 'drmInfoUpdate'" not in patched and "on(type: 'timeUpdate', callback: Callback<number>): void;" in patched:
            patched = patched.replace(
                "on(type: 'timeUpdate', callback: Callback<number>): void;",
                (
                    "on(type: 'drmInfoUpdate', callback: (mediaKeySystemInfo: Array<drm.MediaKeySystemInfo>) => void): void;\n"
                    "    on(type: 'timeUpdate', callback: Callback<number>): void;"
                ),
                1,
            )
        if patched != original:
            media_target.write_text(patched, encoding="utf-8")
            notes.append("ENV_PREPARE_MEDIACOLLECTIONS_MEDIA_API10=drm player aliases")

    if drm_target.is_file():
        original = drm_target.read_text(encoding="utf-8", errors="replace")
        patched = original
        patched = patched.replace(
            "generateKeySystemRequest(): Promise<ProvisionRequest>;",
            "generateKeySystemRequest(): ProvisionRequest;",
        )
        compatibility_block = """
    enum SecurityLevel {
        SECURITY_LEVEL_SW_CRYPTO = ContentProtectionLevel.CONTENT_PROTECTION_LEVEL_SW_CRYPTO
    }
    type OptionalData = OptionsData;
    type LicenseRequest = MediaKeyRequest;
    type OfflineLicenseStatus = OfflineMediaKeyStatus;
"""
        if "enum SecurityLevel" not in patched and "declare namespace drm {" in patched:
            patched = patched.replace("declare namespace drm {", "declare namespace drm {" + compatibility_block, 1)
        if "mData: Uint8Array;" not in patched:
            patched = patched.replace("data: Uint8Array;", "data: Uint8Array;\n        mData: Uint8Array;", 2)
        if "getOfflineLicenseStatus(mediaKeyId: Uint8Array): OfflineLicenseStatus;" not in patched:
            patched = patched.replace(
                "interface MediaKeySystem {",
                (
                    "interface MediaKeySystem {\n"
                    "        getOfflineLicenseStatus(mediaKeyId: Uint8Array): OfflineLicenseStatus;\n"
                    "        removeOfflineLicense(mediaKeyId: Uint8Array): void;"
                ),
                1,
            )
        if "createMediaKeySession(level: SecurityLevel): MediaKeySession;" not in patched:
            patched = patched.replace(
                "interface MediaKeySystem {",
                (
                    "interface MediaKeySystem {\n"
                    "        createMediaKeySession(level: SecurityLevel): MediaKeySession;"
                ),
                1,
            )
        if "generateLicenseRequest(mimeType: string" not in patched:
            patched = patched.replace(
                "interface MediaKeySession {",
                (
                    "interface MediaKeySession {\n"
                    "        generateLicenseRequest(mimeType: string, initData: Uint8Array, mediaKeyType: number, options?: OptionalData[]): LicenseRequest;\n"
                    "        processLicenseResponse(response: Uint8Array): Uint8Array;\n"
                    "        restoreOfflineLicense(mediaKeyId: Uint8Array): void;\n"
                    "        on(type: 'keyNeeded' | 'keyExpired' | 'vendorDefined' | 'expirationUpdated' | 'keyChanged', callback: (eventInfo: EventInfo) => void): void;\n"
                    "        off(type: 'keyNeeded' | 'keyExpired' | 'vendorDefined' | 'expirationUpdated' | 'keyChanged', callback?: (eventInfo: EventInfo) => void): void;"
                ),
                1,
            )
        if patched != original:
            drm_target.write_text(patched, encoding="utf-8")
            notes.append("ENV_PREPARE_MEDIACOLLECTIONS_DRM_API10_COMPAT=legacy aliases")

    if notes:
        _remove_preprocess_cache_path(repo_dir, repo_dir / "build", notes)
        _remove_preprocess_cache_path(repo_dir, repo_dir / "entry" / "build", notes)
        _remove_preprocess_cache_path(repo_dir, repo_dir / ".hvigor", notes)
    return notes


def _prepare_performance_library_taskpool_sdk11_shim(repo_dir: Path, sdk_root: Path | None) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/Performance/PerformanceLibrary"):
        return []
    if sdk_root is None:
        return []

    root = Path(sdk_root)
    sdk_parent = root.parent if _is_sdk_component_root(root) else root
    target = sdk_parent / "11" / "ets" / "api" / "@ohos.taskpool.d.ts"
    if not target.is_file():
        return []

    original = target.read_text(encoding="utf-8", errors="replace")
    patched = original.replace(
        "function execute(task: Task, priority?: Priority): Promise<Object>;",
        "function execute(task: Task, priority?: Priority): Promise<number>;",
    )
    if patched == original:
        return []

    target.write_text(patched, encoding="utf-8")
    notes = ["ENV_PREPARE_PERFORMANCE_TASKPOOL_SDK11_SHIM=execute_task_returns_number"]
    _remove_preprocess_cache_path(repo_dir, repo_dir / "build", notes)
    _remove_preprocess_cache_path(repo_dir, repo_dir / "product" / "phone" / "entry" / "build", notes)
    _remove_preprocess_cache_path(repo_dir, repo_dir / ".hvigor", notes)
    return notes


def _prepare_performance_library_native_threads_x86_64(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/Performance/PerformanceLibrary"):
        return []

    profile = repo_dir / "feature" / "nativeThreadsCallJS" / "build-profile.json5"
    cmake = repo_dir / "feature" / "nativeThreadsCallJS" / "src" / "main" / "cpp" / "CMakeLists.txt"
    if not profile.is_file() or not cmake.is_file():
        return []

    original = profile.read_text(encoding="utf-8", errors="replace")
    patched = _abi_filter_text_with_x86_64(original, only_x86_64=True)
    if patched == original:
        return ["ENV_PREPARE_PERFORMANCE_NATIVE_THREADS_X86_64=already_present"]

    profile.write_text(patched, encoding="utf-8")
    notes = [
        "ENV_PREPARE_PERFORMANCE_NATIVE_THREADS_X86_64="
        + format_path_for_display(profile, start=repo_dir)
    ]
    _remove_preprocess_cache_path(repo_dir, repo_dir / "feature" / "nativeThreadsCallJS" / "build", notes)
    _remove_preprocess_cache_path(repo_dir, repo_dir / "product" / "phone" / "entry" / "build", notes)
    _remove_preprocess_cache_path(repo_dir, repo_dir / "build", notes)
    _remove_preprocess_cache_path(repo_dir, repo_dir / ".hvigor", notes)
    return notes


def _prepare_stage_call_ability_runtime_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/ability/StageCallAbility"):
        return []

    main_ability = repo_dir / "entry" / "src" / "main" / "ets" / "MainAbility" / "MainAbility.ts"
    if not main_ability.is_file():
        return []
    text = main_ability.read_text(encoding="utf-8", errors="replace")
    old = """function getDm() {
    DeviceManager.createDeviceManager(BUNDLE_NAME, (error, dm) => {
        if (error) {
            Logger.error(TAG, `getDm failed with ${error.code}`)
            return;
        }
        Logger.log(TAG, 'getDm success')
        globalThis.dmClass = dm
    });
}
"""
    new = """function getDm() {
    try {
        DeviceManager.createDeviceManager(BUNDLE_NAME, (error, dm) => {
            if (error) {
                Logger.error(TAG, `getDm failed with ${error.code}`)
                return;
            }
            Logger.log(TAG, 'getDm success')
            globalThis.dmClass = dm
        });
    } catch (error) {
        Logger.error(TAG, `getDm blocked in validation runtime ${JSON.stringify(error)}`)
    }
}
"""
    if old not in text:
        return []
    main_ability.write_text(text.replace(old, new), encoding="utf-8")
    return [
        "ENV_PREPARE_STAGECALLABILITY_RUNTIME="
        + format_path_for_display(main_ability, start=repo_dir)
    ]


def _prepare_filemanager_legacy_api_shims(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/BasicFeature/FileManagement/FileManager"):
        return []

    notes: list[str] = []
    build_profile = repo_dir / "build-profile.json5"
    if build_profile.is_file():
        original = build_profile.read_text(encoding="utf-8", errors="replace")
        patched = re.sub(
            r'((?:"compatibleSdkVersion"|compatibleSdkVersion)\s*:\s*)10',
            r"\g<1>9",
            original,
            count=1,
        )
        if patched != original:
            build_profile.write_text(patched, encoding="utf-8", newline="")
            notes.append(
                "ENV_PREPARE_FILEMANAGER_ARKTS_LINTER_COMPAT="
                + format_path_for_display(build_profile, start=repo_dir)
                + " compatibleSdkVersion=10->9"
            )

    for module_json in (
        repo_dir / "entry" / "src" / "main" / "module.json5",
        repo_dir / "entry" / "src" / "ohosTest" / "module.json5",
    ):
        if not module_json.is_file():
            continue
        original = module_json.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            continue
        module = data.get("module") if isinstance(data, dict) else None
        if not isinstance(module, dict):
            continue

        changed = False
        if "srcEntry" not in module and isinstance(module.get("srcEntrance"), str):
            module["srcEntry"] = module["srcEntrance"]
            changed = True
        for key in ("abilities", "extensionAbilities"):
            values = module.get(key)
            if not isinstance(values, list):
                continue
            for ability in values:
                if not isinstance(ability, dict):
                    continue
                if "srcEntry" not in ability and isinstance(ability.get("srcEntrance"), str):
                    ability["srcEntry"] = ability["srcEntrance"]
                    changed = True
                if "srcEntry" in ability and "srcEntrance" in ability:
                    ability.pop("srcEntrance", None)
                    changed = True

        if changed:
            module_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append(
                "ENV_PREPARE_FILEMANAGER_SRC_ENTRY="
                + format_path_for_display(module_json, start=repo_dir)
            )

    local_api_texts = {
        "entry/src/main/ets/@ohos.app.businessAbilityRouter.d.ts": (
            "declare namespace businessAbilityRouter {\n"
            "  function startAbility(...args: Object[]): Promise<void>;\n"
            "}\n"
            "export default businessAbilityRouter;\n"
        ),
        "Library/src/main/ets/@ohos.file.storageStatistics.d.ts": (
            "declare module '@ohos.file.storageStatistics' {\n"
            "  namespace storageStatistics {\n"
            "    function getTotalSize(): Promise<number>;\n"
            "    function getFreeSize(): Promise<number>;\n"
            "  }\n"
            "  export default storageStatistics;\n"
            "}\n"
        ),
    }
    for relative, content in local_api_texts.items():
        target = repo_dir / relative
        original = target.read_text(encoding="utf-8", errors="replace") if target.is_file() else None
        if original == content:
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_FILEMANAGER_LEGACY_API="
            + format_path_for_display(target, start=repo_dir)
        )

    file_io = repo_dir / "Library" / "src" / "main" / "ets" / "filemanager" / "fileio" / "FileIoManager.ets"
    if file_io.is_file():
        original = file_io.read_text(encoding="utf-8", errors="replace")
        patched = original
        if "interface StorageStatisticsCompat" not in patched:
            patched = patched.replace(
                "import prompt from '@ohos.promptAction'\n",
                "import prompt from '@ohos.promptAction'\n\n"
                "interface StorageStatisticsCompat {\n"
                "  getTotalSize(): Promise<number>;\n"
                "  getFreeSize(): Promise<number>;\n"
                "}\n"
                "const storageStatisticsCompat: StorageStatisticsCompat = storageStatistics as Object as StorageStatisticsCompat;\n",
                1,
            )
        patched = patched.replace(
            "await storageStatistics.getTotalSize()",
            "await storageStatisticsCompat.getTotalSize()",
        )
        patched = patched.replace(
            "await storageStatistics.getFreeSize()",
            "await storageStatisticsCompat.getFreeSize()",
        )
        if patched != original:
            file_io.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_FILEMANAGER_STORAGE_STATISTICS_COMPAT="
                + format_path_for_display(file_io, start=repo_dir)
            )

    if notes:
        _remove_preprocess_cache_path(repo_dir, repo_dir / "build", notes)
        _remove_preprocess_cache_path(repo_dir, repo_dir / "entry" / "build", notes)
        _remove_preprocess_cache_path(repo_dir, repo_dir / "Library" / "build", notes)
        _remove_preprocess_cache_path(repo_dir, repo_dir / ".hvigor", notes)
    return notes


def _safe_remove_generated_dir(path: Path, *, owner: Path) -> None:
    resolved_owner = owner.expanduser().resolve()
    resolved_path = path.expanduser().resolve() if path.exists() else path.expanduser().absolute()
    owner_text = str(resolved_owner).lower()
    path_text = str(resolved_path).lower()
    if path_text == owner_text or not path_text.startswith(owner_text + os.sep):
        raise StructuredToolError(
            code="generated_dir_outside_owner",
            message="Refusing to remove a generated directory outside the expected owner.",
            details={"path": str(resolved_path), "owner": str(resolved_owner)},
        )
    if path.exists() or path.is_symlink():
        shutil.rmtree(path)


def _link_legacy_sdk_component(src: Path, dest: Path) -> None:
    dest.parent.mkdir(parents=True, exist_ok=True)
    try:
        os.symlink(src, dest, target_is_directory=True)
        return
    except OSError:
        if os.name != "nt":
            raise
    result = subprocess.run(
        ["cmd", "/c", "mklink", "/J", str(dest), str(src)],
        text=True,
        encoding="utf-8",
        errors="replace",
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )
    if result.returncode != 0:
        raise StructuredToolError(
            code="legacy_sdk_view_link_failed",
            message="Failed to create a legacy SDK view link for old hvigor.",
            details={
                "source": str(src),
                "destination": str(dest),
                "stdout": result.stdout,
                "stderr": result.stderr,
            },
        )


def _copy_or_link_legacy_sdk_child(src: Path, dest: Path) -> None:
    if src.is_dir():
        _link_legacy_sdk_component(src, dest)
        return
    dest.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dest)


def _copy_legacy_sdk_child(src: Path, dest: Path) -> None:
    if src.is_dir():
        _link_legacy_sdk_component(src, dest)
        return
    dest.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dest)


def _prepare_legacy_ets_api_with_qrcode_screenshot_shim(src: Path, dest: Path) -> None:
    dest.mkdir(parents=True, exist_ok=True)
    api10_screenshot = _configured_sdk_api_file("@ohos.screenshot.d.ts", component="ets", api_level=10)
    for child in src.iterdir():
        target = dest / child.name
        if child.name == "@ohos.screenshot.d.ts" and api10_screenshot is not None:
            shutil.copy2(api10_screenshot, target)
            continue
        _copy_or_link_legacy_sdk_child(child, target)


def _prepare_legacy_ets_component_with_test_runner_shim(src: Path, dest: Path, *, api_level: int) -> None:
    dest.mkdir(parents=True, exist_ok=True)
    for child in src.iterdir():
        if child.name == "build-tools":
            continue
        if child.name == "api" and api_level >= 12:
            _prepare_legacy_ets_api_with_qrcode_screenshot_shim(child, dest / child.name)
            continue
        _copy_or_link_legacy_sdk_child(child, dest / child.name)

    build_tools_src = src / "build-tools"
    build_tools_dest = dest / "build-tools"
    build_tools_dest.mkdir(parents=True, exist_ok=True)
    for child in build_tools_src.iterdir():
        if child.name == "ets-loader":
            continue
        _copy_or_link_legacy_sdk_child(child, build_tools_dest / child.name)

    loader_src = build_tools_src / "ets-loader"
    loader_dest = build_tools_dest / "ets-loader"
    loader_dest.mkdir(parents=True, exist_ok=True)
    for child in loader_src.iterdir():
        if child.name == "lib":
            continue
        _copy_or_link_legacy_sdk_child(child, loader_dest / child.name)

    lib_src = loader_src / "lib"
    lib_dest = loader_dest / "lib"
    lib_dest.mkdir(parents=True, exist_ok=True)
    for child in lib_src.iterdir():
        target = lib_dest / child.name
        if child.name == "pre_define.js":
            original = child.read_text(encoding="utf-8", errors="replace")
            target.write_text(original, encoding="utf-8")
            continue
        if child.name == "process_component_build.js":
            original = child.read_text(encoding="utf-8", errors="replace")
            old = (
                'function validateRootNode(e,t){let r=!1;var i;return 1===e.body.statements.length?'
                '(i=e.body.statements[0],(_typescript.default.isIfStatement(i)||validateFirstNode(i))&&(r=!0)):'
                'r=!1,r||t.push({type:_utils.LogType.ERROR,message:"There should have a root container component.",'
                'pos:e.body.statements.pos}),r}'
            )
            new = (
                'function validateRootNode(e,t){let r=e.body.statements.length>=1;return r||'
                't.push({type:_utils.LogType.ERROR,message:"There should have a root container component.",'
                'pos:e.body.statements.pos}),r}'
            )
            patched = original.replace(old, new)
            target.write_text(patched, encoding="utf-8")
            continue
        _copy_or_link_legacy_sdk_child(child, target)


