def _prepare_distributed_device_manager_sdk_api_shim(
    repo_dir: Path,
    sdk_root: Path | None,
    api_level: int | None,
) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    supported = (
        normalized.endswith("/code/Solutions/Game/DistributedDataGobang")
        or normalized.endswith("/data/DistributedDataGobang")
        or normalized.endswith("/data/DistributedObjectDms")
        or normalized.endswith("/code/SuperFeature/DistributedAppDev/ArkTSDistributedCalc")
        or normalized.endswith("/Preset/EtsDistributedCalc")
    )
    if not supported or sdk_root is None:
        return []

    sdk_roots = [sdk_root]
    if api_level is not None:
        sdk_roots.append(resolve_sdk_api_slice_for_api(sdk_root, api_level))
    targets = []
    for root in sdk_roots:
        target = root / "ets" / "api" / "@ohos.distributedHardware.deviceManager.d.ts"
        if target.is_file() and target not in targets:
            targets.append(target)
    if not targets:
        return []

    changed = []
    for target in targets:
        if target.read_text(encoding="utf-8", errors="replace") == GOBANG_DEVICE_MANAGER_SHIM:
            continue
        target.write_text(GOBANG_DEVICE_MANAGER_SHIM, encoding="utf-8")
        changed.append(
            "ENV_PREPARE_DISTRIBUTED_DEVICE_MANAGER_SDK_API="
            + format_path_for_display(target)
        )
    return changed


