def _prepare_weather_local_module_dependency_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/ETSUI/Weather"):
        return []

    product_root = repo_dir / "product"
    product_ets_root = product_root / "src" / "main" / "ets"
    common_root = repo_dir / "common"
    if not product_ets_root.is_dir() or not (common_root / "index.ets").is_file():
        return []

    notes: list[str] = []
    ets_roots = [product_ets_root]
    ohos_test_ets_root = product_root / "src" / "ohosTest" / "ets"
    if ohos_test_ets_root.is_dir():
        ets_roots.append(ohos_test_ets_root)
    for ets_root in ets_roots:
        note_key = "ENV_PREPARE_WEATHER_OHOSTEST_LOCAL_API" if ets_root == ohos_test_ets_root else "ENV_PREPARE_WEATHER_LOCAL_API"
        for filename, content in STAGE_CALL_ABILITY_API_SHIMS.items():
            target = ets_root / filename
            if not target.is_file() or target.read_text(encoding="utf-8", errors="replace") != content:
                target.write_text(content, encoding="utf-8")
            notes.append(
                note_key
                + "="
                + format_path_for_display(target, start=repo_dir)
            )

    main_resources = product_root / "src" / "main" / "resources"
    ohos_test_resources = product_root / "src" / "ohosTest" / "resources"
    if main_resources.is_dir() and ohos_test_resources.is_dir():
        copied_resources = 0
        for source in main_resources.rglob("*"):
            if not source.is_file():
                continue
            relative = source.relative_to(main_resources)
            if relative.parts[:2] == ("base", "profile"):
                continue
            target = ohos_test_resources / relative
            if target.is_file():
                continue
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, target)
            copied_resources += 1
        if copied_resources:
            notes.append(f"ENV_PREPARE_WEATHER_OHOSTEST_RESOURCES=copied_missing_main_resources count={copied_resources}")

    product_node_modules = product_root / "node_modules" / "@ohos"
    target_common = product_node_modules / "common"
    if not target_common.exists():
        product_node_modules.mkdir(parents=True, exist_ok=True)
        try:
            if os.name == "nt":
                subprocess.run(
                    ["cmd", "/c", "mklink", "/J", str(target_common), str(common_root)],
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True,
                    encoding="utf-8",
                    errors="replace",
                    check=False,
                )
            else:
                target_common.symlink_to(common_root, target_is_directory=True)
        except Exception:
            pass
    if not target_common.exists():
        shutil.copytree(common_root, target_common, dirs_exist_ok=True)
    notes.append(
        "ENV_PREPARE_WEATHER_LOCAL_MODULE="
        + format_path_for_display(target_common, start=repo_dir)
    )
    return notes


def _prepare_window_ext_ability_legacy_api_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/ability/WindowExtAbility"):
        return []

    ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    if not ets_root.is_dir():
        return []

    notes: list[str] = []
    ets_roots = [ets_root]
    ohos_test_ets_root = repo_dir / "entry" / "src" / "ohosTest" / "ets"
    if ohos_test_ets_root.is_dir():
        ets_roots.append(ohos_test_ets_root)

    for current_ets_root in ets_roots:
        note_key = (
            "ENV_PREPARE_WINDOW_EXT_ABILITY_OHOSTEST_LOCAL_API"
            if current_ets_root == ohos_test_ets_root
            else "ENV_PREPARE_WINDOW_EXT_ABILITY_LOCAL_API"
        )
        for filename, content in WINDOW_EXT_ABILITY_LEGACY_API_SHIMS.items():
            target = current_ets_root / filename
            if not target.is_file() or target.read_text(encoding="utf-8", errors="replace") != content:
                target.write_text(content, encoding="utf-8")
            notes.append(
                note_key
                + "="
                + format_path_for_display(target, start=repo_dir)
            )

    index_page = ets_root / "pages" / "Index.ets"
    if index_page.is_file():
        original = index_page.read_text(encoding="utf-8", errors="replace")
        marker = "type AbilityComponentAttribute = Object;\n"
        if "Cannot find name 'AbilityComponentAttribute'" not in original and marker not in original:
            imports_end = 0
            lines = original.splitlines(keepends=True)
            for idx, line in enumerate(lines):
                if line.lstrip().startswith("import "):
                    imports_end = idx + 1
            lines.insert(imports_end, marker)
            index_page.write_text("".join(lines), encoding="utf-8")
            notes.append(
                "ENV_PREPARE_WINDOW_EXT_ABILITY_GLOBAL_TYPE="
                + format_path_for_display(index_page, start=repo_dir)
            )
    return notes


