def _find_installed_sdk_api_file(file_name: str, *, component: str) -> Path | None:
    sdk_root = _configured_openharmony_sdk_root()
    if sdk_root is None:
        return None
    api_dirs = sorted(
        (child for child in sdk_root.iterdir() if child.is_dir() and child.name.isdigit()),
        key=lambda child: int(child.name),
        reverse=True,
    )
    for api_dir in api_dirs:
        candidate = api_dir / component / "api" / file_name
        if candidate.is_file():
            return candidate
    return None


def _find_installed_sdk_kit_file(file_name: str, *, component: str) -> Path | None:
    sdk_root = _configured_openharmony_sdk_root()
    if sdk_root is None:
        return None
    api_dirs = sorted(
        (child for child in sdk_root.iterdir() if child.is_dir() and child.name.isdigit()),
        key=lambda child: int(child.name),
        reverse=True,
    )
    for api_dir in api_dirs:
        candidate = api_dir / component / "kits" / file_name
        if candidate.is_file():
            return candidate
    return None


def _copy_installed_sdk_api_file(file_name: str, target: Path, *, component: str) -> bool:
    source = _find_installed_sdk_api_file(file_name, component=component)
    if source is None:
        return False
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, target)
    return True


def _append_to_declare_namespace(path: Path, namespace: str, addition: str) -> None:
    if not path.is_file():
        return
    original = path.read_text(encoding="utf-8", errors="replace")
    if addition.strip() in original:
        return
    start_pattern = re.compile(rf"^\s*declare\s+namespace\s+{re.escape(namespace)}\s*\{{", re.MULTILINE)
    match = start_pattern.search(original)
    if match is None:
        return

    depth = 0
    close_index: int | None = None
    for index in range(match.start(), len(original)):
        char = original[index]
        if char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                close_index = index
                break
    if close_index is None:
        return

    patched = original[:close_index] + addition + original[close_index:]
    path.write_text(patched, encoding="utf-8")


