def _patch_legacy_ets_loader_clean_config(loader_dest: Path) -> None:
    compile_plugin = loader_dest / "compile_plugin.js"
    if not compile_plugin.is_file():
        return
    original = compile_plugin.read_text(encoding="utf-8", errors="replace")
    old = "exports.getCleanConfig = getCleanConfig;"
    if old not in original or "ENV_PREPARE_LEGACY_CLEAN_CONFIG_FILTER" in original:
        return
    new = """exports.getCleanConfig = function(workerFile) {
    const cleanConfig = getCleanConfig(workerFile);
    if (!Array.isArray(cleanConfig)) {
        return [];
    }
    return cleanConfig.filter((item) => typeof item === 'string' && item.length > 0);
};
// ENV_PREPARE_LEGACY_CLEAN_CONFIG_FILTER
"""
    compile_plugin.write_text(original.replace(old, new, 1), encoding="utf-8")


def _patch_legacy_ets_loader_keep_sdk_configs(loader_dest: Path) -> None:
    main_js = loader_dest / "main.js"
    if not main_js.is_file():
        return
    original = main_js.read_text(encoding="utf-8", errors="replace")
    if "ENV_PREPARE_LEGACY_KEEP_SDK_CONFIGS" in original:
        return
    old = """  globalModulePaths = [];
  sdkConfigs = [];
  defaultSdkConfigs = [];
  extendSdkConfigs = [];
  sdkConfigPrefix = 'ohos|system|kit';
  ohosSystemModulePaths = [];
  ohosSystemModuleSubDirPaths = [];
  allModulesPaths = [];
"""
    new = """  // ENV_PREPARE_LEGACY_KEEP_SDK_CONFIGS
  // Old hvigor workers call resetMain() without rebuilding the SDK module config.
  // Keep the system API paths that were read when main.js was loaded.
"""
    if old not in original:
        return
    main_js.write_text(original.replace(old, new, 1), encoding="utf-8")


def _patch_legacy_webpack_sourcemap_missing_asset_guard(loader_dest: Path) -> None:
    plugin = loader_dest / "node_modules" / "webpack" / "lib" / "SourceMapDevToolPlugin.js"
    if not plugin.is_file():
        return
    original = plugin.read_text(encoding="utf-8", errors="replace")
    if "ENV_PREPARE_LEGACY_SOURCEMAP_MISSING_ASSET_GUARD" in original:
        return
    old = """\t\t\t\t\t\t\tconst asset = compilation.getAsset(file);
\t\t\t\t\t\t\tif (asset.info.related && asset.info.related.sourceMap) {
\t\t\t\t\t\t\t\tfileIndex++;
\t\t\t\t\t\t\t\treturn callback();
\t\t\t\t\t\t\t}
"""
    new = """\t\t\t\t\t\t\tconst asset = compilation.getAsset(file);
\t\t\t\t\t\t\t// ENV_PREPARE_LEGACY_SOURCEMAP_MISSING_ASSET_GUARD
\t\t\t\t\t\t\tif (!asset) {
\t\t\t\t\t\t\t\tfileIndex++;
\t\t\t\t\t\t\t\treturn callback();
\t\t\t\t\t\t\t}
\t\t\t\t\t\t\tif (asset.info.related && asset.info.related.sourceMap) {
\t\t\t\t\t\t\t\tfileIndex++;
\t\t\t\t\t\t\t\treturn callback();
\t\t\t\t\t\t\t}
"""
    if old not in original:
        return
    plugin.write_text(original.replace(old, new, 1), encoding="utf-8")


def _patch_form_ext_form_info_types(path: Path) -> None:
    if not path.is_file():
        return
    original = path.read_text(encoding="utf-8", errors="replace")
    needs_provider_filter = "interface FormProviderFilter" not in original
    needs_running_info = "interface RunningFormInfo" not in original
    if not needs_provider_filter and not needs_running_info:
        return
    marker = "\n}\nexport default formInfo;"
    if marker not in original:
        return
    additions: list[str] = []
    if needs_provider_filter:
        additions.append(
            """
    interface FormProviderFilter {
        bundleName?: string;
        moduleName?: string;
        abilityName?: string;
        formName?: string;
    }
"""
        )
    if needs_running_info:
        additions.append(
            """
    interface RunningFormInfo {
        readonly formId: string;
        readonly bundleName: string;
        readonly moduleName?: string;
        readonly abilityName?: string;
        readonly formName?: string;
    }
"""
        )
    patched = original.replace(marker, "".join(additions) + marker, 1)
    path.write_text(patched, encoding="utf-8")


def _prepare_legacy_api_with_form_ext_shims(src: Path, dest: Path) -> None:
    dest.mkdir(parents=True, exist_ok=True)
    for child in src.iterdir():
        target = dest / child.name
        if child.name == "@ohos.app.form.formInfo.d.ts":
            if not _copy_installed_sdk_api_file(child.name, target, component=src.parent.name):
                shutil.copy2(child, target)
            _patch_form_ext_form_info_types(target)
            continue
        if child.name in ("@ohos.app.form.formObserver.d.ts", "@ohos.data.dataShare.d.ts"):
            continue
        _copy_or_link_legacy_sdk_child(child, target)

    _patch_form_ext_form_info_types(dest / "@ohos.app.form.formInfo.d.ts")
    if not _copy_installed_sdk_api_file("@ohos.app.form.formObserver.d.ts", dest / "@ohos.app.form.formObserver.d.ts", component=src.parent.name):
        (dest / "@ohos.app.form.formObserver.d.ts").write_text(
            FORM_EXT_FORM_OBSERVER_SHIM,
            encoding="utf-8",
        )
    if not _copy_installed_sdk_api_file("@ohos.data.dataShare.d.ts", dest / "@ohos.data.dataShare.d.ts", component=src.parent.name):
        (dest / "@ohos.data.dataShare.d.ts").write_text(
            FORM_EXT_DATASHARE_SHIM,
            encoding="utf-8",
        )
    _patch_form_ext_datashare_legacy_types(dest / "@ohos.data.dataShare.d.ts")


