def _patch_sdk_component_package_api(component_root: Path, *, api_level: int) -> None:
    package_json = component_root / "oh-uni-package.json"
    if not package_json.is_file():
        return
    try:
        data = json.loads(package_json.read_text(encoding="utf-8", errors="replace"))
    except Exception:
        return
    data["apiVersion"] = str(api_level)
    package_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


