    command = [
        str(npm),
        "install",
        "--offline",
        "--cache",
        str(npm_cache),
    ]
    env = os.environ.copy()
    offline_env = workspace_root() / "offline_env"
    env["HOME"] = str(offline_env)
    env["USERPROFILE"] = str(offline_env)
    node_dir = deveco_dir / "tools" / "node"
    if node_dir.is_dir():
        env["PATH"] = str(node_dir) + os.pathsep + env.get("PATH", "")

    npm_lock = npm_cache / "arkeval-legacy-hvigor-npm-install.lock"
    with FileLock(str(npm_lock), timeout=max(600.0, float(timeout_sec))):
        result = subprocess.run(
            command,
            cwd=str(repo_dir),
            text=True,
            encoding="utf-8",
            errors="replace",
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            env=env,
            timeout=max(60, min(float(timeout_sec), 600.0)),
        )
