def _remove_preprocess_cache_path(repo_dir: Path, path: Path, notes: list[str]) -> None:
    if not path.exists():
        return
    resolved = path.resolve()
    try:
        resolved.relative_to(repo_dir.resolve())
    except ValueError:
        return
    if resolved.is_dir():
        shutil.rmtree(resolved)
    else:
        resolved.unlink()
    notes.append(
        "ENV_PREPARE_CACHE_CLEANED="
        + format_path_for_display(resolved, start=repo_dir)
    )


def _uses_legacy_fa_test_runner_case(module_root: Path) -> bool:
    hvigorfile = module_root / "hvigorfile.js"
    if hvigorfile.is_file() and "legacyHapTasks" in hvigorfile.read_text(encoding="utf-8", errors="replace"):
        return True
    return (
        (module_root / "src" / "main" / "config.json").is_file()
        and not (module_root / "src" / "main" / "module.json5").is_file()
    )


def _prepare_ohos_test_runner_case_paths(repo_dir: Path) -> list[str]:
    notes: list[str] = []
    for runner_file in sorted(repo_dir.rglob("src/ohosTest/ets/*/OpenHarmonyTestRunner.ts")):
        runner_dir = runner_file.parent
        if runner_dir.name.lower() != "testrunner":
            continue

        module_root = runner_file.parents[4]
        desired_name = "TestRunner" if _uses_legacy_fa_test_runner_case(module_root) else "testrunner"
        if runner_dir.name == desired_name:
            continue

        target_dir = runner_dir.with_name(desired_name)
        if target_dir.exists():
            try:
                same_path = target_dir.resolve() == runner_dir.resolve()
            except OSError:
                same_path = False
            if not same_path:
                notes.append(
                    "ENV_PREPARE_OHOSTEST_RUNNER_CASE=skipped_existing_target "
                    + format_path_for_display(target_dir, start=repo_dir)
                )
                continue

        temp_dir = runner_dir.with_name("__arkagent_testrunner_case_tmp__")
        if temp_dir.exists():
            raise StructuredToolError(
                code="ohostest_runner_case_tmp_exists",
                message="Cannot normalize ohosTest runner path because a temporary directory already exists.",
                details={"temp_dir": str(temp_dir)},
            )

        source_display = runner_dir.relative_to(repo_dir).as_posix()
        target_display = target_dir.relative_to(repo_dir).as_posix()
        runner_dir.rename(temp_dir)
        temp_dir.rename(target_dir)
        notes.append(
            f"ENV_PREPARE_OHOSTEST_RUNNER_CASE=renamed {source_display}->{target_display}"
        )
        _remove_preprocess_cache_path(repo_dir, module_root / "build", notes)
        _remove_preprocess_cache_path(repo_dir, repo_dir / ".hvigor", notes)
    return notes


def _gpu_transform_dependency_roots(repo_dir: Path) -> list[Path]:
    candidates: list[Path] = [
        repo_dir / "oh_modules" / "@ohos" / "gpu_transform",
    ]
    ohpm_root = repo_dir / "oh_modules" / ".ohpm"
    if ohpm_root.is_dir():
        for package_dir in ohpm_root.glob("@ohos+gpu_transform@*"):
            candidates.append(package_dir / "oh_modules" / "@ohos" / "gpu_transform")

    roots: list[Path] = []
    seen: set[Path] = set()
    for candidate in candidates:
        if not candidate.is_dir():
            continue
        try:
            key = candidate.resolve()
        except OSError:
            key = candidate
        if key in seen:
            continue
        seen.add(key)
        roots.append(candidate)
    return roots


def _gpu_transform_has_x86_64_libs(root: Path) -> bool:
    lib_dir = root / "libs" / "x86_64"
    return (lib_dir / "libnativeGpu.so").is_file() and (lib_dir / "libc++_shared.so").is_file()


def _prepare_imageknife_gpu_transform_x86_64(
    repo_dir: Path,
    deveco_dir: Path,
    *,
    product_name: str,
    sdk_root: Path | None,
    sdk_api_level: int | None,
    timeout_sec: float | None,
) -> list[str]:
    gpu_dir = repo_dir / "gpu_transform"
    profile = gpu_dir / "build-profile.json5"
    cmake = gpu_dir / "src" / "main" / "cpp" / "CMakeLists.txt"
    if not profile.is_file() or not cmake.is_file():
        return []

    dep_roots = _gpu_transform_dependency_roots(repo_dir)
    if dep_roots and all(_gpu_transform_has_x86_64_libs(root) for root in dep_roots):
        return ["ENV_PREPARE_IMAGEKNIFE_GPU_TRANSFORM=already_has_x86_64_dependency"]
    needs_copy = [
        root for root in dep_roots
        if not _gpu_transform_has_x86_64_libs(root)
    ]
    built_native = gpu_dir / "build" / "default" / "intermediates" / "libs" / "default" / "x86_64" / "libnativeGpu.so"
    built_cpp = built_native.with_name("libc++_shared.so")
    if not needs_copy and built_native.is_file() and built_cpp.is_file():
        return ["ENV_PREPARE_IMAGEKNIFE_GPU_TRANSFORM=already_has_x86_64"]

    original = profile.read_text(encoding="utf-8", errors="replace")
    patched = _abi_filter_text_with_x86_64(original, only_x86_64=True)
    changed = patched != original
    if changed:
        profile.write_text(patched, encoding="utf-8")
    notes = ["ENV_PREPARE_IMAGEKNIFE_GPU_TRANSFORM=build_x86_64"]
    root_profile = repo_dir / "build-profile.json5"
    root_profile_original = _imageknife_root_profile_with_gpu_transform(root_profile)
    if root_profile_original is not None:
        notes.append("ENV_PREPARE_IMAGEKNIFE_GPU_TRANSFORM_MODULE=temporary_root_profile")

    try:
        try:
            _run_hvigor_preprocess_task(
                repo_dir,
                deveco_dir,
                module="gpu_transform",
                product=product_name,
                task="assembleHar",
                sdk_root=sdk_root,
                sdk_api_level=sdk_api_level,
                timeout_sec=timeout_sec,
            )
        except StructuredToolError as exc:
            output_tail = str(exc.details.get("output_tail") or "")
            harmony_sdk = _harmonyos_openharmony_sdk_root_from_deveco(deveco_dir)
            if "SDK component missing" not in output_tail or harmony_sdk is None:
                raise
            notes.append(
                "ENV_PREPARE_IMAGEKNIFE_GPU_TRANSFORM_SDK_FALLBACK="
                + format_path_for_display(harmony_sdk)
            )
            _run_hvigor_preprocess_task(
                repo_dir,
                deveco_dir,
                module="gpu_transform",
                product=product_name,
                task="assembleHar",
                sdk_root=harmony_sdk,
                sdk_api_level=None,
                timeout_sec=timeout_sec,
            )
    finally:
        if changed:
            profile.write_text(original, encoding="utf-8")
        if root_profile_original is not None:
            root_profile.write_text(root_profile_original, encoding="utf-8")

    if not built_native.is_file() or not built_cpp.is_file():
        raise StructuredToolError(
            code="native_preprocess_missing_output",
            message="gpu_transform x86_64 build succeeded but expected .so files were not produced.",
            details={"expected_dir": str(built_native.parent)},
        )

    if not dep_roots:
        notes.append("ENV_PREPARE_IMAGEKNIFE_GPU_TRANSFORM=no_ohpm_dependency_root_found")
        return notes

    for root in dep_roots:
        dst = root / "libs" / "x86_64"
        dst.mkdir(parents=True, exist_ok=True)
        shutil.copy2(built_native, dst / built_native.name)
        shutil.copy2(built_cpp, dst / built_cpp.name)
        notes.append(
            "ENV_PREPARE_IMAGEKNIFE_GPU_TRANSFORM_COPIED="
            + format_path_for_display(dst, start=repo_dir)
        )
    return notes


def _prepare_sdk_version_string_literals(repo_dir: Path) -> list[str]:
    if _is_parallel_sample_project(repo_dir):
        return []

    profile = repo_dir / "build-profile.json5"
    if not profile.is_file():
        return []

    original = profile.read_text(encoding="utf-8", errors="replace")
    profile_data = parse_json5_text(original)
    app = profile_data.get("app") if isinstance(profile_data, dict) else None
    products = app.get("products") if isinstance(app, dict) else None
    should_use_openharmony = (
        isinstance(products, list)
        and any(
            isinstance(product, dict)
            and str(product.get("runtimeOS") or "").strip() == "HarmonyOS"
            and any(
                isinstance(product.get(key), str)
                and re.search(r"\(\d+\)", str(product.get(key)))
                for key in ("compileSdkVersion", "compatibleSdkVersion", "targetSdkVersion")
            )
            for product in products
        )
    )

    def replace_version(match: re.Match[str]) -> str:
        if should_use_openharmony:
            return f"{match.group(1)}{match.group(2)}"
        return f'{match.group(1)}"{match.group(2)}"'

    patched = re.sub(
        r'((?:"(?:compileSdkVersion|compatibleSdkVersion)"|(?:compileSdkVersion|compatibleSdkVersion))\s*:\s*)'
        r'["\'][^"\']*\((\d+)\)["\']',
        replace_version,
        original,
    )
    if should_use_openharmony:
        patched = re.sub(
            r'("runtimeOS"\s*:\s*)"HarmonyOS"',
            r'\1"OpenHarmony"',
            patched,
        )
        try:
            data = parse_json5_text(patched)
            patched_app = data.get("app") if isinstance(data, dict) else None
            patched_products = patched_app.get("products") if isinstance(patched_app, dict) else None
            if isinstance(patched_products, list):
                for product in patched_products:
                    if not isinstance(product, dict):
                        continue
                    compatible = _coerce_sdk_version(product.get("compatibleSdkVersion"))
                    compile_v = _coerce_sdk_version(product.get("compileSdkVersion"))
                    if compile_v is None and compatible is not None:
                        patched = re.sub(
                            r'("compatibleSdkVersion"\s*:\s*)' + str(compatible),
                            f'"compileSdkVersion": {compatible},\n        '
                            + rf'\g<1>{compatible}',
                            patched,
                            count=1,
                        )
                        break
        except Exception:
            pass
    elif isinstance(products, list) and any(
        isinstance(product, dict)
        and str(product.get("runtimeOS") or "").strip() == "OpenHarmony"
        and str(product.get("compatibleSdkVersion") or "").strip().isdigit()
        and not (
            isinstance(product.get("compileSdkVersion"), str)
            and str(product.get("compileSdkVersion") or "").strip().isdigit()
        )
        for product in products
    ):
        patched = re.sub(
            r'((?:"(?:compileSdkVersion|compatibleSdkVersion|targetSdkVersion)"|'
            r'(?:compileSdkVersion|compatibleSdkVersion|targetSdkVersion))\s*:\s*)'
            r'["\'](\d+)["\']',
            lambda match: f"{match.group(1)}{match.group(2)}",
            patched,
        )
        try:
            data = parse_json5_text(patched)
            patched_app = data.get("app") if isinstance(data, dict) else None
            patched_products = patched_app.get("products") if isinstance(patched_app, dict) else None
            if isinstance(patched_products, list):
                for product in patched_products:
                    if not isinstance(product, dict):
                        continue
                    compatible = _coerce_sdk_version(product.get("compatibleSdkVersion"))
                    compile_v = _coerce_sdk_version(product.get("compileSdkVersion"))
                    if compile_v is None and compatible is not None:
                        patched = re.sub(
                            r'("compatibleSdkVersion"\s*:\s*)' + str(compatible),
                            f'"compileSdkVersion": {compatible},\n        '
                            + rf'\g<1>{compatible}',
                            patched,
                            count=1,
                        )
                        break
        except Exception:
            pass
    elif '"modelVersion": "5.0.0"' in patched or "'modelVersion': '5.0.0'" in patched:
        patched = re.sub(
            r'((?:"(?:compileSdkVersion|compatibleSdkVersion)"|(?:compileSdkVersion|compatibleSdkVersion))\s*:\s*)'
            r'(\d+)(\s*[,}\]])',
            lambda match: f'{match.group(1)}"{match.group(2)}"{match.group(3)}',
            patched,
        )
    if patched == original:
        return []

    profile.write_text(patched, encoding="utf-8")
    return [
        "ENV_PREPARE_SDK_VERSION_STRING="
        + format_path_for_display(profile, start=repo_dir)
    ]


def _sdk_component_api_version(sdk_root: Path | None) -> int | None:
    if sdk_root is None:
        return None
    if not _is_complete_sdk_component_root(sdk_root):
        return None
    for package_json in (
        sdk_root / "ets" / "oh-uni-package.json",
        sdk_root / "js" / "oh-uni-package.json",
        sdk_root / "toolchains" / "oh-uni-package.json",
    ):
        if not package_json.is_file():
            continue
        try:
            data = json.loads(package_json.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            continue
        api = _coerce_sdk_version(data.get("apiVersion"))
        if api is not None:
            return api
    return None


def _prepare_build_profile_sdk_api_compat(
    repo_dir: Path,
    sdk_root: Path | None,
    sdk_meta: dict[str, Any],
) -> list[str]:
    profile = repo_dir / "build-profile.json5"
    if sdk_root is None or not profile.is_file():
        return []
    package_json = repo_dir / "package.json"
    if package_json.is_file() and not (repo_dir / "oh-package.json5").is_file():
        try:
            package_data = json.loads(package_json.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            package_data = None
        dependencies = package_data.get("dependencies") if isinstance(package_data, dict) else None
        if isinstance(dependencies, dict) and "@ohos/hvigor" in dependencies:
            return []

    profile_compile, profile_compatible, _product, _runtime_os = _read_build_profile_product_info(
        repo_dir
    )
    selected_api = _coerce_sdk_version(sdk_meta.get("sdk_selection_api_level"))
    compile_api = profile_compile or _coerce_sdk_version(sdk_meta.get("compileSdkVersion"))
    compatible_api = profile_compatible or _coerce_sdk_version(sdk_meta.get("compatibleSdkVersion"))
    declared = selected_api or compile_api or compatible_api
    allow_photo_deal_api16 = repo_dir.name.casefold() == "photo-deal-demo" and declared == 16
    if declared is None or (declared > 12 and not allow_photo_deal_api16):
        return []

    api_slice = resolve_sdk_api_slice_for_api(sdk_root, declared)
    actual_api = _sdk_component_api_version(api_slice)
    if actual_api is None:
        actual_api = _first_installed_openharmony_api_at_least(sdk_root, declared)
    if actual_api is None or actual_api == declared:
        return []
    if actual_api < declared:
        return []

    original = profile.read_text(encoding="utf-8", errors="replace")
    patched = original
    for key, old_value in (
        ("compileSdkVersion", compile_api),
        ("compatibleSdkVersion", compatible_api),
    ):
        if old_value is None or old_value == actual_api:
            continue
        patched = re.sub(
            rf'((?:"{key}"|{key})\s*:\s*){old_value}(\s*[,}}\]])',
            rf"\g<1>{actual_api}\2",
            patched,
        )
    if patched == original:
        return []

    profile.write_text(patched, encoding="utf-8")
    sdk_meta["compileSdkVersion"] = actual_api if compile_api is not None else compile_api
    sdk_meta["compatibleSdkVersion"] = actual_api if compatible_api is not None else compatible_api
    sdk_meta["sdk_selection_api_level"] = actual_api
    return [
        "ENV_PREPARE_BUILD_PROFILE_SDK_API="
        f"{declared}->api{actual_api}:"
        + format_path_for_display(profile, start=repo_dir)
    ]


def _prepare_legacy_hvigor_model_version(repo_dir: Path) -> list[str]:
    if _is_parallel_sample_project(repo_dir):
        return []

    notes: list[str] = []
    for config in (
        repo_dir / "hvigor" / "hvigor-config.json5",
        repo_dir / "oh-package.json5",
    ):
        if not config.is_file():
            continue

        original = config.read_text(encoding="utf-8", errors="replace")
        model_match = re.search(
            r'(?:"modelVersion"|modelVersion)\s*:\s*["\'](5\.0\.[124]|6\.0\.0)["\']',
            original,
        )
        patched = re.sub(
            r'((?:"modelVersion"|modelVersion)\s*:\s*["\'])(?:5\.0\.[124]|6\.0\.0)(["\'])',
            r"\g<1>5.0.0\2",
            original,
        )
        if patched == original:
            continue

        config.write_text(patched, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_LEGACY_HVIGOR_MODEL_VERSION="
            + format_path_for_display(config, start=repo_dir)
            + f" {model_match.group(1) if model_match else '5.0.x'}->5.0.0"
        )
    return notes


def _prepare_legacy_har_build_profile(repo_dir: Path) -> list[str]:
    hvigorfile = repo_dir / "hvigorfile.js"
    if not hvigorfile.is_file() or (repo_dir / "oh-package.json5").is_file():
        return []
    try:
        hvigorfile_text = hvigorfile.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return []
    if "harTasks" not in hvigorfile_text:
        return []

    notes: list[str] = []
    build_profile = repo_dir / "build-profile.json5"
    if build_profile.is_file():
        original = build_profile.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            data = None
        if isinstance(data, dict) and not isinstance(data.get("modules"), list):
            data["modules"] = [{"name": repo_dir.name, "srcPath": "."}]
            build_profile.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append(
                "ENV_PREPARE_LEGACY_HAR_BUILD_PROFILE="
                + format_path_for_display(build_profile, start=repo_dir)
            )

    hvigor_config = repo_dir / "hvigor" / "hvigor-config.json5"
    if hvigor_config.is_file():
        return notes
    hvigor_config.parent.mkdir(parents=True, exist_ok=True)
    hvigor_config.write_text(
        json.dumps({"modelVersion": "5.0.0", "dependencies": {}}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    notes.append(
        "ENV_PREPARE_LEGACY_HAR_HVIGOR_CONFIG="
        + format_path_for_display(hvigor_config, start=repo_dir)
    )
    return notes


def _prepare_legacy_hvigor_windows_wrapper_exit(repo_dir: Path) -> list[str]:
    wrapper = repo_dir / "hvigorw.bat"
    if not wrapper.is_file():
        return []

    original = wrapper.read_text(encoding="utf-8", errors="replace")
    if "ENV_PREPARE_LEGACY_HVIGOR_WRAPPER_EXIT" in original:
        return []
    needle = '"%NODE_EXE%" %WRAPPER_MODULE_PATH% %*'
    if needle not in original:
        return []
    if re.search(r'"%NODE_EXE%"\s+%WRAPPER_MODULE_PATH%\s+%\*\s*\r?\n\s*if\s+"?%ERRORLEVEL%"?', original, re.I):
        return []

    patched = original.replace(
        needle,
        needle
        + "\n"
        + "set HVIGOR_EXIT_CODE=%ERRORLEVEL%\n"
        + "if \"%HVIGOR_EXIT_CODE%\" == \"0\" exit /b 0\n"
        + "rem ENV_PREPARE_LEGACY_HVIGOR_WRAPPER_EXIT\n",
        1,
    )
    if patched == original:
        return []

    wrapper.write_text(patched, encoding="utf-8")
    return [
        "ENV_PREPARE_LEGACY_HVIGOR_WRAPPER_EXIT="
        + format_path_for_display(wrapper, start=repo_dir)
    ]


def _prepare_legacy_hvigor_windows_batch_wrapper(repo_dir: Path) -> list[str]:
    if os.name != "nt":
        return []

    batch_wrapper = repo_dir / "hvigorw.bat"
    shell_wrapper = repo_dir / "hvigorw"
    wrapper_module = repo_dir / "hvigor" / "hvigor-wrapper.js"
    if batch_wrapper.is_file() or not shell_wrapper.is_file() or not wrapper_module.is_file():
        return []

    try:
        first_line = shell_wrapper.read_text(encoding="utf-8", errors="replace").splitlines()[0]
    except (OSError, IndexError):
        first_line = ""
    if "bash" not in first_line.lower():
        return []

    batch_wrapper.write_text(
        "@echo off\r\n"
        "setlocal\r\n"
        "set DIRNAME=%~dp0\r\n"
        "set WRAPPER_MODULE_PATH=%DIRNAME%hvigor\\hvigor-wrapper.js\r\n"
        "if not defined NODE_EXE set NODE_EXE=node\r\n"
        "\"%NODE_EXE%\" \"%WRAPPER_MODULE_PATH%\" %*\r\n"
        "exit /b %ERRORLEVEL%\r\n",
        encoding="utf-8",
        newline="",
    )
    return [
        "ENV_PREPARE_LEGACY_HVIGOR_WINDOWS_BATCH_WRAPPER="
        + format_path_for_display(batch_wrapper, start=repo_dir)
    ]


def _prepare_hvigor_project_cache_plugin_dependencies(repo_dir: Path, deveco_dir: Path) -> list[str]:
    hvigor_config = repo_dir / "hvigor" / "hvigor-config.json5"
    if not hvigor_config.is_file():
        return []
    try:
        config = parse_json5_text(hvigor_config.read_text(encoding="utf-8", errors="replace"))
    except Exception:
        return []
    if not isinstance(config, dict):
        return []
    dependencies = config.get("dependencies")
    if not isinstance(dependencies, dict) or not dependencies:
        return []

    normalized_dependencies = dict(dependencies)
    normalized_notes: list[str] = []
    hvigor_version = config.get("hvigorVersion")
    if isinstance(hvigor_version, str) and hvigor_version.endswith("-s"):
        normalized = hvigor_version[:-2]
        config["hvigorVersion"] = normalized
        normalized_notes.append(f"hvigorVersion:{hvigor_version}->{normalized}")
        hvigor_config.write_text(json.dumps(config, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    for name, version in list(normalized_dependencies.items()):
        if not isinstance(name, str) or not isinstance(version, str):
            continue
        if name.startswith("@ohos/") and version.endswith("-s"):
            normalized = version[:-2]
            normalized_dependencies[name] = normalized
            normalized_notes.append(f"{name}:{version}->{normalized}")
    if normalized_dependencies != dependencies:
        config["dependencies"] = normalized_dependencies
        hvigor_config.write_text(json.dumps(config, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    workspace_dependencies = dict(normalized_dependencies)
    normalized_hvigor_version = config.get("hvigorVersion")
    if isinstance(normalized_hvigor_version, str) and normalized_hvigor_version:
        workspace_dependencies["@ohos/hvigor"] = normalized_hvigor_version

    project_name = hashlib.md5(str(repo_dir.resolve()).encode("utf-8")).hexdigest()
    hvigor_home = Path(os.environ.get("HVIGOR_USER_HOME") or (workspace_root() / ".hvigor")).resolve()
    workspace = hvigor_home / "project_caches" / project_name / "workspace"
    package_json = workspace / "package.json"
    node_modules = workspace / "node_modules"
    missing: list[str] = []
    for name in workspace_dependencies:
        if not isinstance(name, str):
            continue
        dependency_path = (
            node_modules.joinpath(*name.split("/", 1))
            if name.startswith("@") and "/" in name
            else node_modules / name
        )
        expected_version = workspace_dependencies.get(name)
        installed_version = None
        installed_package = dependency_path / "package.json"
        if installed_package.is_file():
            try:
                installed_data = json.loads(installed_package.read_text(encoding="utf-8", errors="replace"))
                installed_version = installed_data.get("version") if isinstance(installed_data, dict) else None
            except Exception:
                installed_version = None
        if not dependency_path.exists() or (
            isinstance(expected_version, str)
            and re.fullmatch(r"\d+\.\d+\.\d+", expected_version)
            and installed_version != expected_version
        ):
            missing.append(name)
    if not missing:
        notes = ["ENV_PREPARE_HVIGOR_PROJECT_CACHE_PLUGIN_DEPS=present"]
        if normalized_notes:
            notes.append("ENV_PREPARE_HVIGOR_PROJECT_CACHE_PLUGIN_VERSION_NORMALIZED=" + ",".join(normalized_notes))
        return notes

    data: dict[str, Any] = {}
    if package_json.is_file():
        try:
            parsed = json.loads(package_json.read_text(encoding="utf-8", errors="replace"))
            if isinstance(parsed, dict):
                data = parsed
        except Exception:
            data = {}
    package_dependencies = data.get("dependencies")
    if not isinstance(package_dependencies, dict):
        package_dependencies = {}
    changed = False
    package_hvigor_version = package_dependencies.get("@ohos/hvigor")
    if isinstance(package_hvigor_version, str) and package_hvigor_version.endswith("-s"):
        normalized = package_hvigor_version[:-2]
        package_dependencies["@ohos/hvigor"] = normalized
        normalized_notes.append(f"@ohos/hvigor:{package_hvigor_version}->{normalized}")
        changed = True
    for name, version in workspace_dependencies.items():
        if (
            isinstance(name, str)
            and name in missing
            and isinstance(version, str)
            and package_dependencies.get(name) != version
        ):
            package_dependencies[name] = version
            changed = True
    if changed or not package_json.is_file():
        data["dependencies"] = package_dependencies
        workspace.mkdir(parents=True, exist_ok=True)
        package_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    node_dir = deveco_dir / "tools" / "node"
    pnpm_candidates = [
        hvigor_home / "wrapper" / "tools" / "node_modules" / ".bin" / ("pnpm.cmd" if os.name == "nt" else "pnpm"),
        node_dir / ("pnpm.cmd" if os.name == "nt" else "pnpm"),
        node_dir / "node_modules" / "corepack" / "shims" / ("pnpm.cmd" if os.name == "nt" else "pnpm"),
    ]
    pnpm = next((candidate for candidate in pnpm_candidates if candidate.is_file()), None)
    if pnpm is None:
        raise StructuredToolError(
            code="bundled_pnpm_not_found",
            message="Bundled pnpm was not found under the local arkeval runtime.",
            details={"candidates": [str(candidate) for candidate in pnpm_candidates]},
        )
    command = [
        str(pnpm),
        "install",
        "--offline",
        "--store-dir",
        str(hvigor_home / "caches"),
    ]
    env = os.environ.copy()
    offline_env = workspace_root() / "offline_env"
    env["HOME"] = str(offline_env)
    env["USERPROFILE"] = str(offline_env)
    if node_dir.is_dir():
        env["PATH"] = str(node_dir) + os.pathsep + env.get("PATH", "")

    install_lock = hvigor_home / "arkeval-hvigor-project-cache-plugin-install.lock"
    cache_filled_online = False
    with FileLock(str(install_lock), timeout=900):
        result = subprocess.run(
            command,
            cwd=str(workspace),
            text=True,
            encoding="utf-8",
            errors="replace",
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            env=env,
            timeout=600,
        )
        if result.returncode != 0 and "ERR_PNPM_NO_OFFLINE_TARBALL" in result.stdout:
            online_command = [item for item in command if item != "--offline"]
            online_result = subprocess.run(
                online_command,
                cwd=str(workspace),
                text=True,
                encoding="utf-8",
                errors="replace",
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                env=env,
                timeout=600,
            )
            if online_result.returncode == 0:
                cache_filled_online = True
                result = subprocess.run(
                    command,
                    cwd=str(workspace),
                    text=True,
                    encoding="utf-8",
                    errors="replace",
                    stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT,
                    env=env,
                    timeout=600,
                )
            else:
                result = online_result
                command = online_command
    if result.returncode != 0:
        raise StructuredToolError(
            code="hvigor_project_cache_plugin_install_failed",
            message="Failed to install hvigor project-cache plugin dependencies.",
            details={
                "command": format_command(command),
                "cwd": str(workspace),
                "missing": missing,
                "exit_code": result.returncode,
                "output_tail": tail_text(result.stdout),
            },
        )
    notes = ["ENV_PREPARE_HVIGOR_PROJECT_CACHE_PLUGIN_DEPS=installed " + ",".join(missing)]
    if cache_filled_online:
        notes.append("ENV_PREPARE_HVIGOR_PROJECT_CACHE_PLUGIN_STORE=filled_online_then_verified_offline")
    if normalized_notes:
        notes.append("ENV_PREPARE_HVIGOR_PROJECT_CACHE_PLUGIN_VERSION_NORMALIZED=" + ",".join(normalized_notes))
    return notes


def _prepare_legacy_module_build_profile_arkts_version(repo_dir: Path) -> list[str]:
    if _is_parallel_sample_project(repo_dir):
        return []

    notes: list[str] = []
    profiles = [repo_dir / "build-profile.json5"]
    profiles.extend(sorted(repo_dir.glob("*/build-profile.json5"), key=lambda p: str(p)))
    for profile in profiles:
        if not profile.is_file():
            continue

        original = profile.read_text(encoding="utf-8", errors="replace")
        patched = re.sub(
            r'^\s*(?:"arkTSVersion"|arkTSVersion)\s*:\s*["\'][^"\']+["\']\s*,?\s*\r?\n',
            "",
            original,
            flags=re.MULTILINE,
        )
        if patched == original:
            continue

        profile.write_text(patched, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_LEGACY_BUILD_PROFILE_ARKTS_VERSION="
            + format_path_for_display(profile, start=repo_dir)
        )
    return notes


