def _prepare_form_ext_ability_ohos_test_strict_shim(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/SuperFeature/Widget/FormExtAbility"):
        return []

    replacements: dict[str, list[tuple[str, str]]] = {
        "entry/src/ohosTest/ets/test/Ability.test.ets": [
            ("describe('ActsAbilityTest', function () {", "describe('ActsAbilityTest', () => {"),
            ("it('OpenFormList_001', 0, async function (done) {", "it('OpenFormList_001', 0, async (done: Function) => {"),
            ("it('createForm_001', 0, async function () {", "it('createForm_001', 0, async () => {"),
        ],
        "entry/src/ohosTest/ets/test/Form.test.ets": [
            ("async (done) =>", "async (done: Function) =>"),
            (".then((data) =>", ".then((data: Object) =>"),
            (".then((result) =>", ".then((result: Object) =>"),
            (".catch((err) =>", ".catch((err: Error) =>"),
        ],
        "entry/src/ohosTest/ets/testability/TestAbility.ets": [
            (
                "import UIAbility from '@ohos.app.ability.UIAbility';",
                "import UIAbility from '@ohos.app.ability.UIAbility';\n"
                "import AbilityConstant from '@ohos.app.ability.AbilityConstant';\n"
                "import Want from '@ohos.app.ability.Want';\n"
                "import base from '@ohos.base';",
            ),
            ("  onCreate(want, launchParam) {", "  onCreate(want: Want, launchParam: AbilityConstant.LaunchParam): void {"),
            ("  onDestroy() {", "  onDestroy(): void {"),
            (
                "windowStage.loadContent('testability/pages/Index', (err, data) => {",
                "windowStage.loadContent('testability/pages/Index', (err: base.BusinessError<void>) => {",
            ),
            (
                "windowStage.loadContent('testability/pages/Index', (err: base.BusinessError<void>, data: Object) => {",
                "windowStage.loadContent('testability/pages/Index', (err: base.BusinessError<void>) => {",
            ),
            ("  onWindowStageDestroy() {", "  onWindowStageDestroy(): void {"),
            ("  onForeground() {", "  onForeground(): void {"),
            ("  onBackground() {", "  onBackground(): void {"),
            (
                "      hilog.info(0x0000, 'testTag', 'Succeeded in loading the content. Data: %{public}s',\n"
                "        JSON.stringify(data) ?? '');",
                "      hilog.info(0x0000, 'testTag', '%{public}s', 'Succeeded in loading the content.');",
            ),
        ],
    }

    notes: list[str] = []
    for relative, pairs in replacements.items():
        path = repo_dir / relative
        if not path.is_file():
            continue
        original = path.read_text(encoding="utf-8", errors="replace")
        patched = original
        for old, new in pairs:
            patched = patched.replace(old, new)
        if relative == "entry/src/ohosTest/ets/testability/TestAbility.ets":
            seen_imports: set[str] = set()
            deduped_lines: list[str] = []
            for line in patched.splitlines():
                if line.startswith("import ") and line in seen_imports:
                    continue
                if line.startswith("import "):
                    seen_imports.add(line)
                deduped_lines.append(line)
            patched = "\n".join(deduped_lines) + ("\n" if patched.endswith("\n") else "")
        if patched == original:
            continue
        path.write_text(patched, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_FORM_EXT_OHOSTEST_STRICT="
            + format_path_for_display(path, start=repo_dir)
        )
    return notes


