def _prepare_media_recorder_legacy_build_shims(repo_dir: Path, sdk_root: Path | None = None) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/media/Recorder"):
        return []

    ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    if not ets_root.is_dir():
        return []

    notes: list[str] = []

    animate_view = ets_root / "MainAbility" / "common" / "AnimateView.ets"
    if animate_view.is_file():
        original = animate_view.read_text(encoding="utf-8", errors="replace")
        patched = original
        replacements = {
            "@State translate: string = '-0.2%'": "@State translatePosition: string = '-0.2%'",
            "@State translateText: string = '-1%'": "@State translateTextPosition: string = '-1%'",
            "this.translate = '16.3%'": "this.translatePosition = '16.3%'",
            "this.translateText = '15.5%'": "this.translateTextPosition = '15.5%'",
            "this.translate = '-0.2%'": "this.translatePosition = '-0.2%'",
            "this.translateText = '-1%'": "this.translateTextPosition = '-1%'",
            ".translate({ x: this.translateText })": ".translate({ x: this.translateTextPosition })",
            ".translate({ x: this.translate })": ".translate({ x: this.translatePosition })",
        }
        for old, new in replacements.items():
            patched = patched.replace(old, new)
        if patched != original:
            animate_view.write_text(patched, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_MEDIA_RECORDER_LEGACY_SOURCE_COMPAT="
            + format_path_for_display(animate_view, start=repo_dir)
            + " translate_field_rename"
        )

    process_target = ets_root / "@ohos.process.d.ts"
    if not _copy_installed_sdk_api_file("@ohos.process.d.ts", process_target, component="ets"):
        source = _configured_sdk_api_file("@ohos.process.d.ts", component="ets", api_level=9)
        if source is not None:
            process_target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, process_target)
    if process_target.is_file():
        _append_to_declare_namespace(process_target, "process", RECORDER_PROCESS_RUNCMD_COMPAT)
    else:
        process_target.write_text(RECORDER_PROCESS_RUNCMD_SHIM, encoding="utf-8")
    notes.append(
        "ENV_PREPARE_MEDIA_RECORDER_LEGACY_LOCAL_API="
        + format_path_for_display(process_target, start=repo_dir)
        + " runCmd"
    )

    if sdk_root is not None:
        sdk_process_targets = [
            sdk_root / "ets" / "api" / "@ohos.process.d.ts",
            *sorted((sdk_root / "ets").glob("*/api/@ohos.process.d.ts")),
        ]
        for sdk_process_target in sdk_process_targets:
            if not sdk_process_target.is_file():
                continue
            _append_to_declare_namespace(sdk_process_target, "process", RECORDER_PROCESS_RUNCMD_COMPAT)
            notes.append(
                "ENV_PREPARE_MEDIA_RECORDER_LEGACY_SDK_API="
                + format_path_for_display(sdk_process_target)
                + " runCmd"
            )

    file_manager = ets_root / "MainAbility" / "model" / "FileManager.ets"
    if file_manager.is_file():
        original = file_manager.read_text(encoding="utf-8", errors="replace")
        patched = original.replace("process.runCmd(", "(process as any).runCmd(")
        if patched != original:
            file_manager.write_text(patched, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_MEDIA_RECORDER_LEGACY_SOURCE_COMPAT="
            + format_path_for_display(file_manager, start=repo_dir)
            + " process_runCmd_any_cast"
        )

    media_manager = ets_root / "MainAbility" / "model" / "MediaManager.ts"
    if media_manager.is_file():
        original = media_manager.read_text(encoding="utf-8", errors="replace")
        patched = original.replace(
            "mediaLibrary.getMediaLibrary()",
            "mediaLibrary.getMediaLibrary(featureAbility.getContext() as any)",
        )
        if patched != original:
            media_manager.write_text(patched, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_MEDIA_RECORDER_LEGACY_SOURCE_COMPAT="
            + format_path_for_display(media_manager, start=repo_dir)
            + " mediaLibrary_getMediaLibrary_context"
        )

    return notes


def _prepare_static_subscriber_legacy_build_shims(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/SystemFeature/ApplicationModels/StaticSubscriber"):
        return []

    entry_ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    publish_ets_root = repo_dir / "publish" / "src" / "main" / "ets"
    if not entry_ets_root.is_dir():
        return []

    notes: list[str] = []

    extension_target = entry_ets_root / "@ohos.application.StaticSubscriberExtensionAbility.d.ts"
    if (
        not extension_target.is_file()
        or extension_target.read_text(encoding="utf-8", errors="replace") != STATIC_SUBSCRIBER_EXTENSION_ABILITY_SHIM
    ):
        extension_target.write_text(STATIC_SUBSCRIBER_EXTENSION_ABILITY_SHIM, encoding="utf-8")
    notes.append(
        "ENV_PREPARE_STATIC_SUBSCRIBER_LOCAL_API="
        + format_path_for_display(extension_target, start=repo_dir)
    )

    for ets_root in (entry_ets_root, publish_ets_root):
        if not ets_root.is_dir():
            continue
        common_event_target = ets_root / "@ohos.commonEventManager.d.ts"
        if _copy_installed_sdk_api_file("@ohos.commonEventManager.d.ts", common_event_target, component="ets"):
            _append_to_declare_namespace(common_event_target, "commonEventManager", STATIC_SUBSCRIBER_COMMON_EVENT_COMPAT)
        elif (
            not common_event_target.is_file()
            or common_event_target.read_text(encoding="utf-8", errors="replace") != STATIC_SUBSCRIBER_COMMON_EVENT_SHIM
        ):
            common_event_target.write_text(STATIC_SUBSCRIBER_COMMON_EVENT_SHIM, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_STATIC_SUBSCRIBER_LOCAL_API="
            + format_path_for_display(common_event_target, start=repo_dir)
        )

    notification_target = entry_ets_root / "@ohos.notificationManager.d.ts"
    if (
        not notification_target.is_file()
        or notification_target.read_text(encoding="utf-8", errors="replace") != STATIC_SUBSCRIBER_NOTIFICATION_SHIM
    ):
        notification_target.write_text(STATIC_SUBSCRIBER_NOTIFICATION_SHIM, encoding="utf-8")
    notes.append(
        "ENV_PREPARE_STATIC_SUBSCRIBER_LOCAL_API="
        + format_path_for_display(notification_target, start=repo_dir)
    )

    for source_path in (
        entry_ets_root / "pages" / "Index.ets",
        entry_ets_root / "StaticSubscriber" / "StaticSubscriber.ts",
        publish_ets_root / "pages" / "Index.ets",
    ):
        if not source_path.is_file():
            continue
        original = source_path.read_text(encoding="utf-8", errors="replace")
        patched = original
        patched = patched.replace("} catch (error) {", "} catch {")
        patched = patched.replace("} catch (err) {", "} catch {")
        patched = patched.replace(".catch((err) =>", ".catch(() =>")
        patched = patched.replace(
            "catch {\n              Logger.error(`showToast args error code is ${error.code}, message is ${error.message}`);",
            "catch {\n              Logger.error('showToast args error');",
        )
        patched = patched.replace(
            "catch {\n              Logger.error('showToast args error code is ${error.code}, message is ${error.message}');",
            "catch {\n              Logger.error('showToast args error');",
        )
        patched = patched.replace(
            "catch {\n              Logger.error(`showToast args error code is ${error.code}, message is ${error.message}`);",
            "catch {\n              Logger.error('showToast args error');",
        )
        patched = patched.replace(
            "catch {\n              Logger.error(`publish failed, catch error ${JSON.stringify(err)}`);",
            "catch {\n            Logger.error('publish failed, catch error');",
        )
        patched = re.sub(
            r"Logger\.error\(`showToast args error code is \$\{error\.code\}, message is \$\{error\.message\}`\);",
            "Logger.error('showToast args error');",
            patched,
        )
        patched = re.sub(
            r"Logger\.error\(`publish failed, catch error \$\{JSON\.stringify\(err\)\}`\);",
            "Logger.error('publish failed, catch error');",
            patched,
        )
        patched = patched.replace(
            "Logger.info(`Set static subscriber state failed, errCode: ${err.code}, errMes: ${err.message}`);",
            "Logger.info('Set static subscriber state failed');",
        )
        patched = patched.replace(
            "Logger.info('Set static subscriber state failed, errCode: ${err.code}, errMes: ${err.message}');",
            "Logger.info('Set static subscriber state failed');",
        )
        patched = patched.replace("function publishCallback(err) {", "function publishCallback(err: Error) {")
        patched = patched.replace(
            "export default class StaticSubscriber extends StaticSubscriberExtensionAbility {",
            (
                "interface StaticSubscriberEvent {\n"
                "  event?: string;\n"
                "  data?: string;\n"
                "}\n\n"
                "export default class StaticSubscriber extends StaticSubscriberExtensionAbility {"
            ),
        )
        patched = patched.replace(
            "onReceiveEvent(event) {",
            "onReceiveEvent(event: StaticSubscriberEvent) {",
        )
        if patched != original:
            source_path.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_STATIC_SUBSCRIBER_STRICT_COMPAT="
                + format_path_for_display(source_path, start=repo_dir)
            )
    return notes


def _prepare_notification_legacy_build_shims(repo_dir: Path, sdk_root: Path | None = None) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/Notification/Notification"):
        return []

    notes: list[str] = []
    ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    if not ets_root.is_dir():
        return notes

    for filename, content in STAGE_CALL_ABILITY_API_SHIMS.items():
        target = ets_root / filename
        if not target.exists() or target.read_text(encoding="utf-8", errors="replace") != content:
            target.write_text(content, encoding="utf-8")
            notes.append("ENV_PREPARE_NOTIFICATION_LOCAL_API=" + format_path_for_display(target, start=repo_dir))

    notification_subscribe_target = ets_root / "@ohos.notificationSubscribe.d.ts"
    if (
        not notification_subscribe_target.is_file()
        or notification_subscribe_target.read_text(encoding="utf-8", errors="replace") != NOTIFICATION_SUBSCRIBE_LOCAL_SHIM
    ):
        notification_subscribe_target.write_text(NOTIFICATION_SUBSCRIBE_LOCAL_SHIM, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_NOTIFICATION_LOCAL_API="
            + format_path_for_display(notification_subscribe_target, start=repo_dir)
            + " notificationSubscribe"
        )

    want_agent_candidates = [ets_root / "@ohos.wantAgent.d.ts"]
    if not want_agent_candidates[0].is_file():
        copied = _copy_installed_sdk_api_file(
            "@ohos.wantAgent.d.ts",
            want_agent_candidates[0],
            component="ets",
        )
        if copied:
            notes.append(
                "ENV_PREPARE_NOTIFICATION_LOCAL_API="
                + format_path_for_display(want_agent_candidates[0], start=repo_dir)
                + " copied_wantAgent"
            )
    if sdk_root is not None:
        want_agent_candidates.extend(sorted(sdk_root.glob("**/api/@ohos.wantAgent.d.ts")))
    local_properties = repo_dir / "local.properties"
    if local_properties.is_file():
        for line in local_properties.read_text(encoding="utf-8", errors="replace").splitlines():
            if line.startswith("sdk.dir="):
                actual_sdk = Path(line.split("=", 1)[1].strip())
                want_agent_candidates.extend(sorted(actual_sdk.glob("**/api/@ohos.wantAgent.d.ts")))
                break
    for want_agent in want_agent_candidates:
        if not want_agent.is_file():
            continue
        original = want_agent.read_text(encoding="utf-8", errors="replace")
        cleaned = original.replace("\n  export function getWant(agent: WantAgent): Promise<Object>;\n", "\n")
        if cleaned != original:
            want_agent.write_text(cleaned, encoding="utf-8")
            notes.append("ENV_PREPARE_NOTIFICATION_LOCAL_API=" + format_path_for_display(want_agent, start=repo_dir) + " remove_bad_getWant")
        if "function getWant(agent: WantAgent)" not in want_agent.read_text(encoding="utf-8", errors="replace"):
            _append_to_declare_namespace(want_agent, "wantAgent", NOTIFICATION_WANT_AGENT_COMPAT)
            notes.append("ENV_PREPARE_NOTIFICATION_LOCAL_API=" + format_path_for_display(want_agent, start=repo_dir) + " add_getWant")
    return notes


