def _prepare_custom_notification_legacy_build_shims(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/Notification/CustomNotification"):
        return []

    main_ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    if not main_ets_root.is_dir():
        return []

    notes: list[str] = []
    ability_api_roots = [main_ets_root]
    ohos_test_ets = repo_dir / "entry" / "src" / "ohosTest" / "ets"
    if ohos_test_ets.is_dir():
        ability_api_roots.extend([ohos_test_ets, ohos_test_ets / "TestAbility"])
    for ets_root in ability_api_roots:
        if not ets_root.is_dir():
            continue
        for filename, content in STAGE_CALL_ABILITY_API_SHIMS.items():
            target = ets_root / filename
            if not target.is_file() or target.read_text(encoding="utf-8", errors="replace") != content:
                target.write_text(content, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_CUSTOM_NOTIFICATION_LOCAL_API="
                + format_path_for_display(target, start=repo_dir)
            )

    notification_target = main_ets_root / "@ohos.notification.d.ts"
    if (
        not notification_target.is_file()
        or notification_target.read_text(encoding="utf-8", errors="replace") != CUSTOM_NOTIFICATION_NOTIFICATION_SHIM
    ):
        notification_target.write_text(CUSTOM_NOTIFICATION_NOTIFICATION_SHIM, encoding="utf-8")
    notes.append(
        "ENV_PREPARE_CUSTOM_NOTIFICATION_LOCAL_API="
        + format_path_for_display(notification_target, start=repo_dir)
    )

    node_modules_target = repo_dir / "node_modules" / "@ohos" / "notification"
    notification_source = repo_dir / "notification"
    if notification_source.is_dir() and not node_modules_target.exists():
        node_modules_target.parent.mkdir(parents=True, exist_ok=True)
        try:
            os.symlink(notification_source, node_modules_target, target_is_directory=True)
        except OSError:
            shutil.copytree(notification_source, node_modules_target)
        notes.append(
            "ENV_PREPARE_CUSTOM_NOTIFICATION_FILE_DEP="
            + format_path_for_display(node_modules_target, start=repo_dir)
        )

    return notes


def _prepare_hello_world_legacy_build_shims(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/HelloWorld"):
        return []

    ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    if not ets_root.is_dir():
        return []

    notes: list[str] = []

    index_path = ets_root / "pages" / "Index.ets"
    if index_path.is_file():
        original = index_path.read_text(encoding="utf-8", errors="replace")
        patched = original
        patched = "\n".join(
            line
            for line in patched.splitlines()
            if " from '@ohos.arkui.component'" not in line
            and " from '@ohos.arkui.stateManagement'" not in line
        )
        if original.endswith("\n"):
            patched += "\n"
        patched = patched.replace("Column(undefined) {", "Column() {")
        patched = patched.replace(".onClick((e: ClickEvent) => {", ".onClick(() => {")
        patched = patched.replace(
            "Child({stateVar: this.stateVar} as __Options_Child)",
            "Child({ stateVar: this.stateVar })",
        )
        if patched != original:
            index_path.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_HELLO_WORLD_LEGACY_ARKUI="
                + format_path_for_display(index_path, start=repo_dir)
            )

    callback_path = ets_root / "models" / "MyCallback.ets"
    if callback_path.is_file():
        original = callback_path.read_text(encoding="utf-8", errors="replace")
        patched = original
        patched = patched.replace("const SYNTAX_ERROR_CODE: double = 1002;", "const SYNTAX_ERROR_CODE: number = 1002;")
        patched = patched.replace(
            "let error = new Error('Business Error', 'basicError2 message', undefined);\n"
            "    let be2: BusinessError<string> = new BusinessError<string>(SYNTAX_ERROR_CODE, error);\n"
            "    callback(be2, 'yAsyncCallback');",
            "let be2 = { code: SYNTAX_ERROR_CODE, message: 'basicError2 message' } as BusinessError<string>;\n"
            "    callback(be2, 'yAsyncCallback');",
        )
        patched = patched.replace(
            "let error = new Error('Business Error', 'myErrorCallback message', undefined);\n"
            "    let result: string = 'test';\n"
            "    let be: BusinessError<string> = new BusinessError<string>(SYNTAX_ERROR_CODE, result, error);\n"
            "    callback(be);",
            "let be = { code: SYNTAX_ERROR_CODE, message: 'myErrorCallback message' } as BusinessError<string>;\n"
            "    callback(be);",
        )
        if patched != original:
            callback_path.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_HELLO_WORLD_LEGACY_CALLBACK="
                + format_path_for_display(callback_path, start=repo_dir)
            )

    ability_path = ets_root / "entryability" / "EntryAbility.ets"
    if ability_path.is_file():
        original = ability_path.read_text(encoding="utf-8", errors="replace")
        patched = original.replace("} catch (e: Error) {", "} catch (e) {")
        patched = patched.replace(" + e.message);", " + (e as Error).message);")
        if (
            "export default class EntryAbility extends UIAbility" not in patched
            and "class EntryAbility extends UIAbility" in patched
        ):
            patched = patched.replace(
                "class EntryAbility extends UIAbility",
                "export default class EntryAbility extends UIAbility",
                1,
            )
        patched = patched.replace("\n\nexport default EntryAbility;\n", "\n")
        if patched != original:
            ability_path.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_HELLO_WORLD_LEGACY_CATCH="
                + format_path_for_display(ability_path, start=repo_dir)
            )

    return notes


