def _prepare_launcher_legacy_build_shims(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/code/SystemFeature/ApplicationModels/Launcher"):
        return []

    notes: list[str] = []

    app_json = repo_dir / "AppScope" / "app.json5"
    if app_json.is_file():
        original = app_json.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            data = None
        app = data.get("app") if isinstance(data, dict) else None
        if isinstance(app, dict) and "distributedNotificationEnabled" in app:
            app.pop("distributedNotificationEnabled", None)
            app_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append(
                "ENV_PREPARE_LAUNCHER_APP_PROFILE="
                + format_path_for_display(app_json, start=repo_dir)
                + " removed_distributedNotificationEnabled"
            )

    build_profile = repo_dir / "build-profile.json5"
    if build_profile.is_file():
        original = build_profile.read_text(encoding="utf-8", errors="replace")
        patched = re.sub(
            r'((?:"compatibleSdkVersion"|compatibleSdkVersion)\s*:\s*)10',
            r"\g<1>9",
            original,
            count=1,
        )
        if patched != original:
            build_profile.write_text(patched, encoding="utf-8", newline="")
            notes.append(
                "ENV_PREPARE_LAUNCHER_ARKTS_LINTER_COMPAT="
                + format_path_for_display(build_profile, start=repo_dir)
                + " compatibleSdkVersion=10->9"
            )

    module_roots = [
        repo_dir / "entry" / "src" / "main" / "ets",
        repo_dir / "entry" / "src" / "ohosTest" / "ets",
        repo_dir / "base" / "src" / "main" / "ets",
        repo_dir / "desktop" / "src" / "main" / "ets",
        repo_dir / "recents" / "src" / "main" / "ets",
    ]
    shim_by_name = {
        "@ohos.app.form.formHost.d.ts": LAUNCHER_FORM_HOST_SHIM,
        "@ohos.bundle.launcherBundleManager.d.ts": LAUNCHER_BUNDLE_MANAGER_SHIM,
        "@ohos.bundle.bundleMonitor.d.ts": LAUNCHER_BUNDLE_MONITOR_SHIM,
        "@ohos.application.missionManager.d.ts": LAUNCHER_MISSION_MANAGER_SHIM,
        "@ohos.app.ability.ServiceExtensionAbility.d.ts": LAUNCHER_SERVICE_EXTENSION_ABILITY_SHIM,
        "@ohos.notificationSubscribe.d.ts": LAUNCHER_NOTIFICATION_SUBSCRIBE_SHIM,
    }
    for ets_root in module_roots:
        if not ets_root.is_dir():
            continue
        for file_name, content in shim_by_name.items():
            target = ets_root / file_name
            if not target.is_file() or target.read_text(encoding="utf-8", errors="replace") != content:
                target.write_text(content, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_LAUNCHER_LOCAL_API="
                + format_path_for_display(target, start=repo_dir)
            )

        form_component_target = ets_root / "launcher_form_component_global.d.ts"
        if (
            not form_component_target.is_file()
            or form_component_target.read_text(encoding="utf-8", errors="replace") != LAUNCHER_FORM_COMPONENT_GLOBAL_SHIM
        ):
            form_component_target.write_text(LAUNCHER_FORM_COMPONENT_GLOBAL_SHIM, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_LAUNCHER_LOCAL_API="
            + format_path_for_display(form_component_target, start=repo_dir)
        )

    bundle_target = repo_dir / "base" / "src" / "main" / "ets" / "@ohos.bundle.d.ts"
    if bundle_target.parent.is_dir():
        if _copy_installed_sdk_api_file("@ohos.bundle.d.ts", bundle_target, component="ets"):
            _append_to_declare_namespace(bundle_target, "bundle", """

  export interface InstallParam {
    userId?: number;
    installFlag?: number;
    isKeepData?: boolean;
  }

  export interface BundleInstaller {
    uninstall(bundleName: string, installParam: InstallParam, callback: (result: Object) => void): void;
  }

  export function getBundleInstaller(): Promise<BundleInstaller>;""")
        elif not bundle_target.is_file() or bundle_target.read_text(encoding="utf-8", errors="replace") != LAUNCHER_BUNDLE_SHIM:
            bundle_target.write_text(LAUNCHER_BUNDLE_SHIM, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_LAUNCHER_LOCAL_API="
            + format_path_for_display(bundle_target, start=repo_dir)
        )

    window_target = repo_dir / "entry" / "src" / "main" / "ets" / "@ohos.window.d.ts"
    if window_target.parent.is_dir():
        if not _copy_installed_sdk_api_file("@ohos.window.d.ts", window_target, component="ets"):
            source = _configured_sdk_api_file("@ohos.window.d.ts", component="ets", api_level=9)
            if source is not None:
                window_target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(source, window_target)
        _append_to_declare_namespace(window_target, "window", """

  export enum WindowType {
    TYPE_DESKTOP = 2100
  }""")
        if window_target.is_file():
            notes.append(
                "ENV_PREPARE_LAUNCHER_LOCAL_API="
                + format_path_for_display(window_target, start=repo_dir)
            )

    for module_json in (
        repo_dir / "entry" / "src" / "main" / "module.json5",
        repo_dir / "entry" / "src" / "ohosTest" / "module.json5",
    ):
        if not module_json.is_file():
            continue
        original = module_json.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            data = None
        module = data.get("module") if isinstance(data, dict) else None
        changed = False
        if isinstance(module, dict):
            if "srcEntry" not in module and isinstance(module.get("srcEntrance"), str):
                module["srcEntry"] = module["srcEntrance"]
                changed = True
            if "srcEntry" in module and "srcEntrance" in module:
                module.pop("srcEntrance", None)
                changed = True
            for key in ("abilities", "extensionAbilities"):
                values = module.get(key)
                if not isinstance(values, list):
                    continue
                for ability in values:
                    if not isinstance(ability, dict):
                        continue
                    if "srcEntry" not in ability and isinstance(ability.get("srcEntrance"), str):
                        ability["srcEntry"] = ability["srcEntrance"]
                        changed = True
                    if "srcEntry" in ability and "srcEntrance" in ability:
                        ability.pop("srcEntrance", None)
                        changed = True
        if changed and data is not None:
            module_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append(
                "ENV_PREPARE_LAUNCHER_SRC_ENTRY="
                + format_path_for_display(module_json, start=repo_dir)
            )

    main_module_json = repo_dir / "entry" / "src" / "main" / "module.json5"
    if main_module_json.is_file():
        original = main_module_json.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            data = None
        module = data.get("module") if isinstance(data, dict) else None
        if isinstance(module, dict):
            permissions = module.get("requestPermissions")
            if isinstance(permissions, list):
                blocked = {
                    "ohos.permission.START_ABILITIES_FROM_BACKGROUND",
                    "ohos.permission.GET_BUNDLE_INFO_PRIVILEGED",
                    "ohos.permission.INSTALL_BUNDLE",
                    "ohos.permission.LISTEN_BUNDLE_CHANGE",
                    "ohos.permission.MANAGE_MISSIONS",
                    "ohos.permission.REQUIRE_FORM",
                    "ohos.permission.NOTIFICATION_CONTROLLER",
                }
                filtered = [
                    item for item in permissions
                    if not (isinstance(item, dict) and item.get("name") in blocked)
                ]
                if len(filtered) != len(permissions):
                    if filtered:
                        module["requestPermissions"] = filtered
                    else:
                        module.pop("requestPermissions", None)
                    main_module_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
                    notes.append("ENV_PREPARE_LAUNCHER_PERMISSIONS=removed_install_blocking_permissions")

    source_replacements: dict[str, list[tuple[str, str]]] = {
        "base/src/main/ets/default/manager/LauncherAbilityManager.ts": [
            (
                "const TAG: string = 'LauncherAbilityManager'\n",
                (
                    "const TAG: string = 'LauncherAbilityManager'\n\n"
                    "interface LegacyInstallParam {\n"
                    "  userId?: number;\n"
                    "  installFlag?: number;\n"
                    "  isKeepData?: boolean;\n"
                    "}\n\n"
                    "interface LegacyBundleInstaller {\n"
                    "  uninstall(bundleName: string, installParam: LegacyInstallParam, callback: (result: Object) => void): void;\n"
                    "}\n\n"
                    "interface LegacyBundleMgr {\n"
                    "  getBundleInstaller(): Promise<LegacyBundleInstaller>;\n"
                    "}\n"
                ),
            ),
            (
                "const bundlerInstaller = await bundleMgr.getBundleInstaller()",
                "const bundlerInstaller = await (bundleMgr as Object as LegacyBundleMgr).getBundleInstaller()",
            ),
        ],
        "desktop/src/main/ets/default/components/Bubble.ets": [
            (
                "const TAG: string = 'Bubble'\n",
                (
                    "declare class FormComponentAttribute {\n"
                    "  clip(value: Object): FormComponentAttribute;\n"
                    "  size(value: Object): FormComponentAttribute;\n"
                    "  onAcquired(callback: (form: { id: number }) => void): FormComponentAttribute;\n"
                    "}\n"
                    "declare function FormComponent(options: Object): FormComponentAttribute;\n\n"
                    "const TAG: string = 'Bubble'\n"
                ),
            ),
        ],
        "desktop/src/main/ets/default/components/CardItem.ets": [
            (
                "const TAG: string = 'CardItem'\n",
                (
                    "declare class FormComponentAttribute {\n"
                    "  clip(value: Object): FormComponentAttribute;\n"
                    "  size(value: Object): FormComponentAttribute;\n"
                    "  onAcquired(callback: (form: { id: number }) => void): FormComponentAttribute;\n"
                    "  allowUpdate(value: boolean): FormComponentAttribute;\n"
                    "}\n"
                    "declare function FormComponent(options: Object): FormComponentAttribute;\n\n"
                    "const TAG: string = 'CardItem'\n"
                ),
            ),
        ],
        "entry/src/main/ets/components/FormManagerComponent.ets": [
            (
                "const TAG: string = 'FormManagerComponent'\n",
                (
                    "declare class FormComponentAttribute {\n"
                    "  clip(value: Object): FormComponentAttribute;\n"
                    "  size(value: Object): FormComponentAttribute;\n"
                    "  onAcquired(callback: (form: { id: number }) => void): FormComponentAttribute;\n"
                    "}\n"
                    "declare function FormComponent(options: Object): FormComponentAttribute;\n\n"
                    "const TAG: string = 'FormManagerComponent'\n"
                ),
            ),
        ],
        "desktop/src/main/ets/default/components/LauncherGridLayout.ets": [
            (
                "let context = getContext(this) as common.ServiceExtensionContext\n",
                "let context: any = getContext(this)\n",
            ),
        ],
        "recents/src/main/ets/default/model/MissionModel.ts": [
            (
                "let snapshot: image.PixelMap = missionSnapshot.snapshot\n",
                "let snapshot: image.PixelMap = missionSnapshot.snapshot as image.PixelMap\n",
            ),
        ],
        "entry/src/ohosTest/ets/testability/TestAbility.ts": [
            (
                "    let serviceWant = {\n",
                "    let serviceWant: any = {\n",
            ),
            (
                "      'abilityName': 'MainAbility'\n    }\n",
                "      'abilityName': 'MainAbility'\n    };\n",
            ),
            (
                "    this.context.startServiceExtensionAbility(serviceWant).then(() => {",
                "    (this.context as any).startServiceExtensionAbility(serviceWant).then(() => {",
            ),
        ],
    }
    for relative, replacements in source_replacements.items():
        source_path = repo_dir / relative
        if not source_path.is_file():
            continue
        original = source_path.read_text(encoding="utf-8", errors="replace")
        patched = original
        for old, new in replacements:
            if old in patched and new not in patched:
                patched = patched.replace(old, new, 1)
        if patched != original:
            source_path.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_LAUNCHER_STRICT_COMPAT="
                + format_path_for_display(source_path, start=repo_dir)
            )

    return notes


