def _prepare_flipclock_legacy_build_shims(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith(("/CompleteApps/FlipClock", "/Solutions/Tools/FlipClock")):
        return []

    ets_root = repo_dir / "entry" / "src" / "main" / "ets" / "MainAbility"
    if not ets_root.is_dir():
        ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    if not ets_root.is_dir():
        return []

    notes: list[str] = []

    hvigor_config = repo_dir / "hvigor" / "hvigor-config.json5"
    if hvigor_config.is_file():
        original = hvigor_config.read_text(encoding="utf-8", errors="replace")
        patched = re.sub(
            r'("hvigorVersion"\s*:\s*)"[23]\.\d+\.\d+"',
            r'\g<1>"4.1.2"',
            original,
        )
        patched = re.sub(
            r'("@ohos/hvigor-ohos-plugin"\s*:\s*)"[23]\.\d+\.\d+"',
            r'\g<1>"4.1.2"',
            patched,
        )
        if patched != original:
            hvigor_config.write_text(patched, encoding="utf-8")
            notes.append("ENV_PREPARE_FLIPCLOCK_HVIGOR=legacy->4.1.2")

    module_json = repo_dir / "entry" / "src" / "main" / "module.json5"
    if module_json.is_file():
        try:
            module_data = parse_json5_text(module_json.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            module_data = None
        module = module_data.get("module") if isinstance(module_data, dict) else None
        permissions = module.get("requestPermissions") if isinstance(module, dict) else None
        changed = False
        if isinstance(permissions, list):
            for permission in permissions:
                if not isinstance(permission, dict) or permission.get("name") not in {
                    "ohos.permission.READ_CALENDAR",
                    "ohos.permission.WRITE_CALENDAR",
                }:
                    continue
                if "reason" not in permission:
                    permission["reason"] = "$string:module_desc"
                    changed = True
                if "usedScene" not in permission:
                    permission["usedScene"] = {"abilities": ["EntryAbility"], "when": "inuse"}
                    changed = True
        if changed:
            module_json.write_text(json.dumps(module_data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append("ENV_PREPARE_FLIPCLOCK_CALENDAR_PERMISSION=reason_usedScene")

    local_apis = {
        "@ohos.runninglock.d.ts": FLIPCLOCK_RUNNINGLOCK_SHIM,
        "@ohos.brightness.d.ts": FLIPCLOCK_BRIGHTNESS_SHIM,
    }
    for filename, content in local_apis.items():
        target = ets_root / filename
        if not target.is_file() or target.read_text(encoding="utf-8", errors="replace") != content:
            target.write_text(content, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_FLIPCLOCK_LOCAL_API="
            + format_path_for_display(target, start=repo_dir)
        )

    notification_target = ets_root / "@ohos.notificationManager.d.ts"
    if _copy_installed_sdk_api_file("@ohos.notificationManager.d.ts", notification_target, component="ets"):
        original = notification_target.read_text(encoding="utf-8", errors="replace")
        if "interface NotificationEnableBundleOption" not in original:
            _append_to_declare_namespace(
                notification_target,
                "notificationManager",
                "  export interface NotificationEnableBundleOption {\n"
                "    bundle: string;\n"
                "  }\n\n"
                "  export function isNotificationEnabled(bundle: NotificationEnableBundleOption): Promise<boolean>;\n"
                "  export function setNotificationEnable(bundle: NotificationEnableBundleOption, enable: boolean): Promise<void>;\n",
            )
        elif "setNotificationEnable(bundle: NotificationEnableBundleOption" not in original:
            _append_to_declare_namespace(
                notification_target,
                "notificationManager",
                "  export function isNotificationEnabled(bundle: NotificationEnableBundleOption): Promise<boolean>;\n"
                "  export function setNotificationEnable(bundle: NotificationEnableBundleOption, enable: boolean): Promise<void>;\n",
            )
        notes.append(
            "ENV_PREPARE_FLIPCLOCK_LOCAL_API="
            + format_path_for_display(notification_target, start=repo_dir)
        )
    elif not notification_target.is_file():
        notification_target.write_text(
            "declare namespace notificationManager {\n"
            "  export interface NotificationEnableBundleOption { bundle: string; }\n"
            "  export function isNotificationEnabled(bundle: NotificationEnableBundleOption): Promise<boolean>;\n"
            "  export function setNotificationEnable(bundle: NotificationEnableBundleOption, enable: boolean): Promise<void>;\n"
            "  export function requestEnableNotification(callback?: () => void): Promise<void>;\n"
            "}\n"
            "export default notificationManager;\n",
            encoding="utf-8",
        )
        notes.append(
            "ENV_PREPARE_FLIPCLOCK_LOCAL_API="
            + format_path_for_display(notification_target, start=repo_dir)
        )

    replacements: dict[str, list[tuple[str, str]]] = {
        "common/Setting.ets": [
            ("  brightness() {\n    brightness.setValue(this.inSetValue)\n  }",
             "  applyBrightness(): void {\n    brightness.setValue(this.inSetValue)\n  }"),
            ("            this.brightness()\n", "            this.applyBrightness()\n"),
        ],
        "pages/Index.ets": [
            ("  brightness() {\n    brightness.setValue(this.value)\n  }",
             "  applyBrightness(): void {\n    brightness.setValue(this.value)\n  }"),
            ("          this.brightness()\n", "          this.applyBrightness()\n"),
        ],
        "model/StorageModel.ets": [
            ("  static instance: StorageModel  = null\n  private storage = null",
             "  static instance: StorageModel | null = null\n  private storage: any = null"),
            ("  public static getInstance() {", "  public static getInstance(): StorageModel {"),
            ("  async putStorageValue(putKey: string, alarmClock) {",
             "  async putStorageValue(putKey: string, alarmClock: Object) {"),
            ("    let getValue = this.storage.get(getKey, 'null')",
             "    let getValue: string = this.storage.get(getKey, 'null') as string"),
            ("    let result = await this.storage.get(key, 'null')",
             "    let result: string = await this.storage.get(key, 'null') as string"),
        ],
        "common/CustomDataPicker.ets": [
            ("  private total: number\n  private selectedTime: Date = new Date()\n  private controller: CustomDialogController\n  private countChange: (result: number) => void",
             "  private total: number = 0\n  private selectedTime: Date = new Date()\n  private controller?: CustomDialogController\n  private countChange: (result: number) => void = (_result: number): void => {}"),
            ("            let dateTime = { hour: this.hourTest, minute: this.minuteTest, reminderId: this.reminderId }",
             "            let dateTime: Object = { hour: this.hourTest, minute: this.minuteTest, reminderId: this.reminderId }"),
            ("            this.controller.close()", "            this.controller?.close()"),
          ],
        "common/AlarmClock.ets": [
            ("    let amount = await this.storage.getStorageValue('amount')\n    for (let i = 0;i <= amount; i++) {",
             "    let amount = await this.storage.getStorageValue('amount')\n    let amountCount: number = amount === 'null' ? 0 : parseInt(amount)\n    for (let i = 0;i <= amountCount; i++) {"),
            ("  @Link listItems: Array<any>\n  @StorageLink('clockTime') clockTime: any = []\n  private datePicker: CustomDialogController = null",
             "  @Link listItems: Array<unknown>\n  @StorageLink('clockTime') clockTime: Array<unknown> = []\n  private datePicker?: CustomDialogController"),
            ("        this.listItems.push({ key: `alarmClock${i}`, value: dataTime, reminderId: JSON.parse(alarmClock).reminderId })",
             "        let listItem: Object = { key: `alarmClock${i}`, value: dataTime, reminderId: JSON.parse(alarmClock).reminderId }\n        this.listItems.push(listItem)"),
            ("  countChange(result) {",
             "  countChange(result: number): void {"),
            ("            if (this.datePicker == null) {",
             "            if (this.datePicker == null) {"),
            ("            if (this.datePicker === undefined) {",
             "            if (this.datePicker == null) {"),
            ("                  .onClick(() => {\n                    this.storage.deleteSync(item.key)",
             "                  .onClick(() => {\n                    let itemRecord: Record<string, Object> = item as Record<string, Object>\n                    this.storage.deleteSync(itemRecord.key as string)"),
            ("                    reminderAgent.cancelReminder(item.reminderId, () => {",
             "                    reminderAgent.cancelReminder(itemRecord.reminderId as number, () => {"),
          ],
    }
    for relative, pairs in replacements.items():
        source_path = ets_root / relative
        if not source_path.is_file():
            continue
        original = source_path.read_text(encoding="utf-8", errors="replace")
        patched = original
        for old, new in pairs:
            patched = patched.replace(old, new)
        if patched != original:
            source_path.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_FLIPCLOCK_STRICT_COMPAT="
                + format_path_for_display(source_path, start=repo_dir)
                + " brightness_method_rename"
            )

    return notes


