WLAN_LEGACY_WIFI_API_SHIM = """declare module '@ohos.wifi' {
  export interface WifiScanInfo {
    ssid: string;
    bssid: string;
    securityType: number;
    rssi: number;
    band: number;
    frequency: number;
    timestamp: number;
  }

  export interface WifiDeviceConfig {
    ssid: string;
    bssid?: string;
    preSharedKey?: string;
    isHiddenSsid?: boolean;
    securityType?: number;
  }

  export interface WifiLinkedInfo {
    ssid: string;
    bssid: string;
    networkId: number;
    rssi: number;
    band: number;
  }

  export interface IpInfo {
    ipAddress: number;
    gateway: number;
    netmask: number;
    primaryDns: number;
    secondDns: number;
    serverIp: number;
    leaseDuration: number;
  }

  export function isWifiActive(): boolean;
  export function scan(): boolean;
  export function getScanInfos(callback: (err: Error | undefined, result: Array<WifiScanInfo>) => void): void;
  export function getLinkedInfo(callback: (err: Error | undefined, linkedInfo: WifiLinkedInfo | null) => void): void;
  export function connectToDevice(config: WifiDeviceConfig): boolean;
  export function addDeviceConfig(config: WifiDeviceConfig): boolean;
  export function enableWifi(): boolean;
  export function disableWifi(): boolean;
  export function disconnect(): boolean;
  export function getIpInfo(): IpInfo;
  export function getCountryCode(): string;
  export function isFeatureSupported(featureId: number): boolean;
  export function on(type: string, callback: (state: number) => void): void;
  export function off(type: string): void;
}
"""


WLAN_LEGACY_WIFI_API_COMPAT = """
  function connectToDevice(config: WifiDeviceConfig): boolean;
  function addDeviceConfig(config: WifiDeviceConfig): boolean;
  function enableWifi(): boolean;
  function disableWifi(): boolean;
  function disconnect(): boolean;
"""


def _prepare_wlan_legacy_build_shims(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/Communication/Wlan"):
        return []

    ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    if not ets_root.is_dir():
        return []

    target = ets_root / "@ohos.wifi.d.ts"
    if not target.is_file() or target.read_text(encoding="utf-8", errors="replace") != WLAN_LEGACY_WIFI_API_SHIM:
        target.write_text(WLAN_LEGACY_WIFI_API_SHIM, encoding="utf-8")
    notes = [
        "ENV_PREPARE_WLAN_LOCAL_API="
        + format_path_for_display(target, start=repo_dir)
    ]
    ohos_test_ets_root = repo_dir / "entry" / "src" / "ohosTest" / "ets"
    if ohos_test_ets_root.is_dir():
        for uitest_target in (
            ohos_test_ets_root / "@ohos.uitest.d.ts",
            ohos_test_ets_root / "test" / "@ohos.uitest.d.ts",
            ohos_test_ets_root / "TestAbility" / "@ohos.uitest.d.ts",
        ):
            if not uitest_target.parent.is_dir():
                continue
            if _copy_installed_sdk_api_file("@ohos.UiTest.d.ts", uitest_target, component="ets"):
                notes.append(
                    "ENV_PREPARE_WLAN_OHOSTEST_LOCAL_API="
                    + format_path_for_display(uitest_target, start=repo_dir)
                )
    return notes


def _prepare_wlan_legacy_sdk_api_shim(repo_dir: Path, sdk_root: Path | None) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/Communication/Wlan") or sdk_root is None:
        return []

    candidates = [
        sdk_root / "ets" / "api" / "@ohos.wifi.d.ts",
        *sorted((sdk_root / "ets").glob("*/api/@ohos.wifi.d.ts")),
    ]
    notes: list[str] = []
    for wifi_api in candidates:
        if not wifi_api.is_file():
            continue
        before = wifi_api.read_text(encoding="utf-8", errors="replace")
        _append_to_declare_namespace(wifi_api, "wifi", WLAN_LEGACY_WIFI_API_COMPAT)
        after = wifi_api.read_text(encoding="utf-8", errors="replace")
        if after != before or WLAN_LEGACY_WIFI_API_COMPAT.strip() in after:
            notes.append(
                "ENV_PREPARE_WLAN_SDK_API="
                + format_path_for_display(wifi_api, start=repo_dir)
            )
    return notes


