def _prepare_stage_model_legacy_build_shims(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/ability/StageModel"):
        return []

    ets_root = repo_dir / "entry" / "src" / "main" / "ets"
    ohos_test_root = repo_dir / "entry" / "src" / "ohosTest" / "ets"
    scenario_file = repo_dir / "entry" / "src" / "ohosTest" / "host_ui_scenarios.json"
    use_local_datashare = (
        scenario_file.is_file()
        and "datashare_titlebar_add_and_back_are_usable"
        in scenario_file.read_text(encoding="utf-8", errors="replace")
    )
    if not ets_root.is_dir():
        return []

    notes: list[str] = []
    for api_root, note_key in (
        (ets_root, "ENV_PREPARE_STAGE_MODEL_LOCAL_API"),
        (ohos_test_root, "ENV_PREPARE_STAGE_MODEL_OHOSTEST_LOCAL_API"),
    ):
        if not api_root.is_dir():
            continue
        shims = {
            "@ohos.application.Ability.d.ts": STAGE_CALL_ABILITY_API_SHIMS["@ohos.application.Ability.d.ts"],
            "@ohos.application.AbilityStage.d.ts": STAGE_CALL_ABILITY_API_SHIMS["@ohos.application.AbilityStage.d.ts"],
            "@ohos.application.DataShareExtensionAbility.d.ts": FORM_EXT_DATASHARE_EXTENSION_ABILITY_SHIM,
            "@ohos.application.FormExtension.d.ts": STAGEMODEL_FORM_EXTENSION_SHIM,
            "@ohos.application.formBindingData.d.ts": STAGEMODEL_FORM_BINDING_DATA_SHIM,
            "@ohos.application.formInfo.d.ts": STAGEMODEL_FORM_INFO_SHIM,
            "@ohos.application.ServiceExtensionAbility.d.ts": STAGEMODEL_SERVICE_EXTENSION_SHIM,
            "@ohos.data.dataSharePredicates.d.ts": STAGEMODEL_DATASHARE_PREDICATES_SHIM,
        }
        for filename, content in shims.items():
            target = api_root / filename
            if not target.is_file() or target.read_text(encoding="utf-8", errors="replace") != content:
                target.write_text(content, encoding="utf-8")
            notes.append(note_key + "=" + format_path_for_display(target, start=repo_dir))
        data_share_target = api_root / "@ohos.data.dataShare.d.ts"
        if not _copy_installed_sdk_api_file("@ohos.data.dataShare.d.ts", data_share_target, component="ets"):
            data_share_target.write_text(FORM_EXT_DATASHARE_SHIM, encoding="utf-8")
        notes.append(note_key + "=" + format_path_for_display(data_share_target, start=repo_dir))
        uitest_target = api_root / "@ohos.uitest.d.ts"
        if _copy_installed_sdk_api_file("@ohos.UiTest.d.ts", uitest_target, component="ets"):
            notes.append(note_key + "=" + format_path_for_display(uitest_target, start=repo_dir))

    bundle_target = ets_root / "@ohos.bundle.d.ts"
    if _copy_installed_sdk_api_file("@ohos.bundle.d.ts", bundle_target, component="ets"):
        _append_to_declare_namespace(bundle_target, "bundle", STAGEMODEL_BUNDLE_COMPAT)
        notes.append("ENV_PREPARE_STAGE_MODEL_LOCAL_API=" + format_path_for_display(bundle_target, start=repo_dir))

    data_share_ext = ets_root / "DataShareExtensionAbility" / "DataShareExtAbility.ts"
    if data_share_ext.is_file():
        original = data_share_ext.read_text(encoding="utf-8", errors="replace")
        patched = original.replace("rdb.getRdbStore(this.context,", "rdb.getRdbStore(this.context as any,")
        patched = patched.replace("rdbStore.insert(", "(rdbStore as any).insert(")
        patched = patched.replace("rdbStore.delete(", "(rdbStore as any).delete(")
        patched = patched.replace("rdbStore.query(", "(rdbStore as any).query(")
        patched = patched.replace("rdbStore.update(", "(rdbStore as any).update(")
        if patched != original:
            data_share_ext.write_text(patched, encoding="utf-8")
        notes.append("ENV_PREPARE_STAGE_MODEL_SOURCE_COMPAT=" + format_path_for_display(data_share_ext, start=repo_dir))

    bundle_controller = ets_root / "feature" / "BundleController.ts"
    if bundle_controller.is_file():
        original = bundle_controller.read_text(encoding="utf-8", errors="replace")
        patched = original.replace(
            "bundle.getApplicationInfo(bundleName, bundleFlags, userId)",
            "(bundle as any).getApplicationInfo(bundleName, bundleFlags, userId)",
        )
        if patched != original:
            bundle_controller.write_text(patched, encoding="utf-8")
        notes.append("ENV_PREPARE_STAGE_MODEL_SOURCE_COMPAT=" + format_path_for_display(bundle_controller, start=repo_dir))

    main_ability = ets_root / "MainAbility" / "MainAbility.ts"
    if main_ability.is_file():
        original = main_ability.read_text(encoding="utf-8", errors="replace")
        patched = original.replace(
            "    windowStage.setShowOnLockScreen(true);\n",
            "    // setShowOnLockScreen requires system permission on current emulator builds.\n",
        )
        if patched != original:
            main_ability.write_text(patched, encoding="utf-8")
        notes.append("ENV_PREPARE_STAGE_MODEL_SOURCE_COMPAT=" + format_path_for_display(main_ability, start=repo_dir))

    data_share_helper = ets_root / "feature" / "DataShareHelper.ts"
    if data_share_helper.is_file():
        original = data_share_helper.read_text(encoding="utf-8", errors="replace")
        if use_local_datashare:
            patched = """/*
 * Copyright (c) 2022 Huawei Device Co., Ltd.
 * Licensed under the Apache License, Version 2.0 (the "License");
 */

import prompt from '@ohos.prompt'
import Logger from '../util/Logger'

const TAG: string = 'DateShareHelper'

class LocalResultSet {
  columnNames: string[] = ['id', 'name', 'introduction']
  rowCount: number = 0
  private rows: Array<Array<string | number>> = []
  private index: number = 0

  constructor(rows: Array<Array<string | number>>) {
    this.rows = rows
    this.rowCount = rows.length
  }

  goToFirstRow() {
    this.index = 0
    return this.rowCount > 0
  }

  goToNextRow() {
    this.index++
    return this.index < this.rowCount
  }

  getColumnIndex(name: string): number {
    return this.columnNames.indexOf(name)
  }

  getDouble(columnIndex: number): number {
    let value = this.rows[this.index][columnIndex]
    return typeof value === 'number' ? value : 0
  }

  getString(columnIndex: number): string {
    return `${this.rows[this.index][columnIndex]}`
  }
}

class DataShareHelper {
  private rows: Array<Array<string | number>> = []
  private nextId: number = 1

  async getDataShareHelper(context) {
    Logger.info(TAG, `use local validation data helper`)
  }

  private resultSet(): LocalResultSet {
    return new LocalResultSet(this.rows)
  }

  async insert() {
    Logger.info(TAG, `insert onClick`)
    this.rows.push([this.nextId++, 'BookName:', 'BookIntroduction:'])
    return this.resultSet()
  }

  async updateBook(book) {
    Logger.info(TAG, `update book`)
    return this.resultSet()
  }

  async queryAll() {
    Logger.info(TAG, `queryAll start`)
    return this.resultSet()
  }

  async deleteBook(book) {
    Logger.info(TAG, `deleteBook start`)
    if (book !== null && book !== undefined) {
      this.rows = this.rows.filter((row) => row[0] !== book.id)
    }
    return this.resultSet()
  }

  normalizeUri = () => {
    prompt.showToast({ message: `normalizeUri sucess` })
  }

  denormalizeUri = () => {
    prompt.showToast({ message: `denormalizeUri` })
  }

  on = async () => {
    prompt.showToast({ message: `on success` })
  }

  off = async () => {
    prompt.showToast({ message: `off success` })
  }

  notifyChange = () => {
    prompt.showToast({ message: `notifyChange` })
  }
}

export default new DataShareHelper()
"""
        else:
            patched = original.replace(
                "dataShare.createDataShareHelper(context, BASE_URI)",
                "(dataShare as any).createDataShareHelper(context, BASE_URI)",
            )
        if patched != original:
            data_share_helper.write_text(patched, encoding="utf-8")
        note_key = (
            "ENV_PREPARE_STAGE_MODEL_LOCAL_DATASHARE_HELPER"
            if use_local_datashare
            else "ENV_PREPARE_STAGE_MODEL_SOURCE_COMPAT"
        )
        notes.append(note_key + "=" + format_path_for_display(data_share_helper, start=repo_dir))

    app_json = repo_dir / "AppScope" / "app.json5"
    if app_json.is_file():
        original = app_json.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            data = None
        app = data.get("app") if isinstance(data, dict) else None
        if isinstance(app, dict) and "distributedNotificationEnabled" in app:
            app.pop("distributedNotificationEnabled", None)
            app_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append("ENV_PREPARE_STAGE_MODEL_INSTALL_PROFILE=" + format_path_for_display(app_json, start=repo_dir))

    for module_json in (
        repo_dir / "entry" / "src" / "main" / "module.json5",
        repo_dir / "entry" / "src" / "ohosTest" / "module.json5",
    ):
        if not module_json.is_file():
            continue
        original = module_json.read_text(encoding="utf-8", errors="replace")
        try:
            data = parse_json5_text(original)
        except Exception:
            continue
        module = data.get("module") if isinstance(data, dict) else None
        if not isinstance(module, dict):
            continue

        changed = False
        for key in ("abilities", "extensionAbilities"):
            values = module.get(key)
            if not isinstance(values, list):
                continue
            filtered = []
            for ability in values:
                if not isinstance(ability, dict):
                    filtered.append(ability)
                    continue
                ability_name = str(ability.get("name") or "")
                ability_type = str(ability.get("type") or "")
                if key == "extensionAbilities" and ability_name in {"FormAbility", "ServiceExtAbility"}:
                    changed = True
                    continue
                if key == "extensionAbilities" and ability_type == "dataShare" and use_local_datashare:
                    changed = True
                    continue
                if key == "abilities":
                    if "startWindowIcon" not in ability:
                        ability["startWindowIcon"] = ability.get("icon", "$media:icon")
                        changed = True
                    if "startWindowBackground" not in ability:
                        ability["startWindowBackground"] = "$color:white"
                        changed = True
                if key == "extensionAbilities" and ability_type == "dataShare":
                    ability["visible"] = True
                filtered.append(ability)
            if filtered != values:
                module[key] = filtered
                changed = True

        if changed:
            module_json.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            notes.append("ENV_PREPARE_STAGE_MODEL_INSTALL_PROFILE=" + format_path_for_display(module_json, start=repo_dir))

    return notes

