def _prepare_contact_legacy_build_shims(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/Telephony/Contact"):
        return []

    contact_component = (
        repo_dir
        / "entry"
        / "src"
        / "main"
        / "ets"
        / "MainAbility"
        / "component"
        / "Contact.ets"
    )
    notes: list[str] = []

    if contact_component.is_file():
        original = contact_component.read_text(encoding="utf-8", errors="replace")
        patched = original
        replacements = [
            ("  @State position: string = ''", "  @State contactPositionText: string = ''"),
            ("${this.contactNumber}${this.position}", "${this.contactNumber}${this.contactPositionText}"),
            ("    this.position = await resource.getString($r('app.string.contacts').id)", "    this.contactPositionText = await resource.getString($r('app.string.contacts').id)"),
        ]
        for old, new in replacements:
            patched = patched.replace(old, new)
        if patched != original:
            contact_component.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_CONTACT_LEGACY_BUILD_SHIM="
                + format_path_for_display(contact_component, start=repo_dir)
                + " renamed @State position"
            )

    ohos_test_root = repo_dir / "entry" / "src" / "ohosTest" / "ets"
    if ohos_test_root.is_dir():
        for uitest_target in (
            ohos_test_root / "@ohos.uitest.d.ts",
            ohos_test_root / "test" / "@ohos.uitest.d.ts",
            ohos_test_root / "TestAbility" / "@ohos.uitest.d.ts",
        ):
            if not uitest_target.parent.is_dir():
                continue
            if _copy_installed_sdk_api_file("@ohos.UiTest.d.ts", uitest_target, component="ets"):
                notes.append(
                    "ENV_PREPARE_CONTACT_OHOSTEST_LOCAL_API="
                    + format_path_for_display(uitest_target, start=repo_dir)
                    + " copied @ohos.UiTest.d.ts"
                )
                continue
            if (
                not uitest_target.is_file()
                or uitest_target.read_text(encoding="utf-8", errors="replace") != DISTRIBUTED_CALC_UITEST_SHIM
            ):
                uitest_target.write_text(DISTRIBUTED_CALC_UITEST_SHIM, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_CONTACT_OHOSTEST_LOCAL_API="
                + format_path_for_display(uitest_target, start=repo_dir)
                + " minimal @ohos.uitest shim"
            )

    return notes


