    target_icon = repo_dir / "entry" / "src" / "ohosTest" / "resources" / "base" / "media" / "icon.png"
    if source_icon.is_file() and (
        not target_icon.is_file()
        or hashlib.sha256(source_icon.read_bytes()).digest() != hashlib.sha256(target_icon.read_bytes()).digest()
    ):
        target_icon.parent.mkdir(parents=True, exist_ok=True)
