def _prepare_util_base64_codec_ohos_test_local_api(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/Util/UtilBase64Codec"):
        return []

    ohos_test_root = repo_dir / "entry" / "src" / "ohosTest" / "ets"
    if not ohos_test_root.is_dir():
        return []

    notes: list[str] = []
    for uitest_target in (
        ohos_test_root / "@ohos.uitest.d.ts",
        ohos_test_root / "test" / "@ohos.uitest.d.ts",
        ohos_test_root / "TestAbility" / "@ohos.uitest.d.ts",
    ):
        if not uitest_target.parent.is_dir():
            continue
        if _copy_installed_sdk_api_file("@ohos.UiTest.d.ts", uitest_target, component="ets"):
            notes.append(
                "ENV_PREPARE_UTIL_BASE64_CODEC_OHOSTEST_LOCAL_API="
                + format_path_for_display(uitest_target, start=repo_dir)
                + " copied @ohos.UiTest.d.ts"
            )
            continue
        if (
            not uitest_target.is_file()
            or uitest_target.read_text(encoding="utf-8", errors="replace") != DISTRIBUTED_CALC_UITEST_SHIM
        ):
            uitest_target.write_text(DISTRIBUTED_CALC_UITEST_SHIM, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_UTIL_BASE64_CODEC_OHOSTEST_LOCAL_API="
            + format_path_for_display(uitest_target, start=repo_dir)
            + " minimal @ohos.uitest shim"
        )

    hypium_index = repo_dir / "node_modules" / "@ohos" / "hypium" / "index.ets"
    if hypium_index.is_file():
        original = hypium_index.read_text(encoding="utf-8", errors="replace")
        patched = original
        if "interface HypiumAbilityDelegator" not in patched:
            patched = patched.replace(
                "import {describe, beforeAll, beforeEach, afterEach, afterAll, it, expect} from './src/interface'\n\n",
                "import {describe, beforeAll, beforeEach, afterEach, afterAll, it, expect} from './src/interface'\n\n"
                "interface HypiumAbilityDelegator {\n"
                "    print(text: string): void;\n"
                "    finishTest(message: string, code: number, callback: () => void): void;\n"
                "}\n\n"
                "interface HypiumAbilityDelegatorArguments {\n"
                "    parameters: Record<string, string>;\n"
                "}\n\n"
            )
        patched = patched.replace(
            "function dryRun(core, testParameters, abilityDelegator) {",
            "function dryRun(core: Core, testParameters: Record<string, string>, abilityDelegator: HypiumAbilityDelegator): boolean {",
        )
        patched = patched.replace(
            "function dryRun(core: Core, testParameters: Record<string, string>, abilityDelegator: Object): boolean {",
            "function dryRun(core: Core, testParameters: Record<string, string>, abilityDelegator: HypiumAbilityDelegator): boolean {",
        )
        patched = patched.replace("let testSuitesObj = {}", "let testSuitesObj: Record<string, Object> = {}")
        patched = patched.replace("let suitesArray = []", "let suitesArray: Array<Object> = []")
        patched = patched.replace("let itArray = []", "let itArray: Array<Object> = []")
        patched = patched.replace("let suiteName = suiteItem['description']", "let suiteName: string = suiteItem['description']")
        patched = patched.replace("let obj = {}", "let obj: Record<string, Array<Object>> = {}")
        patched = patched.replace("static setData(data) {", "static setData(data: Object): void {")
        patched = patched.replace(
            "static hypiumTest(abilityDelegator, abilityDelegatorArguments, testsuite) {",
            "static hypiumTest(abilityDelegator: HypiumAbilityDelegator, abilityDelegatorArguments: HypiumAbilityDelegatorArguments, testsuite: () => void): void {",
        )
        patched = patched.replace(
            "static hypiumTest(abilityDelegator: Object, abilityDelegatorArguments: Object, testsuite: Function): void {",
            "static hypiumTest(abilityDelegator: HypiumAbilityDelegator, abilityDelegatorArguments: HypiumAbilityDelegatorArguments, testsuite: () => void): void {",
        )
        patched = patched.replace("let testParameters = configService.translateParams(abilityDelegatorArguments.parameters)", "let testParameters: Record<string, string> = configService.translateParams(abilityDelegatorArguments.parameters)")
        if patched != original:
            hypium_index.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_UTIL_BASE64_CODEC_HYPIUM_TYPES="
                + format_path_for_display(hypium_index, start=repo_dir)
            )

    return notes


def _prepare_util_scope_ohos_test_local_api(repo_dir: Path) -> list[str]:
    normalized = repo_dir.as_posix().replace("\\", "/")
    if not normalized.endswith("/Util/UtilScope"):
        return []

    ohos_test_root = repo_dir / "entry" / "src" / "ohosTest" / "ets"
    if not ohos_test_root.is_dir():
        return []

    notes: list[str] = []
    for uitest_target in (
        ohos_test_root / "@ohos.uitest.d.ts",
        ohos_test_root / "test" / "@ohos.uitest.d.ts",
        ohos_test_root / "TestAbility" / "@ohos.uitest.d.ts",
    ):
        if not uitest_target.parent.is_dir():
            continue
        if _copy_installed_sdk_api_file("@ohos.UiTest.d.ts", uitest_target, component="ets"):
            notes.append(
                "ENV_PREPARE_UTIL_SCOPE_OHOSTEST_LOCAL_API="
                + format_path_for_display(uitest_target, start=repo_dir)
                + " copied @ohos.UiTest.d.ts"
            )
            continue
        if (
            not uitest_target.is_file()
            or uitest_target.read_text(encoding="utf-8", errors="replace") != DISTRIBUTED_CALC_UITEST_SHIM
        ):
            uitest_target.write_text(DISTRIBUTED_CALC_UITEST_SHIM, encoding="utf-8")
        notes.append(
            "ENV_PREPARE_UTIL_SCOPE_OHOSTEST_LOCAL_API="
            + format_path_for_display(uitest_target, start=repo_dir)
            + " minimal @ohos.uitest shim"
        )

    for test_source in sorted((ohos_test_root / "test").glob("*.ets")):
        original = test_source.read_text(encoding="utf-8", errors="replace")
        patched = original.replace("from '@ohos.uitest'", "from '@ohos.UiTest'")
        if patched != original:
            test_source.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_UTIL_SCOPE_OHOSTEST_UITEST_IMPORT="
                + format_path_for_display(test_source, start=repo_dir)
                + " @ohos.uitest->@ohos.UiTest"
            )

    runner = ohos_test_root / "TestRunner" / "OpenHarmonyTestRunner.ts"
    runner.parent.mkdir(parents=True, exist_ok=True)
    if runner.is_file():
        original = runner.read_text(encoding="utf-8", errors="replace")
        patched = """import TestRunner from '@ohos.application.testRunner'
import AbilityDelegatorRegistry from '@ohos.application.abilityDelegatorRegistry'

var abilityDelegator = undefined
var abilityDelegatorArguments = undefined

function translateParamsToString(parameters) {
  const keySet = new Set([
    '-s class', '-s notClass', '-s suite', '-s itName',
    '-s level', '-s testType', '-s size', '-s timeout',
    '-s package'
  ])
  let targetParams = '';
  for (const key in parameters) {
    if (keySet.has(key)) {
      targetParams += ' ' + key + ' ' + parameters[key]
    }
  }
  return targetParams.trim()
}

async function onAbilityCreateCallback() {
  console.info('onAbilityCreateCallback')
}

async function addAbilityMonitorCallback(err: any) {
  console.info('addAbilityMonitorCallback : ' + JSON.stringify(err))
}

export default class OpenHarmonyTestRunner implements TestRunner {
  constructor() {
  }

  onPrepare() {
    console.info('OpenHarmonyTestRunner OnPrepare')
  }

  onRun() {
    console.info('OpenHarmonyTestRunner onRun run')
    abilityDelegatorArguments = AbilityDelegatorRegistry.getArguments()
    abilityDelegator = AbilityDelegatorRegistry.getAbilityDelegator()

    var testAbilityName = abilityDelegatorArguments.parameters['-p'] + '.TestAbility'
    let lMonitor = {
      abilityName: testAbilityName,
      onAbilityCreate: onAbilityCreateCallback,
    };
    abilityDelegator.addAbilityMonitor(lMonitor, addAbilityMonitorCallback)
    var cmd = 'aa start -d 0 -a ' + testAbilityName + ' -b ' + abilityDelegatorArguments.bundleName
    cmd += ' ' + translateParamsToString(abilityDelegatorArguments.parameters)
    console.info('cmd : ' + cmd)
    var debug = abilityDelegatorArguments.parameters["-D"]
    if (debug == 'true') {
      cmd += ' -D'
    }
    abilityDelegator.executeShellCommand(cmd,
      (err: any, d: any) => {
        console.info('executeShellCommand : err : ' + JSON.stringify(err))
        console.info('executeShellCommand : data : ' + d.stdResult)
        console.info('executeShellCommand : data : ' + d.exitCode)
      })
    console.info('OpenHarmonyTestRunner onRun end')
  }
}
"""
        if patched != original:
            runner.write_text(patched, encoding="utf-8")
            notes.append(
                "ENV_PREPARE_UTIL_SCOPE_OHOSTEST_RUNNER="
                + format_path_for_display(runner, start=repo_dir)
                + " runs Hypium directly to avoid legacy TestAbility startup crash"
            )

    ohos_test_config = repo_dir / "entry" / "src" / "ohosTest" / "config.json"
    if ohos_test_config.is_file():
        config_data = json.loads(ohos_test_config.read_text(encoding="utf-8", errors="replace"))
        module = config_data.get("module") if isinstance(config_data, dict) else None
        runner_config = {"name": "OpenHarmonyTestRunner", "srcPath": "TestRunner"}
        if isinstance(module, dict) and module.get("testRunner") != runner_config:
            module["testRunner"] = runner_config
            ohos_test_config.write_text(
                json.dumps(config_data, ensure_ascii=False, indent=2) + "\n",
                encoding="utf-8",
            )
            _remove_preprocess_cache_path(repo_dir, repo_dir / "entry" / "build", notes)
            _remove_preprocess_cache_path(repo_dir, repo_dir / ".hvigor", notes)
            notes.append(
                "ENV_PREPARE_UTIL_SCOPE_OHOSTEST_TEST_RUNNER="
                + format_path_for_display(ohos_test_config, start=repo_dir)
                + " name=OpenHarmonyTestRunner srcPath=TestRunner"
            )

    return notes


def prepare_native_repair_environment(
    repo_dir: str | os.PathLike[str],
    deveco_path: str | os.PathLike[str],
    *,
    product_name: str = "default",
    timeout_sec: float | None = 900,
    sdk_roots: list[Path] | None = None,
    sdk_meta: dict[str, Any] | None = None,
) -> list[str]:
    """Prepare a reset-to-base ArkTS repo before repair/build/test execution."""

    resolved_repo = resolve_directory(repo_dir, "repo_dir")
    resolved_deveco = resolve_directory(deveco_path, "deveco_path")
    if sdk_roots is None or sdk_meta is None:
        sdk_roots, sdk_meta = require_sdk_roots_for_repo(
            resolved_repo,
            resolved_deveco,
            product_name=product_name,
        )

    sdk_root = sdk_roots[0] if sdk_roots else None
    sdk_api_level = sdk_meta.get("sdk_selection_api_level")
    local_properties = ensure_local_properties(
        resolved_repo,
        sdk_root=sdk_root,
        sdk_api_level=sdk_api_level,
        base_env=os.environ.copy(),
    )

    notes = [
        f"ENV_PREPARE_LOCAL_PROPERTIES={format_path_for_display(local_properties, start=resolved_repo)}",
        (
            "ENV_PREPARE_SDK="
            f"compile={sdk_meta.get('compileSdkVersion')} "
            f"compatible={sdk_meta.get('compatibleSdkVersion')} "
            f"selectedApi={sdk_api_level}"
        ),
    ]
    notes.extend(_prepare_sdk_version_string_literals(resolved_repo))
    legacy_sdk_view_notes, legacy_sdk_root = _prepare_selected_legacy_hvigor_sdk_view(
        resolved_repo,
        sdk_root,
        api_level=sdk_api_level if isinstance(sdk_api_level, int) else None,
    )
    if legacy_sdk_view_notes:
        notes.extend(legacy_sdk_view_notes)
    if legacy_sdk_root is not None and sdk_roots:
        sdk_roots[0] = legacy_sdk_root
        sdk_root = legacy_sdk_root
    else:
        sdk_api_notes = _prepare_build_profile_sdk_api_compat(resolved_repo, sdk_root, sdk_meta)
        if sdk_api_notes:
            notes.extend(sdk_api_notes)
            sdk_api_level = sdk_meta.get("sdk_selection_api_level")
    notes.extend(_prepare_legacy_hvigor_model_version(resolved_repo))
    notes.extend(_prepare_upgrade_popup_legacy_shims(resolved_repo))
    notes.extend(_prepare_app_market_legacy_shims(resolved_repo))
    notes.extend(_prepare_ijkplayer_prebuilt_har_dependency(resolved_repo))
